/** 金额显示按亿、万分组；支付金额传 exact=true 保留尾数，其余万以上截去尾数。 */
export function FormatMoney(value: number, exact: boolean = false): string {
    const amount = Math.max(0, Math.floor(Number.isFinite(value) ? value : 0));
    const yi = Math.floor(amount / 100000000);
    const wan = Math.floor(amount % 100000000 / 10000);
    const rest = exact || amount < 10000 ? amount % 10000 : 0;
    return (yi ? yi + "亿" : "") + (wan ? wan + "万" : "")
        + (rest || (!yi && !wan) ? String(rest) : "");
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, Component, easing, Label, Node, tween, Tween } from 'cc';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from '../Manager/ZRSJZ_EventManager';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_Currency')
export class ZRSJZ_Currency extends Component {

    Currency: Label = null;

    private _curTween: Tween = null;
    private _curCurrency: number = 0;

    /** 仅格式化余额显示，不修改实际金币；万以上省略尾数。 */
    public static FormatAmount(value: number): string { return FormatMoney(value); }

    protected onLoad(): void {
        this.Currency = this.node.getChildByName("Count").getComponent(Label);
    }

    protected start(): void {
        this.Show();
    }

    protected onEnable(): void {
        ZRSJZ_UIManager.Instance.AddCurrency(this.node);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE, this.Show, this);
    }

    protected onDisable(): void {
        ZRSJZ_UIManager.Instance?.RemoveCurrency(this.node);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE, this.Show, this);
    }

    Show() {
        Tween.stopAllByTarget(this._curTween);

        const object = { value: this._curCurrency };

        this._curTween = tween(object)
            .delay(0.6)
            .to(0.5, { value: ZRSJZ_GameData.Instance.Gold }, {
                onUpdate: () => {
                    this._curCurrency = object.value;
                    if (this.Currency) this.Currency.string = ZRSJZ_Currency.FormatAmount(object.value);
                }
            })
            .call(() => {
                this._curCurrency = Math.floor(ZRSJZ_GameData.Instance.Gold);
                if (this.Currency) this.Currency.string = ZRSJZ_Currency.FormatAmount(this._curCurrency);
            })
            .start();
    }

    AddCurrencyByVideo() {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        ZRSJZ_UIManager.Instance.ShowPanel(ZRSJZ_PANEL.获取金币弹窗);
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, Component, EventTouch, find, Label, Node, Sprite } from 'cc';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import Banner from 'db://assets/Scripts/Banner';
import { ZRSJZ_BoosterShotService } from '../Service/ZRSJZ_BoosterShotService';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_AccountService } from '../Service/ZRSJZ_AccountService';
import { ZRSJZ_BOOSTER_SHOT_CONFIG, ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from '../Manager/ZRSJZ_EventManager';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_BoosterShot')
export class ZRSJZ_BoosterShot extends Component {

    @property
    BoosterShotName: string = "";

    Name: Label = null;
    Desc: Label = null;
    Have: Label = null;
    BuyBtn: Node = null;
    VideoBtn: Node = null;
    UseBtn: Node = null;
    UseBtnSprite: Sprite = null;
    Used: Node = null;
    Price: Label = null;

    private _price: number = 0;
    private _curCount: number = 0;

    protected onLoad(): void {
        this.Name = find("Name", this.node).getComponent(Label);
        this.Desc = find("Tip", this.node).getComponent(Label);
        this.Have = find("Count", this.node).getComponent(Label);
        this.BuyBtn = find("钞票购买按钮", this.node);
        this.VideoBtn = find("视频按钮", this.node);
        this.UseBtn = find("使用按钮", this.node);
        this.UseBtnSprite = find("使用按钮", this.node).getComponent(Sprite);
        this.Used = find("使用中", this.node);
        this.Price = find("钞票购买按钮/Layout/Count", this.node).getComponent(Label);
    }

    protected start(): void {
        const config = ZRSJZ_BOOSTER_SHOT_CONFIG.get(this.BoosterShotName);
        if (!config) {
            console.error(`[ZRSJZ_BoosterShot] 未找到增强针配置: ${this.BoosterShotName}`);
            this.node.active = false;
            return;
        }
        this._price = config.Price;
        this.Name.string = config.Name;
        this.Desc.string = config.Desc;
        this.BuyBtn.active = config.UnlockType == "钞票";
        this.VideoBtn.active = config.UnlockType == "视频";
        this.Price.string = this.FormatAssetValue(config.Price);
        this.RefreshUI();
    }

    protected onEnable(): void {
        this.RefreshUI();
        ZRSJZ_EventManager.On(ZRSJZ_MyEvent.ZRSJZ_BOOSTER_SHOT_REFRESH, this.RefreshUI, this)
    }

    protected onDisable(): void {
        ZRSJZ_EventManager.Off(ZRSJZ_MyEvent.ZRSJZ_BOOSTER_SHOT_REFRESH, this.RefreshUI, this)
    }

    RefreshUI() {
        this._curCount = ZRSJZ_BoosterShotService.GetBoosterShotCount(this.BoosterShotName);
        this.Have.string = `已拥有：${this._curCount}`
        this.Used.active = ZRSJZ_BoosterShotService.GetCurBoosterShot() === this.BoosterShotName;
        this.UseBtn.active = ZRSJZ_BoosterShotService.GetCurBoosterShot() !== this.BoosterShotName;
        this.UseBtnSprite.grayscale = this._curCount <= 0;
    }

    OnButtonClick(event: EventTouch) {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "钞票购买按钮":
                if (ZRSJZ_GameData.Instance.Gold >= this._price) {
                    ZRSJZ_AccountService.ChangeGold(-this._price);
                    ZRSJZ_BoosterShotService.AddBoosterShot(this.BoosterShotName);
                    this.RefreshUI();
                } else {
                    ZRSJZ_UIManager.Instance.ShowTip("余额不足");
                }
                break;
            case "视频按钮":
                Banner.Instance.ShowVideoAd(() => {
                    ZRSJZ_BoosterShotService.AddBoosterShot(this.BoosterShotName);
                    this.RefreshUI();
                })
                break;
            case "使用按钮":
                if (this._curCount <= 0) {
                    void ZRSJZ_UIManager.Instance.ShowTip("当前没有可使用的增强针");
                    return;
                }
                const curBoosterShot = ZRSJZ_BoosterShotService.GetCurBoosterShot();
                if (!curBoosterShot) {
                    if (!ZRSJZ_BoosterShotService.UseBoosterShot(this.BoosterShotName)) {
                        void ZRSJZ_UIManager.Instance.ShowTip("增强针使用失败");
                    }
                } else if (curBoosterShot !== this.BoosterShotName) {
                    ZRSJZ_UIManager.Instance.ShowPanel(
                        ZRSJZ_PANEL.增强针替换弹窗,
                        this.BoosterShotName,
                    );
                }
                break;
        }
    }

    FormatAssetValue(value: number): string { return FormatMoney(value, true); }

}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { SpriteFrame } from "cc";
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from "../Manager/ZRSJZ_EventManager";
import { ZRSJZ_PROP_CONFIG } from "../ZRSJZ_Constant";
import { ZRSJZ_GameData } from "../ZRSJZ_GameData";
import { ZRSJZ_Tools } from "../ZRSJZ_Tools";

export interface ZRSJZ_GradeInfo {
    Level: number;
    CurrentExperience: number;
    RequiredExperience: number;
    Progress: number;
    IsMaxLevel: boolean;
}

export interface ZRSJZ_ExperienceAddedInfo {
    Amount: number;
    Before: ZRSJZ_GradeInfo;
    After: ZRSJZ_GradeInfo;
}

/** 等级、账号统计及等级界面展示数据。 */
export class ZRSJZ_GradeService {
    public static readonly MAX_LEVEL: number = 60;

    /**
     * 下标 0～59 对应等级 1～60；60 级为满级，因此升级需求为 0。
     * 曲线采用二次增长：前期升级轻快，20 级后逐渐拉开养成周期。
     */
    public static readonly REQUIRED_EXPERIENCE_BY_LEVEL: readonly number[] = Object.freeze([
        100, 140, 190, 260, 340, 430, 540, 660, 790, 940,
        1100, 1280, 1470, 1680, 1900, 2130, 2380, 2640, 2910, 3200,
        3500, 3820, 4150, 4500, 4860, 5230, 5620, 6020, 6430, 6860,
        7300, 7760, 8230, 8720, 9220, 9730, 10260, 10800, 11350, 11920,
        12500, 13100, 13710, 14340, 14980, 15630, 16300, 16980, 17670, 18380,
        19100, 19840, 20590, 21360, 22140, 22930, 23740, 24560, 25390, 0,
    ]);

    private static readonly _roleSpritePromises = new Map<string, Promise<SpriteFrame | null>>();
    private static _onlineTimeFraction: number = 0;
    private static _unsavedOnlineSeconds: number = 0;

    public static GetGradeInfo(): ZRSJZ_GradeInfo {
        const data = ZRSJZ_GameData.Instance;
        const level = this.ClampLevel(data.Grade);
        const isMaxLevel = level >= this.MAX_LEVEL;
        const requiredExperience = isMaxLevel ? 0 : this.GetRequiredExperience(level);
        const currentExperience = isMaxLevel
            ? 0
            : Math.max(0, Math.min(
                Math.floor(data.CurExp ?? 0),
                Math.max(0, requiredExperience - 1),
            ));
        return {
            Level: level,
            CurrentExperience: currentExperience,
            RequiredExperience: requiredExperience,
            Progress: isMaxLevel
                ? 1
                : currentExperience / Math.max(1, requiredExperience),
            IsMaxLevel: isMaxLevel,
        };
    }

    public static GetRequiredExperience(level: number): number {
        return this.REQUIRED_EXPERIENCE_BY_LEVEL[this.ClampLevel(level) - 1] ?? 0;
    }

    /** 主线任务领取时动态取值，保证奖励恰好补足当前等级。 */
    public static GetExperienceToNextLevel(): number {
        const info = this.GetGradeInfo();
        return info.IsMaxLevel
            ? 0
            : Math.max(0, info.RequiredExperience - info.CurrentExperience);
    }

    /** CurExp 保存当前等级内经验；一次增加可连续提升多级。 */
    public static AddExperience(experience: number): boolean {
        if (!Number.isFinite(experience) || experience <= 0) return false;
        const data = ZRSJZ_GameData.Instance;
        const amount = Math.floor(experience);
        if (amount <= 0) return false;
        const before = this.GetGradeInfo();
        let level = this.ClampLevel(data.Grade);
        let currentExperience = Math.max(0, Math.floor(data.CurExp ?? 0))
            + amount;

        while (level < this.MAX_LEVEL) {
            const requiredExperience = this.GetRequiredExperience(level);
            if (currentExperience < requiredExperience) break;
            currentExperience -= requiredExperience;
            level++;
        }
        if (level >= this.MAX_LEVEL) currentExperience = 0;
        data.Grade = level;
        data.CurExp = currentExperience;
        this._unsavedOnlineSeconds = 0;
        ZRSJZ_GameData.SaveData();
        const changeInfo: ZRSJZ_ExperienceAddedInfo = {
            Amount: amount,
            Before: before,
            After: this.GetGradeInfo(),
        };
        // 先通知经验动画，再发送通用刷新，避免等级 UI 先瞬间跳到最终值。
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_EXPERIENCE_ADDED, changeInfo);
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_PLAYER_INFO_CHANGE);
        return true;
    }

    public static RecordBattleStarted(): void {
        const data = ZRSJZ_GameData.Instance;
        data.TotalGamePlayed = this.SafeInteger(data.TotalGamePlayed) + 1;
        this.SaveAndNotify();
    }

    public static RecordBattleFinished(
        evacuationSuccess: boolean,
        evacuationValue: number = 0,
        battleSeconds: number = 0,
        killCount: number = 0,
        queueExperience: boolean = true,
    ): number {
        const data = ZRSJZ_GameData.Instance;
        if (evacuationSuccess) {
            data.TotalEvacuation = this.SafeInteger(data.TotalEvacuation) + 1;
            data.OptimumEvacuation = Math.max(
                this.SafeInteger(data.OptimumEvacuation),
                Math.max(0, Math.floor(evacuationValue || 0)),
            );
        }
        const battleExperience = queueExperience
            ? this.CalculateBattleExperience(battleSeconds, killCount)
            : 0;
        if (battleExperience > 0) {
            data.PendingExperience = this.SafeInteger(data.PendingExperience) + battleExperience;
        }
        this.SaveAndNotify();
        return battleExperience;
    }

    /**
     * 一局典型的10分钟、10击杀约获得当前等级需求的10%。
     * 时长最多计算15分钟、击杀最多计算15个，避免挂机和反复刷怪快速冲级。
     */
    public static CalculateBattleExperience(battleSeconds: number, killCount: number): number {
        const gradeInfo = this.GetGradeInfo();
        if (gradeInfo.IsMaxLevel) return 0;
        const seconds = Math.max(0, Math.min(15 * 60, Number(battleSeconds) || 0));
        const kills = Math.max(0, Math.min(15, Math.floor(Number(killCount) || 0)));
        if (seconds < 30 && kills <= 0) return 0;

        const timeExperience = Math.floor(
            gradeInfo.RequiredExperience * 0.004 * (seconds / 60),
        );
        const killExperience = Math.floor(
            gradeInfo.RequiredExperience * 0.006 * kills,
        );
        return Math.max(1, timeExperience + killExperience);
    }

    /** 仅在进入大厅后调用，清空暂存并通过统一入口发放经验。 */
    public static ClaimPendingExperience(): number {
        const data = ZRSJZ_GameData.Instance;
        const experience = this.SafeInteger(data.PendingExperience);
        if (experience <= 0) return 0;
        data.PendingExperience = 0;
        this.AddExperience(experience);
        return experience;
    }

    /** 主界面和局内场景共同调用，累计真实在线时间；每30秒自动落盘。 */
    public static UpdateOnlineTime(deltaTime: number): void {
        if (!Number.isFinite(deltaTime) || deltaTime <= 0) return;
        this._onlineTimeFraction += deltaTime;
        const wholeSeconds = Math.floor(this._onlineTimeFraction);
        if (wholeSeconds <= 0) return;
        this._onlineTimeFraction -= wholeSeconds;
        const data = ZRSJZ_GameData.Instance;
        data.TotalTimePlayed = this.SafeInteger(data.TotalTimePlayed) + wholeSeconds;
        this._unsavedOnlineSeconds += wholeSeconds;
        if (this._unsavedOnlineSeconds >= 30) this.FlushOnlineTime();
    }

    public static FlushOnlineTime(): void {
        if (this._unsavedOnlineSeconds <= 0) return;
        this._unsavedOnlineSeconds = 0;
        this.SaveAndNotify();
    }

    /** 当前账号全部道具价值，并额外计入收藏室中已解锁的藏品。 */
    public static GetTotalAssetValue(): number {
        const data = ZRSJZ_GameData.Instance;
        const inventoryValue = Object.values(data.PropData ?? {}).reduce(
            (total, prop) => total
                + Math.max(0, Number(prop?.UnitPrice) || 0)
                * Math.max(0, Number(prop?.CurCount) || 0),
            0,
        );
        const collectionValue = Object.entries(data.BoxroomPropLevel ?? {}).reduce(
            (total, [propName, level]) => {
                if ((Number(level) || 0) <= 0) return total;
                return total + Math.max(0, ZRSJZ_PROP_CONFIG.get(propName)?.UnitPrice ?? 0);
            },
            0,
        );
        return Math.floor(inventoryValue + collectionValue);
    }

    public static GetPropIDsValue(propIDs: readonly string[]): number {
        const data = ZRSJZ_GameData.Instance;
        return Math.floor((propIDs ?? []).reduce((total, propID) => {
            const prop = data.PropData?.[propID];
            return prop
                ? total + Math.max(0, prop.UnitPrice || 0) * Math.max(0, prop.CurCount || 0)
                : total;
        }, 0));
    }

    public static FormatPlayTime(totalSeconds: number): string {
        const totalMinutes = Math.max(0, Math.floor((Number(totalSeconds) || 0) / 60));
        const hours = Math.floor(totalMinutes / 60);
        const minutes = totalMinutes % 60;
        return hours > 0 ? `${hours}h${minutes}m` : `${minutes}m`;
    }

    public static FormatEvacuationRate(successCount: number, totalGameCount: number): string {
        const total = this.SafeInteger(totalGameCount);
        if (total <= 0) return "0.0%";
        const success = Math.min(total, this.SafeInteger(successCount));
        const percentage = success / total * 100;
        return `${percentage.toFixed(1)}%`;
    }

    public static FormatAssetValue(value: number): string { return FormatMoney(value); }

    public static GetRoleAvatar(roleName: string): Promise<SpriteFrame | null> {
        return this.LoadRoleSprite("Sprites/等级系统/头像", roleName);
    }

    public static GetRoleFrame(roleName: string): Promise<SpriteFrame | null> {
        return this.LoadRoleSprite("Sprites/等级系统/角色框", roleName);
    }

    private static ClampLevel(level: number): number {
        return Math.max(1, Math.min(this.MAX_LEVEL, Math.floor(Number(level) || 1)));
    }

    private static SafeInteger(value: number): number {
        return Math.max(0, Math.floor(Number(value) || 0));
    }

    private static SaveAndNotify(): void {
        this._unsavedOnlineSeconds = 0;
        ZRSJZ_GameData.SaveData();
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_PLAYER_INFO_CHANGE);
    }

    private static LoadRoleSprite(directory: string, roleName: string): Promise<SpriteFrame | null> {
        if (!roleName) return Promise.resolve(null);
        const key = `${directory}/${roleName}`;
        let promise = this._roleSpritePromises.get(key);
        if (!promise) {
            promise = ZRSJZ_Tools.LoadSprites(directory)
                .then(spriteFrames => spriteFrames.find(spriteFrame => spriteFrame.name === roleName) ?? null)
                .catch(error => {
                    console.error(`[ZRSJZ_GradeService] 等级角色图片加载失败: ${key}`, error);
                    this._roleSpritePromises.delete(key);
                    return null;
                });
            this._roleSpritePromises.set(key, promise);
        }
        return promise;
    }


}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, EventTouch, find, Label, Node, Sprite, SpriteFrame, UIOpacity, UITransform, Vec3 } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_INVENTORY, ZRSJZ_MAP_CONFIG, ZRSJZ_MapConfig, ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_InventoryService } from '../Service/ZRSJZ_InventoryService';
import { ZRSJZ_PoolManager } from '../Manager/ZRSJZ_PoolManager';
import { ZRSJZ_TaskAward } from '../UI/ZRSJZ_TaskAward';
import { ZRSJZ_LevelProgressService } from '../Service/ZRSJZ_LevelProgressService';
const { ccclass, property } = _decorator;

export interface ZRSJZ_LevelEntryResult {
    CanEnter: boolean;
    CurrentValue: number;
    RequiredValue: number;
    Reason: string;
}

@ccclass('ZRSJZ_SelectPanel')
export class ZRSJZ_SelectPanel extends ZRSJZ_Panel {

    @property(SpriteFrame)
    BGSFs: SpriteFrame[] = [];

    @property(SpriteFrame)
    MapSFs: SpriteFrame[] = [];

    @property(SpriteFrame)
    MapTypeSFs: SpriteFrame[] = [];

    private readonly _mapNames: string[] = ["五号小镇", "沙漠古迹", "极北之地"];
    private readonly _actionNames: string[] = ["机密行动", "绝密行动"];
    private _selectedMapName: string = "五号小镇";
    private _selectedActionName: string = "机密行动";
    private _exclusiveDropRefreshVersion: number = 0;

    private _mapEffectTime = 0;
    private _mapEffects: {
        node: Node; origin: Vec3; opacity: UIOpacity;
        ripple: Node; rippleOpacity: UIOpacity; selected: boolean; burstTime: number;
    }[] = [];

    private InitMapEffects(): void {
        for (const mapName of this._mapNames) {
            const node = find(`Panel/${mapName}`, this.node);
            const checked = node?.getChildByName("Checked");
            const source = checked?.getComponent(Sprite);
            if (!node || !checked || !source) continue;
            // 只复制描边图片，不复制锁图标、按钮和点击事件。
            const ripple = new Node("SelectionRipple");
            ripple.layer = node.layer;
            ripple.parent = node;
            ripple.setSiblingIndex(checked.getSiblingIndex());
            ripple.setPosition(checked.position);
            const transform = ripple.addComponent(UITransform);
            const sourceTransform = checked.getComponent(UITransform);
            transform.setAnchorPoint(sourceTransform.anchorPoint);
            const sprite = ripple.addComponent(Sprite);
            sprite.spriteFrame = source.spriteFrame;
            sprite.sizeMode = Sprite.SizeMode.CUSTOM;
            transform.setContentSize(sourceTransform.contentSize);
            ripple.active = false;
            this._mapEffects.push({
                node, origin: node.position.clone(),
                opacity: checked.getComponent(UIOpacity) ?? checked.addComponent(UIOpacity),
                ripple, rippleOpacity: ripple.addComponent(UIOpacity), selected: false, burstTime: 1,
            });
        }
    }

    protected update(dt: number): void {
        this._mapEffectTime += dt;
        this._mapEffects.forEach((effect, index) => {
            const phase = this._mapEffectTime * Math.PI * 2 / 3.2;
            const offset = index * Math.PI * 2 / 3;
            // 相对固定原点计算，反复开关面板也不会累积位置偏移。
            const y = 9 * (Math.sin(phase + offset) - Math.sin(offset));
            effect.node.setPosition(effect.origin.x, effect.origin.y + y, effect.origin.z);
            effect.opacity.opacity = effect.selected
                ? 205 + 50 * Math.sin(this._mapEffectTime * Math.PI * 2 / 1.6) : 255;
            if (effect.ripple.active) {
                effect.burstTime = Math.min(1, effect.burstTime + dt / 0.65);
                const progress = effect.burstTime;
                const scale = 1 + 0.18 * (1 - (1 - progress) ** 2);
                effect.ripple.setScale(scale, scale, 1);
                effect.rippleOpacity.opacity = 210 * (1 - progress);
                if (progress >= 1) effect.ripple.active = false;
            }
        });
    }

    protected onDisable(): void {
        this._mapEffectTime = 0;
        for (const effect of this._mapEffects) {
            effect.node.setPosition(effect.origin);
            effect.opacity.opacity = 255;
            effect.ripple.active = false;
            effect.selected = false;
        }
    }

    private RefreshMapEffects(): void {
        for (const effect of this._mapEffects) {
            const selected = effect.node.name === this._selectedMapName;
            if (selected && !effect.selected) {
                effect.burstTime = 0;
                effect.ripple.setScale(1, 1, 1);
                effect.rippleOpacity.opacity = 210;
                effect.ripple.active = true;
            } else if (!selected) {
                effect.ripple.active = false;
                effect.opacity.opacity = 255;
            }
            effect.selected = selected;
        }
    }

    protected onLoad(): void {
        this.InitMapEffects();
        this.BindSelectEvents();
        this.RestoreSelection();
        this.RefreshSelection();
    }

    public Show(...args: any[]): void {
        super.Show(...args);
        this.RefreshSelection();
    }

    /**
     * 预制体中的地图和行动卡片没有 Button 组件，在这里统一绑定点击事件。
     * 使用固定回调引用，保证节点销毁时能够正确解除监听。
     */
    private BindSelectEvents(): void {
        for (const mapName of this._mapNames) {
            find(`Panel/${mapName}`, this.node)?.on(Node.EventType.TOUCH_END, this.OnMapSelected, this);
        }
        for (const actionName of this._actionNames) {
            find(`Panel/${actionName}`, this.node)?.on(Node.EventType.TOUCH_END, this.OnActionSelected, this);
        }
    }

    protected onDestroy(): void {
        this._exclusiveDropRefreshVersion++;
        this.ClearExclusiveDrops();
        for (const mapName of this._mapNames) {
            find(`Panel/${mapName}`, this.node)?.off(Node.EventType.TOUCH_END, this.OnMapSelected, this);
        }
        for (const actionName of this._actionNames) {
            find(`Panel/${actionName}`, this.node)?.off(Node.EventType.TOUCH_END, this.OnActionSelected, this);
        }
    }

    public OnButtonClick(event: EventTouch): void {
        if (ZRSJZ_UIManager.Dragging) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Close":
                ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.选关界面);
                break;
            case "开始行动":
                this.TryEnterSelectedLevel();
                break;
        }
    }

    private OnMapSelected(event: EventTouch): void {
        const mapName = event.getCurrentTarget().name;
        // 当前地图已选中时，不重复刷新关卡信息和专属掉落。
        if (!this._mapNames.includes(mapName) || mapName === this._selectedMapName) return;

        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        this._selectedMapName = mapName;
        this.RefreshSelection();
    }

    private OnActionSelected(event: EventTouch): void {
        const actionName = event.getCurrentTarget().name;
        // 当前行动难度已选中时，不重复刷新关卡信息和专属掉落。
        if (!this._actionNames.includes(actionName) || actionName === this._selectedActionName) return;

        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        this._selectedActionName = actionName;
        this.RefreshSelection();
    }

    private RestoreSelection(): void {
        const config = ZRSJZ_MAP_CONFIG.get(ZRSJZ_GameData.Instance.CurMap);
        if (!config) return;

        this._selectedMapName = config.DisplayName;
        this._selectedActionName = config.ActionName;
    }

    private RefreshSelection(): void {
        this._mapNames.forEach((mapName, index) => {
            const mapNode = find(`Panel/${mapName}`, this.node);
            const checked = mapNode?.getChildByName("Checked");
            const mapKey = `${mapName}_${this._selectedActionName}`;
            const isLocked = !!ZRSJZ_LevelProgressService.GetLockReason(mapKey);
            if (checked) checked.active = mapName === this._selectedMapName && !isLocked;
            const lock = mapNode?.getChildByName("Lock");
            if (lock) lock.active = isLocked;
            const checkedLock = checked?.getChildByName("锁");
            if (checkedLock) checkedLock.active = false;
            this.SetDifficultyIcon(`Panel/${mapName}/难度`, ZRSJZ_MAP_CONFIG.get(mapKey)?.Difficulty);
            if (mapName === this._selectedMapName && this.MapSFs[index]) {
                const mapSprite = find("Panel/Desc/Map", this.node)?.getComponent(Sprite);
                if (mapSprite) mapSprite.spriteFrame = this.MapSFs[index];
            }
        });

        this.RefreshMapEffects();
        this._actionNames.forEach(actionName => {
            const actionNode = find(`Panel/${actionName}`, this.node);
            const selected = actionName === this._selectedActionName;
            const checked = actionNode?.getChildByName("Checked");
            if (checked) checked.active = selected;
        });
        const background = find("Mask", this.node)?.getComponent(Sprite);
        const backgroundFrame = this.BGSFs[this._actionNames.indexOf(this._selectedActionName)];
        if (background && backgroundFrame) background.spriteFrame = backgroundFrame;

        const config = this.GetSelectedConfig();
        const isLocked = !!ZRSJZ_LevelProgressService.GetLockReason(this.GetSelectedMapKey());
        const lock = find("Panel/Desc/Lock", this.node);
        if (lock) lock.active = isLocked;
        const startButton = find("Panel/开始行动", this.node);
        if (startButton) startButton.active = !!config && !isLocked;
        const previousLevel = ZRSJZ_LevelProgressService.GetPreviousLevel(this.GetSelectedMapKey());
        this.SetDifficultyIcon("Panel/Desc/Lock/难度", ZRSJZ_MAP_CONFIG.get(previousLevel)?.Difficulty);
        this.RefreshLevelInfo(config);
        void this.RefreshExclusiveDrops(config);
    }

    /** MapTypeSFs 依次为简单、普通、困难、专家、炼狱、末日。 */
    private SetDifficultyIcon(path: string, difficulty: number | undefined): void {
        const sprite = find(path, this.node)?.getComponent(Sprite);
        if (!sprite) return;
        const frame = difficulty ? this.MapTypeSFs[difficulty - 1] : null;
        sprite.node.active = !!frame;
        if (frame) sprite.spriteFrame = frame;
    }

    private RefreshLevelInfo(config: Readonly<ZRSJZ_MapConfig> | null): void {
        const difficulty = Math.max(0, Math.min(5, Math.floor(config?.Difficulty ?? 0)));
        const difficultyNode = find("Panel/Desc/难度", this.node);
        difficultyNode?.children.forEach((star, index) => star.active = index < difficulty);

        this.SetLabel("Panel/Desc/准入价值", config
            ? this.FormatValue(config.RequiredLoadoutValue)
            : "--");
        this.SetLabel("Panel/Desc/行动时限", config
            ? (config.TimeLimitMinutes > 0 ? `${config.TimeLimitMinutes}分钟` : "不限时")
            : "--");
    }

    /** 使用任务系统的 TaskAward 预制体展示当前关卡专属大红。 */
    private async RefreshExclusiveDrops(config: Readonly<ZRSJZ_MapConfig> | null): Promise<void> {
        const refreshVersion = ++this._exclusiveDropRefreshVersion;
        const content = find("Panel/Desc/专属掉落/View/Content", this.node);
        if (!content) {
            console.warn("[ZRSJZ_SelectPanel] 未找到专属掉落展示节点");
            return;
        }

        this.ClearExclusiveDrops(content);
        for (const propName of config?.ExclusiveRedProps ?? []) {
            const awardNode = await ZRSJZ_PoolManager.Instance.GetNode("Prefabs/UI/TaskAward");
            if (!awardNode) continue;
            if (
                refreshVersion !== this._exclusiveDropRefreshVersion
                || !content.isValid
                || !this.node.isValid
            ) {
                ZRSJZ_PoolManager.Instance.PutNode(awardNode);
                return;
            }

            const taskAward = awardNode.getComponent(ZRSJZ_TaskAward);
            if (!taskAward) {
                console.warn("[ZRSJZ_SelectPanel] TaskAward 预制体缺少 ZRSJZ_TaskAward 组件");
                ZRSJZ_PoolManager.Instance.PutNode(awardNode);
                continue;
            }
            awardNode.parent = content;
            awardNode.active = true;
            taskAward.Init(propName, 1);
        }
    }

    private ClearExclusiveDrops(content: Node = find("Panel/Desc/专属掉落/View/Content", this.node)): void {
        if (!content?.isValid) return;
        for (const child of [...content.children]) {
            if (child.getComponent(ZRSJZ_TaskAward)) {
                ZRSJZ_PoolManager.Instance.PutNode(child);
            } else {
                child.removeFromParent();
                child.destroy();
            }
        }
    }

    private SetLabel(path: string, value: string): void {
        const label = find(path, this.node)?.getComponent(Label);
        if (label) label.string = value;
    }

    private GetSelectedMapKey(): string {
        return `${this._selectedMapName}_${this._selectedActionName}`;
    }

    private GetSelectedConfig(): Readonly<ZRSJZ_MapConfig> | null {
        return ZRSJZ_MAP_CONFIG.get(this.GetSelectedMapKey()) ?? null;
    }

    /**
     * 计算玩家真正会带入局内的全部配置价值。
     * 不统计仓库和上一局尚未结算的物资，且按实例 ID 去重，避免装备数组与库存重复计价。
     */
    public GetPlayerLoadoutValue(): number {
        return ZRSJZ_SelectPanel.GetLoadoutValue(ZRSJZ_GameData.Instance.CurModel === "2p" ? [0, 1] : [0]);
    }

    /** 联机每台设备只带入玩家一的配置，不能计入本地玩家二的装备。 */
    public static GetLoadoutValue(playerIndexes: number[] = [0]): number {
        return ZRSJZ_InventoryService.GetLoadoutValue(playerIndexes);
    }

    /** 可供界面和自动化测试复用的纯准入判断，不会切换场景。 */
    public CanEnterLevel(mapKey: string = this.GetSelectedMapKey()): ZRSJZ_LevelEntryResult {
        const config = ZRSJZ_MAP_CONFIG.get(mapKey);
        const currentValue = this.GetPlayerLoadoutValue();
        if (!config) {
            return { CanEnter: false, CurrentValue: currentValue, RequiredValue: 0, Reason: "该关卡暂未开放" };
        }

        const requiredValue = Math.max(0, config.RequiredLoadoutValue || 0);
        const lockReason = ZRSJZ_LevelProgressService.GetLockReason(mapKey);
        if (lockReason) {
            return { CanEnter: false, CurrentValue: currentValue, RequiredValue: requiredValue, Reason: lockReason };
        }
        if (currentValue < requiredValue) {
            return {
                CanEnter: false,
                CurrentValue: currentValue,
                RequiredValue: requiredValue,
                Reason: `配置价值不足，还需${this.FormatValue(requiredValue - currentValue)}`,
            };
        }
        return { CanEnter: true, CurrentValue: currentValue, RequiredValue: requiredValue, Reason: "" };
    }

    private async TryEnterSelectedLevel(): Promise<void> {
        const mapKey = this.GetSelectedMapKey();
        const config = ZRSJZ_MAP_CONFIG.get(mapKey);
        if (!config) {
            ZRSJZ_UIManager.Instance.ShowTip("该关卡暂未开放");
            return;
        }
        const lockReason = ZRSJZ_LevelProgressService.GetLockReason(mapKey);
        if (lockReason) {
            ZRSJZ_UIManager.Instance.ShowTip(lockReason);
            return;
        }
        if (ZRSJZ_UIManager.ZRSJZ_DLC && mapKey === "五号小镇_机密行动") {
            ZRSJZ_UIManager.Instance.ShowPanel(
                ZRSJZ_PANEL.助战礼包弹窗,
                mapKey,
                () => void this.EnterSelectedLevel(mapKey),
            );
        } else {
            this.EnterSelectedLevel(mapKey)
        }
    }

    /** 礼包领取完成后再次校验战备价值，再正式进入关卡。 */
    private async EnterSelectedLevel(mapKey: string): Promise<void> {
        const result = this.CanEnterLevel(mapKey);
        if (!result.CanEnter) {
            ZRSJZ_UIManager.Instance.ShowTip(result.Reason);
            return;
        }
        ZRSJZ_GameData.Instance.CurMap = mapKey;
        ZRSJZ_GameData.SaveData();
        ZRSJZ_UIManager.Instance.ShowPanel(ZRSJZ_PANEL.加载界面, "ZRSJZ_Game", () => ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.选关界面));

    }

    private FormatValue(value: number): string { return FormatMoney(value); }

}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import {
    _decorator,
    Color,
    EventTouch,
    Label,
    Node,
    Sprite,
    SpriteFrame,
    UITransform,
    Widget,
    Layout,
    Tween,
    tween,
    Vec3,
    instantiate,
    isValid,
} from 'cc';
import {
    ZRSJZ_PROP_CONFIG,
    ZRSJZ_PROP_PROPERTY,
    ZRSJZ_PANEL,
} from '../ZRSJZ_Constant';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_InventoryService } from '../Service/ZRSJZ_InventoryService';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import {
    ZRSJZ_FORGE_CATEGORIES,
    ZRSJZ_FORGE_RECIPES,
    ZRSJZ_ForgeCategory,
    ZRSJZ_ForgeRecipe,
} from '../ZRSJZ_ForgeConstant';
import { ZRSJZ_ForgeService, ZRSJZ_ForgeTask } from '../Service/ZRSJZ_ForgeService';

const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_ForgePanel')
export class ZRSJZ_ForgePanel extends ZRSJZ_Panel {
    private static readonly LIST_HEIGHT = 730;

    @property(SpriteFrame)
    SelectedEquipmentBackground: SpriteFrame = null;

    private _initialized: boolean = false;
    private _normalEquipmentBackground: SpriteFrame = null;
    private _category: ZRSJZ_ForgeCategory = '枪械';
    private _selectedItemName: string = '';
    private _listContent: Node = null;
    private _itemTemplate: Node = null;
    private _tabNodes: Map<ZRSJZ_ForgeCategory, Node> = new Map();
    private _isProcessingAction: boolean = false;
    private _itemNameLabel: Label = null;
    private _itemPropertyLabel: Label = null;
    private _itemSprite: Sprite = null;
    private _floatTween: Tween<Node> = null;
    private _floatOrigin: Vec3 = null;
    private _materialContent: Node = null;
    private _materialTemplate: Node = null;
    private _goldLabel: Label = null;
    private _timeLabel: Label = null;
    private _progressRoot: Node = null;
    private _progressSprite: Sprite = null;
    private _progressLabel: Label = null;
    private _actionButton: Node = null;
    private _actionButtonLabel: Label = null;
    private _statusLabel: Label = null;
    private _tickElapsed: number = 0;
    private _lastTaskName: string = '';
    private _lastReady: boolean = false;

    protected onLoad(): void {
        this.InitializeRuntime();
    }

    protected onEnable(): void {
        this.InitializeRuntime().then(() => {
            if (!isValid(this.node) || !this.enabledInHierarchy) return;
            this.RefreshAll();
            this.StartEquipmentFloat();
        });
    }

    protected onDisable(): void {
        this.StopEquipmentFloat();
    }

    protected onDestroy(): void {
        this.StopEquipmentFloat();
    }

    private StartEquipmentFloat(): void {
        const node = this._itemSprite?.node;
        if (!isValid(node) || this._floatTween) return;
        this._floatOrigin = node.position.clone();
        const top = this._floatOrigin.clone();
        top.y += 30;
        this._floatTween = tween(node)
            .to(2.4, { position: top }, { easing: 'sineInOut' })
            .to(2.4, { position: this._floatOrigin.clone() }, { easing: 'sineInOut' })
            .union().repeatForever().start();
    }

    private StopEquipmentFloat(): void {
        this._floatTween?.stop();
        this._floatTween = null;
        if (this._floatOrigin && isValid(this._itemSprite?.node)) {
            this._itemSprite.node.setPosition(this._floatOrigin);
        }
        this._floatOrigin = null;
    }

    protected update(deltaTime: number): void {
        this._tickElapsed += deltaTime;
        if (this._tickElapsed < 0.25 || !this._initialized) return;
        this._tickElapsed = 0;

        const task = ZRSJZ_ForgeService.GetTask();
        const taskName = task?.itemName ?? '';
        const ready = ZRSJZ_ForgeService.IsReady(task);
        if (taskName !== this._lastTaskName || ready !== this._lastReady) {
            this.RefreshAll();
            return;
        }
        this.RefreshProgress(task);
        this.RefreshAction(task);
    }

    public Show(...args: any[]): void {
        this.PlayerIndex = args[0] === 1 ? 1 : 0;
        super.Show();
        this.InitializeRuntime().then(() => this.RefreshAll());
    }

    public OnButtonClick(event: EventTouch): void {
        this.PlayClick();
        if (event.getCurrentTarget().name === '返回') {
            ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.锻造界面);
        }
    }

    private InitializeRuntime(): Promise<void> {
        if (this._initialized) return Promise.resolve();
        if (!isValid(this.node) || !this.BindView()) return Promise.resolve();
        this._initialized = true;
        this._selectedItemName = this.GetCategoryRecipes()[0]?.itemName ?? '';
        this.RefreshAll();
        return Promise.resolve();
    }

    private BindView(): boolean {
        const panel = this.node.getChildByName('Panel');
        const root = panel?.getChildByName('锻造内容');
        if (!root) return false;

        this._tabNodes.clear();
        ZRSJZ_FORGE_CATEGORIES.forEach(category => {
            const tab = root.getChildByName(category);
            if (!tab) return;
            tab.off(Node.EventType.TOUCH_END, undefined, this);
            tab.on(Node.EventType.TOUCH_END, () => this.SelectCategory(category), this);
            this._tabNodes.set(category, tab);
        });

        const listFrame = root.getChildByName('装备列表框');
        const viewport = listFrame?.getChildByName('装备列表');
        this._listContent = viewport?.getChildByName('content') ?? null;
        this.ConfigureListSizing();
        this._itemTemplate = this._listContent?.getChildByName('装备条目模板') ?? null;
        this._normalEquipmentBackground = this._itemTemplate
            ?.getChildByName('装备底')?.getComponent(Sprite)?.spriteFrame ?? null;
        this._itemNameLabel = root.getChildByName('装备名称')?.getComponent(Label) ?? null;
        this._itemPropertyLabel = root.getChildByName('装备属性')?.getComponent(Label) ?? null;
        this._itemSprite = root.getChildByName('锻造装备')?.getComponent(Sprite) ?? null;

        this._progressRoot = root.getChildByName('锻造进度');
        this._progressSprite = this._progressRoot?.getChildByName('进度条')?.getComponent(Sprite) ?? null;
        this._progressLabel = this._progressRoot?.getChildByName('进度文本')?.getComponent(Label) ?? null;

        const materials = root.getChildByName('所需材料');
        this._materialContent = materials?.getChildByName('材料内容') ?? null;
        this._materialTemplate = this._materialContent?.getChildByName('材料格模板') ?? null;
        const cost = root.getChildByName('货币时间底');
        this._goldLabel = cost?.getChildByName('货币数量')?.getComponent(Label) ?? null;
        this._timeLabel = cost?.getChildByName('时间数量')?.getComponent(Label) ?? null;

        this._actionButton = root.getChildByName('开始锻造');
        this._actionButtonLabel = this._actionButton?.getChildByName('按钮文字')?.getComponent(Label) ?? null;
        this._statusLabel = root.getChildByName('状态文字')?.getComponent(Label) ?? null;
        if (this._actionButton) {
            this._actionButton.off(Node.EventType.TOUCH_END, this.OnAction, this);
            this._actionButton.on(Node.EventType.TOUCH_END, this.OnAction, this);
        }
        if (this._progressSprite) this.ConfigureProgressSprite();

        const bound = !!(
            this._listContent && this._itemTemplate && this._itemSprite && this._materialContent
            && this._materialTemplate && this._goldLabel && this._timeLabel
            && this._progressRoot && this._progressSprite && this._progressLabel
            && this._actionButton && this._actionButtonLabel && this._statusLabel
        );
        // 装备名称/装备属性是旧版右侧文本，新预制体可以不保留。
        // 只有完整绑定成功后才隐藏模板，避免绑定失败时整个列表变空。
        if (bound) this._itemTemplate.active = false;
        return bound;
    }

    private ConfigureListSizing(): void {
        if (!this._listContent) return;
        // RefreshList owns item positions and content height. A stretch-height Widget
        // would overwrite that height during the first engine layout pass.
        const widget = this._listContent.getComponent(Widget);
        if (widget) {
            widget.isAlignBottom = false;
            widget.updateAlignment();
        }
        const layout = this._listContent.getComponent(Layout);
        if (layout) layout.enabled = false;
    }

    private ConfigureProgressSprite(): void {
        this._progressSprite.type = Sprite.Type.FILLED;
        this._progressSprite.fillType = Sprite.FillType.HORIZONTAL;
        this._progressSprite.fillStart = 0;
        this._progressSprite.fillRange = 0;
    }

    private SelectCategory(category: ZRSJZ_ForgeCategory): void {
        this.PlayClick();
        this._category = category;
        this._selectedItemName = this.GetCategoryRecipes()[0]?.itemName ?? '';
        this.RefreshAll();
    }

    private SelectRecipe(recipe: ZRSJZ_ForgeRecipe): void {
        this.PlayClick();
        this._selectedItemName = recipe.itemName;
        this.RefreshAll();
    }

    private RefreshAll(): void {
        if (!this._initialized) return;
        const task = ZRSJZ_ForgeService.GetTask();
        this._lastTaskName = task?.itemName ?? '';
        this._lastReady = ZRSJZ_ForgeService.IsReady(task);
        this.RefreshTabs();
        this.RefreshList(task);
        this.RefreshDetail(task);
        this.RefreshProgress(task);
        this.RefreshAction(task);
    }

    private RefreshTabs(): void {
        this._tabNodes.forEach((node, category) => {
            const selected = category === this._category;
            const selectedBackground = node.getChildByName('选中底');
            const normalBackground = node.getChildByName('未选中');
            if (selectedBackground) selectedBackground.active = selected;
            if (normalBackground) normalBackground.active = !selected;
        });
    }

    private RefreshList(task: ZRSJZ_ForgeTask): void {
        if (!this._listContent || !this._itemTemplate) return;
        this._listContent.children.slice().forEach(row => {
            if (row === this._itemTemplate) return;
            row.removeFromParent();
            row.destroy();
        });
        const recipes = this.GetCategoryRecipes();
        const contentTransform = this._listContent.getComponent(UITransform);
        const templateTransform = this._itemTemplate.getComponent(UITransform);
        const viewportHeight = this._listContent.parent?.getComponent(UITransform)?.height
            ?? ZRSJZ_ForgePanel.LIST_HEIGHT;
        const rowHeight = templateTransform?.height ?? 112;
        const rowSpacing = 20;
        const rowStep = rowHeight + rowSpacing;
        const contentHeight = Math.max(
            viewportHeight,
            recipes.length * rowStep + rowSpacing,
        );
        contentTransform.setContentSize(
            contentTransform.width,
            contentHeight,
        );
        const templateX = this._itemTemplate.position.x;
        const templateY = this._itemTemplate.position.y;

        recipes.forEach((recipe, index) => {
            const row = instantiate(this._itemTemplate);
            row.name = recipe.itemName;
            row.active = true;
            this._listContent.addChild(row);
            row.setPosition(templateX, templateY - index * rowStep);
            row.on(Node.EventType.TOUCH_END, () => this.SelectRecipe(recipe), this);

            const selected = recipe.itemName === this._selectedItemName;
            const background = row.getChildByName('装备底')?.getComponent(Sprite);
            if (background) {
                background.spriteFrame = selected && this.SelectedEquipmentBackground
                    ? this.SelectedEquipmentBackground
                    : this._normalEquipmentBackground;
            }
            const iconRoot = row.getChildByName('装备图标');
            const qualityFrame = iconRoot?.getChildByName('品质框')?.getComponent(Sprite);
            this.LoadMaterialGridSprite(qualityFrame, recipe.itemName);
            // Keep the quality frame fixed while fitting the equipment image independently.
            const icon = iconRoot?.getChildByName('图标')?.getComponent(Sprite)
                ?? iconRoot?.getComponent(Sprite);
            const iconTransform = icon?.node.getComponent(UITransform);
            this.LoadPropSprite(
                icon,
                recipe.itemName,
                iconTransform?.width ?? 88,
                iconTransform?.height ?? 88,
            );

            const name = row.getChildByName('名称')?.getComponent(Label);
            if (name) {
                name.string = recipe.itemName;
            }
            const property = row.getChildByName('属性')?.getComponent(Label);
            if (property) {
                property.string = this.GetPrimaryPropertyName(recipe);
            }
            const propertyValue = row.getChildByName('属性值')?.getComponent(Label);
            if (propertyValue) {
                propertyValue.string = this.GetPrimaryPropertyValue(recipe);
            }

            const forgeTag = row.getChildByName('锻造标签')?.getComponent(Label);
            if (forgeTag) {
                forgeTag.node.active = task?.itemName === recipe.itemName;
                const status = ZRSJZ_ForgeService.IsReady(task) ? '可领取' : '锻造中';
                forgeTag.string = status;
                forgeTag.color = ZRSJZ_ForgeService.IsReady(task)
                    ? new Color(80, 255, 117)
                    : new Color(255, 166, 40);
            }
        });
    }

    private RefreshDetail(task: ZRSJZ_ForgeTask): void {
        const recipe = this.GetSelectedRecipe();
        if (!recipe) return;

        if (this._itemNameLabel) this._itemNameLabel.string = recipe.itemName;
        if (this._itemPropertyLabel) {
            this._itemPropertyLabel.string = this.GetPrimaryPropertyName(recipe)
                + ' ' + this.GetPrimaryPropertyValue(recipe)
                + '    价值 ' + this.FormatValue(recipe.value);
        }
        this.LoadPropSprite(this._itemSprite, recipe.itemName, 390, 260);
        this._goldLabel.string = FormatMoney(recipe.goldCost, true);
        this._timeLabel.string = recipe.durationHours + '小时';

        this._materialContent.children.slice().forEach(slot => {
            if (slot === this._materialTemplate) return;
            slot.removeFromParent();
            slot.destroy();
        });
        const slotCount = 6;
        const gap = Math.min(145, 790 / slotCount);
        const startX = -(slotCount - 1) * gap * 0.5;
        for (let index = 0; index < slotCount; index++) {
            const material = recipe.materials[index];
            const slot = instantiate(this._materialTemplate);
            slot.name = material ? material.name : '空材料槽' + (index + 1);
            slot.active = true;
            this._materialContent.addChild(slot);
            slot.setPosition(startX + index * gap, 0);

            const emptySlot = slot.getChildByName('空槽');
            const grid = slot.getChildByName('格子');
            const icon = slot.getChildByName('图标')?.getComponent(Sprite);
            const countLabel = slot.getChildByName('数量')?.getComponent(Label);

            if (!material) {
                if (emptySlot) emptySlot.active = true;
                if (grid) grid.active = false;
                if (icon) {
                    (icon as any).__forgePropName = '';
                    icon.spriteFrame = null;
                    icon.node.active = false;
                }
                if (countLabel) countLabel.node.active = false;
                continue;
            }

            slot.on(
                Node.EventType.TOUCH_END,
                () => this.ShowMaterialDetail(material.name),
                this,
            );

            if (emptySlot) emptySlot.active = false;
            if (grid) {
                grid.active = true;
                this.LoadMaterialGridSprite(grid.getComponent(Sprite), material.name);
            }
            if (icon) {
                icon.node.active = true;
                const iconTransform = icon.node.getComponent(UITransform);
                this.LoadPropSprite(
                    icon,
                    material.name,
                    iconTransform?.width ?? 82,
                    iconTransform?.height ?? 82,
                );
            }
            if (countLabel) {
                const owned = ZRSJZ_InventoryService.GetPropCountByName(material.name);
                countLabel.node.active = true;
                countLabel.string = owned + '/' + material.count;
                countLabel.color = owned >= material.count
                    ? Color.BLACK
                    : new Color(255, 84, 67);
            }
        }
    }

    private ShowMaterialDetail(propName: string): void {
        if (!ZRSJZ_PROP_CONFIG.has(propName)) return;
        this.PlayClick();
        ZRSJZ_UIManager.Instance.ShowPlayerPanel(
            ZRSJZ_PANEL.道具弹窗,
            this.PlayerIndex,
            propName,
            this.PlayerIndex,
        );
    }

    private RefreshProgress(task: ZRSJZ_ForgeTask): void {
        const recipe = this.GetSelectedRecipe();
        if (!task || !recipe || task.itemName !== recipe.itemName) {
            this._progressRoot.active = false;
            return;
        }
        this._progressRoot.active = true;
        const progress = ZRSJZ_ForgeService.GetProgress(task);
        this._progressSprite.fillRange = progress;
        this._progressLabel.string = '进度: ' + Math.floor(progress * 100) + '%';
    }

    private RefreshAction(task: ZRSJZ_ForgeTask): void {
        const recipe = this.GetSelectedRecipe();
        if (!recipe) return;

        if (!task) {
            this._actionButton.active = true;
            this._statusLabel.node.active = false;
            this._actionButtonLabel.string = '开始锻造';
            return;
        }

        if (task.itemName !== recipe.itemName) {
            this._actionButton.active = false;
            this._statusLabel.node.active = true;
            this._statusLabel.string = '其他装备正在锻造中';
            this._statusLabel.color = new Color(255, 194, 47);
            return;
        }

        if (ZRSJZ_ForgeService.IsReady(task)) {
            this._actionButton.active = true;
            this._statusLabel.node.active = false;
            this._actionButtonLabel.string = '领取';
            return;
        }

        this._actionButton.active = false;
        this._statusLabel.node.active = true;
        this._statusLabel.string = '锻造中…\n剩余 ' + this.FormatDuration(
            ZRSJZ_ForgeService.GetRemainingMilliseconds(task),
        );
        this._statusLabel.color = new Color(255, 172, 38);
    }

    private async OnAction(): Promise<void> {
        if (this._isProcessingAction) return;
        const recipe = this.GetSelectedRecipe();
        if (!recipe) return;
        this._isProcessingAction = true;
        this.PlayClick();

        try {
            const task = ZRSJZ_ForgeService.GetTask();
            const result = task
                ? ZRSJZ_ForgeService.Claim()
                : ZRSJZ_ForgeService.Start(recipe);
            if (result.success && result.createdPropIDs?.length > 0) {
                const mailAwards = await ZRSJZ_UIManager.Instance.ReceiveExistingProps(
                    result.createdPropIDs,
                );
                if (mailAwards.length > 0) {
                    result.message += '，仓库已满，装备已发送至邮件';
                }
            }
            void ZRSJZ_UIManager.Instance.ShowTip(result.message);
            this.RefreshAll();
        } finally {
            this._isProcessingAction = false;
        }
    }

    private GetCategoryRecipes(): readonly ZRSJZ_ForgeRecipe[] {
        return ZRSJZ_FORGE_RECIPES.filter(recipe => recipe.category === this._category);
    }

    private GetSelectedRecipe(): ZRSJZ_ForgeRecipe | null {
        return ZRSJZ_FORGE_RECIPES.find(
            recipe => recipe.itemName === this._selectedItemName,
        ) ?? null;
    }

    private GetPrimaryPropertyName(recipe: ZRSJZ_ForgeRecipe): string {
        if (recipe.propType === '枪' || recipe.propType === '刀') return '攻击力';
        if (recipe.propType === '头盔' || recipe.propType === '防弹衣') return '减伤';
        if (recipe.propType === '背包') return '容量';
        return recipe.propType;
    }

    private GetPrimaryPropertyValue(recipe: ZRSJZ_ForgeRecipe): string {
        const properties = ZRSJZ_PROP_PROPERTY.get(recipe.itemName) ?? {};
        if (recipe.propType === '枪' || recipe.propType === '刀') {
            return String(properties['伤害'] ?? 0);
        }
        if (recipe.propType === '头盔' || recipe.propType === '防弹衣') {
            return String(properties['减伤'] ?? 0) + '%';
        }
        if (recipe.propType === '背包') {
            const capacity = Number(properties['容量'] ?? 0);
            const columns = 4;
            return Math.ceil(capacity / columns) + '*' + columns;
        }
        return '';
    }

    private FormatValue(value: number): string { return FormatMoney(value); }

    private FormatDuration(milliseconds: number): string {
        const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor(totalSeconds % 3600 / 60);
        const seconds = totalSeconds % 60;
        return [hours, minutes, seconds]
            .map(value => value.toString().padStart(2, '0'))
            .join(':');
    }

    private LoadMaterialGridSprite(sprite: Sprite, propName: string): void {
        if (!sprite) return;
        const quality = ZRSJZ_PROP_CONFIG.get(propName)?.Quality;
        if (!quality) {
            sprite.spriteFrame = null;
            return;
        }
        const gridName = quality + '1_1';
        (sprite as any).__forgeGridName = gridName;
        ZRSJZ_UIManager.Instance.GetPropGridUI(gridName)?.then(spriteFrame => {
            if (!spriteFrame || !isValid(sprite?.node)) return;
            if ((sprite as any).__forgeGridName !== gridName) return;
            sprite.spriteFrame = spriteFrame;
            sprite.sizeMode = Sprite.SizeMode.CUSTOM;
        }).catch(error => {
            console.warn('[ZRSJZ_ForgePanel] 材料格子加载失败: ' + gridName, error);
        });
    }

    private LoadPropSprite(
        sprite: Sprite,
        propName: string,
        maxWidth: number,
        maxHeight: number,
    ): void {
        if (!sprite) return;
        (sprite as any).__forgePropName = propName;
        ZRSJZ_UIManager.Instance.GetPropUI(propName)?.then(spriteFrame => {
            if (!spriteFrame || !isValid(sprite?.node)) return;
            if ((sprite as any).__forgePropName !== propName) return;
            sprite.spriteFrame = spriteFrame;
            sprite.sizeMode = Sprite.SizeMode.CUSTOM;
            const original = spriteFrame.originalSize;
            const scale = Math.min(
                maxWidth / Math.max(1, original.width),
                maxHeight / Math.max(1, original.height),
            );
            sprite.node.getComponent(UITransform)?.setContentSize(
                original.width * scale,
                original.height * scale,
            );
        }).catch(error => {
            console.warn('[ZRSJZ_ForgePanel] 道具图片加载失败: ' + propName, error);
        });
    }

    private PlayClick(): void {
        ZRSJZ_AudioManager.Instance?.PlaySound('点击');
    }

}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, Button, Color, Label, Node, ScrollView, Sprite, SpriteFrame, UITransform, Vec2 } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_ENHANCEMENT_NODES, ZRSJZ_ENHANCEMENT_STATS, EnhancementStat } from '../ZRSJZ_EnhancementConfig';
import { ZRSJZ_EnhancementService as Upgrade } from '../Service/ZRSJZ_EnhancementService';
import { ZRSJZ_InventoryService } from '../Service/ZRSJZ_InventoryService';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_PoolManager } from '../Manager/ZRSJZ_PoolManager';
import { ZRSJZ_TaskAward } from '../UI/ZRSJZ_TaskAward';
const { ccclass, property } = _decorator;

/** 路线与详情节点保存在预制体中；运行时仅绑定交互、更新显示。 */
@ccclass('ZRSJZ_UpgradePanel')
export class ZRSJZ_UpgradePanel extends ZRSJZ_Panel {
    @property(SpriteFrame) NormalFrame: SpriteFrame = null;
    @property(SpriteFrame) OwnedFrame: SpriteFrame = null;
    @property(SpriteFrame) LevelFrame: SpriteFrame = null;
    @property(SpriteFrame) OwnedLevelFrame: SpriteFrame = null;
    @property(SpriteFrame) LineFrame: SpriteFrame = null;
    @property(SpriteFrame) OwnedLineFrame: SpriteFrame = null;
    @property(SpriteFrame) DottedFrame: SpriteFrame = null;
    @property(SpriteFrame) OwnedDottedFrame: SpriteFrame = null;
    private selected = 'main_1';
    private version = 0;
    private route = new Map<string, Node>();
    private scroll: ScrollView = null;
    private refreshClock = 0;
    private signature = '';
    private materialAwards: ZRSJZ_TaskAward[] = [];
    private materialSetup: Promise<void> = null;
    private static readonly ENOUGH = new Color(0, 255, 0);
    private static readonly LACK = new Color(255, 0, 0);

    private At(path: string): Node { return this.node.getChildByPath(`Panel/${path}`); }
    private Text(path: string, text: string): Label {
        const label = this.At(path).getComponent(Label); label.string = text; return label;
    }
    protected onLoad(): void {
        this.scroll = this.At('Tree/Scroll').getComponent(ScrollView);
        this.At('Close').on(Button.EventType.CLICK, () => {
            ZRSJZ_AudioManager.Instance?.PlaySound('点击');
            ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.强化界面);
        }, this);
        this.At('Desc/Upgrade').on(Button.EventType.CLICK, this.Purchase, this);
        for (const config of ZRSJZ_ENHANCEMENT_NODES) {
            const node = this.At(`Tree/Scroll/View/Content/Row_${config.Level}/${config.ID}`);
            this.route.set(config.ID, node);
            node.on(Button.EventType.CLICK, () => {
                this.selected = config.ID;
                ZRSJZ_AudioManager.Instance?.PlaySound('点击');
                this.Refresh();
            }, this);
        }
        void this.EnsureMaterialAwards();
    }
    Show(): void {
        super.Show();
        this.selected = `main_${Math.min(50, Upgrade.Level + 1)}`;
        this.Refresh();
        this.scheduleOnce(() => {
            if (!this.node.activeInHierarchy) return;
            const max = this.scroll.getMaxScrollOffset().y;
            this.scroll.scrollToOffset(new Vec2(0, Math.max(0, Math.min(max, max - Math.max(0, Upgrade.Level - 1) * 210))), 0);
        }, 0);
    }
    protected onDisable(): void { this.version++; this.unscheduleAllCallbacks(); }
    protected update(dt: number): void {
        this.refreshClock += dt;
        if (this.refreshClock < 0.5) return;
        this.refreshClock = 0;
        const config = Upgrade.GetNode(this.selected);
        const signature = `${Upgrade.FreeUpgradeEnabled}:${Upgrade.Level}:${ZRSJZ_GameData.Instance.Gold}:${(ZRSJZ_GameData.Instance.EnhancementSpecials ?? []).join(',')}:${config.Materials.map(m => ZRSJZ_InventoryService.GetPropCountByName(m.PropName)).join(',')}`;
        if (signature !== this.signature) { this.signature = signature; this.Refresh(); }
    }
    private Purchase(): void {
        const result = Upgrade.Purchase(this.selected);
        ZRSJZ_AudioManager.Instance?.PlaySound('点击');
        ZRSJZ_UIManager.Instance.ShowTip(result || '强化成功！');
        this.Refresh();
    }
    private Refresh(): void {
        ++this.version;
        this.Text('Progress', `强化等级  ${Upgrade.Level} / 50`);
        (Object.keys(ZRSJZ_ENHANCEMENT_STATS) as EnhancementStat[]).forEach((stat, index) =>
            this.Text(`Bonuses/Stat${index}`, `${stat}  ${Upgrade.Format(stat, Upgrade.GetBonus(stat))}`));
        for (const config of ZRSJZ_ENHANCEMENT_NODES) {
            const node = this.route.get(config.ID), owned = Upgrade.IsOwned(config);
            node.getComponent(Sprite).spriteFrame = owned ? this.OwnedFrame : this.NormalFrame;
            node.getChildByName('Icon').active = owned || Upgrade.IsAvailable(config);
            const grayIcon = node.getChildByName('GrayIcon');
            grayIcon.active = !owned && !Upgrade.IsAvailable(config);
            this.FitIcon(node.getChildByName('Icon'));
            this.FitIcon(grayIcon);
            node.getChildByName('Selected').active = this.selected === config.ID;
            node.getChildByName('Value').getComponent(Label).string = Upgrade.Format(config.Stat, config.Value);
            node.getChildByName('Status').getComponent(Label).string = config.Special ? (owned ? '已强化' : Upgrade.IsAvailable(config) ? '可强化' : '特殊强化') : '';
            if (config.Special) node.parent.getChildByName('Branch').getComponent(Sprite).spriteFrame = owned ? this.OwnedLineFrame : this.LineFrame;
            if (!config.Special) {
                const row = node.parent;
                const dotted = row.getChildByName('Dotted')?.getComponent(Sprite);
                if (dotted) {
                    dotted.sizeMode = Sprite.SizeMode.TRIMMED;
                    // Dotted 位于当前等级与下一等级之间；下一等级完成后才高亮。
                    dotted.spriteFrame = config.Level < Upgrade.Level
                        ? this.OwnedDottedFrame
                        : this.DottedFrame;
                }
                row.getChildByName('Level').getComponent(Sprite).spriteFrame = owned ? this.OwnedLevelFrame : this.LevelFrame;
                const line = row.getChildByName('Line');
                if (line) line.getComponent(Sprite).spriteFrame = config.Level < Upgrade.Level ? this.OwnedLineFrame : this.LineFrame;
            }
        }
        const config = Upgrade.GetNode(this.selected), owned = Upgrade.IsOwned(config), available = Upgrade.IsAvailable(config);
        const stat = ZRSJZ_ENHANCEMENT_STATS[config.Stat];
        const statLevel = ZRSJZ_ENHANCEMENT_NODES.filter(n => n.Stat === config.Stat && n.Level <= config.Level).length;
        this.Text('Desc/Title', `${config.Stat}强化 Lv.${statLevel}`);
        this.At('Desc/Icon').getComponent(Sprite).spriteFrame = this.route.get(config.ID).getChildByName('Icon').getComponent(Sprite).spriteFrame;
        this.FitIcon(this.At('Desc/Icon'), 90, 96);
        this.Text('Desc/Category', `${config.Special ? '特殊强化' : '基础强化'} · 路线 Lv.${config.Level}`);
        this.Text('Desc/Gain', `本次提升  ${Upgrade.Format(config.Stat, config.Value)}`);
        this.Text('Desc/Total', owned ? `当前累计  ${Upgrade.Format(config.Stat, Upgrade.GetBonus(config.Stat))}`
            : `累计 ${Upgrade.Format(config.Stat, Upgrade.GetBonus(config.Stat))} → ${Upgrade.Format(config.Stat, Upgrade.GetBonus(config.Stat) + config.Value)}`);
        this.Text('Desc/Description', stat.Description);
        const free = Upgrade.FreeUpgradeEnabled, gold = free ? 0 : config.Gold;
        this.Text('Desc/Gold', `${this.Money(ZRSJZ_GameData.Instance.Gold)} / ${FormatMoney(gold, true)}`).color = ZRSJZ_GameData.Instance.Gold >= gold ? ZRSJZ_UpgradePanel.ENOUGH : ZRSJZ_UpgradePanel.LACK;
        this.Text('Desc/Requirement', owned ? '该强化已永久生效' : available ? (free ? '本次游戏免费：免材料、免金币' : '消耗以下材料与金币') : config.Special ? `强化达到 Lv.${config.Level} 后可解锁` : `需先完成路线 Lv.${config.Level - 1}`);
        this.Text('Desc/Upgrade/Text', owned ? '已强化' : available ? (free ? '免费强化' : '解锁') : '未解锁');
        const upgradeButton = this.At('Desc/Upgrade');
        upgradeButton.getComponent(Button).interactable = available;
        // 不可点击时隐藏按钮底图，状态文字仍然显示。
        upgradeButton.getComponent(Sprite).enabled = available;
        config.Materials.forEach((material, index) => {
            const count = ZRSJZ_InventoryService.GetPropCountByName(material.PropName);
            const award = this.materialAwards[index];
            if (!award) { void this.EnsureMaterialAwards(); return; }
            const required = free ? 0 : material.Count;
            award.Init(material.PropName, required, `EnhancementMaterial${index}`);
            award.Count.string = `${count}/${required}`;
            award.Count.color = count >= required ? ZRSJZ_UpgradePanel.ENOUGH : ZRSJZ_UpgradePanel.LACK;
        });
    }
    /** 保留图片裁剪后的真实宽高，只做等比缩放；切换图片后重新适配。 */
    private FitIcon(node: Node, width = 90, height = 90): void {
        const sprite = node.getComponent(Sprite), frame = sprite.spriteFrame;
        if (!frame || frame.rect.width <= 0 || frame.rect.height <= 0) return;
        sprite.type = Sprite.Type.SIMPLE;
        sprite.trim = true;
        sprite.sizeMode = Sprite.SizeMode.TRIMMED;
        // 已经是 TRIMMED 时 setter 不会更新旧预制体里残留的自定义尺寸。
        node.getComponent(UITransform).setContentSize(frame.rect.width, frame.rect.height);
        const scale = Math.min(width / frame.rect.width, height / frame.rect.height);
        node.setScale(scale, scale, 1);
    }
    /** Material0/1 只作为定位容器，实际外观和异步图标加载统一复用 TaskAward。 */
    private EnsureMaterialAwards(): Promise<void> {
        if (this.materialAwards.length === 2) return Promise.resolve();
        if (this.materialSetup) return this.materialSetup;
        this.materialSetup = Promise.all([0, 1].map(async index => {
            const holder = this.At(`Desc/Material${index}`);
            holder.getComponent(Sprite).enabled = false;
            holder.children.forEach(child => child.active = false);
            const node = await ZRSJZ_PoolManager.Instance.GetNode('Prefabs/UI/TaskAward');
            if (!this.node?.isValid) { ZRSJZ_PoolManager.Instance.PutNode(node); return; }
            node.name = `TaskAward${index}`;
            node.setParent(holder);
            node.setPosition(0, 0);
            node.setScale(0.95, 0.95);
            node.active = true;
            this.materialAwards[index] = node.getComponent(ZRSJZ_TaskAward);
        })).then(() => { if (this.node?.isValid && this.node.activeInHierarchy) this.Refresh(); })
            .finally(() => { this.materialSetup = null; });
        return this.materialSetup;
    }
    private Money(value: number): string { return FormatMoney(value); }
}

