import { FormatMoney } from "../../../73_ZRSJZ/Scripts/ZRSJZ_NumberFormat";
import { _decorator, Button, EventTouch, Label, Node } from 'cc';
import { ZRSJZ_Panel } from '../../../73_ZRSJZ/Scripts/Panel/ZRSJZ_Panel';
import { ZRSJZ_UIManager } from '../../../73_ZRSJZ/Scripts/Manager/ZRSJZ_UIManager';
import { ZRSJZ_MAP_CONFIG, ZRSJZ_PANEL } from '../../../73_ZRSJZ/Scripts/ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../../../73_ZRSJZ/Scripts/ZRSJZ_GameData';
import { ZRSJZ_SelectPanel } from '../../../73_ZRSJZ/Scripts/Panel/ZRSJZ_SelectPanel';
import { ZRSJZ_OnlineService as Online } from '../../../73_ZRSJZ/Scripts/Service/ZRSJZ_OnlineService';
import { ZRSJZ_OnlineBattle } from '../../../73_ZRSJZ/Scripts/Controller/ZRSJZ_OnlineBattle';
const { ccclass } = _decorator;

@ccclass('ZRSJZ_OnlinePanel')
export class ZRSJZ_OnlinePanel extends ZRSJZ_Panel {
    private code = '';
    private readonly maps = ['五号小镇', '沙漠古迹', '极北之地'];
    private readonly modes = ['机密行动', '绝密行动'];
    private N(path: string): Node { return this.node.getChildByPath('Panel/' + path); }
    private Text(path: string, value: string): void { this.N(path).getComponent(Label).string = value; }
    private Enable(path: string, enabled: boolean): void { this.N(path).getComponent(Button).interactable = enabled; }
    protected onEnable(): void {
        Online.Events.on('change', this.Refresh, this);
        Online.Events.on('start', this.StartBattle, this);
        this.N('数字键盘').active = false;
        this.Refresh();
        this.schedule(this.CheckReadiness, 0.5);
        Online.Connect();
    }
    protected onDisable(): void {
        Online.Events.off('change', this.Refresh, this);
        Online.Events.off('start', this.StartBattle, this);
        this.unschedule(this.CheckReadiness);
    }
    private Value(value: number): string { return FormatMoney(value); }
    private CanReady(showTip: boolean): boolean {
        const config = ZRSJZ_MAP_CONFIG.get(Online.Map);
        const value = ZRSJZ_SelectPanel.GetLoadoutValue([0]);
        const valid = !!config && value >= config.RequiredLoadoutValue;
        if (!valid && showTip) ZRSJZ_UIManager.Instance.ShowTip(config
            ? '配置价值不足，还需' + this.Value(config.RequiredLoadoutValue - value)
            : '该关卡暂未开放');
        return valid;
    }
    private CheckReadiness(): void {
        const me = Online.Room?.members.find(m => m.id === Online.SelfID);
        if (me?.ready && Online.Room.phase === 'lobby' && !this.CanReady(false)) {
            Online.Send('ready', { ready: false, map: Online.Map });
        }
        this.Refresh();
    }
    private Refresh(): void {
        const room = Online.Room;
        const me = room?.members.find(m => m.id === Online.SelfID);
        const [map, mode] = Online.Map.split('_');
        const config = ZRSJZ_MAP_CONFIG.get(Online.Map);
        this.Text('状态', Online.Status);
        this.Text('房间信息', room ? '房间号：' + room.code + '    ' + room.members.length + '/2 人' : '创建房间后，将六位房间号告诉好友');
        this.Text('成员信息', room ? room.members.map(m => (m.id === room.host ? '房主' : '队友') + '  ' + (m.id === Online.SelfID ? '你' : m.name) + '  ·  ' + (m.ready ? '已准备' : '未准备')).join('\n') : '等待组队\n最多两人 · 掉落各自独立');
        this.Text('战备信息', '战备：' + this.Value(ZRSJZ_SelectPanel.GetLoadoutValue([0])) + ' / ' + this.Value(config?.RequiredLoadoutValue || 0)
            + '  ·  ' + (this.CanReady(false) ? '已达标' : '未达标') + '  ·  时限 ' + (config?.TimeLimitMinutes || '--') + '分钟');
        this.Text('准备/文字', me?.ready ? '取消准备' : '准备');
        this.Text('房间号输入/文字', this.code || '点击输入房间号');
        this.Text('数字键盘/号码', this.code.padEnd(6, '＿').split('').join('  '));
        this.Enable('连接', !Online.Connected && !Online.Connecting);
        this.Enable('创建房间', !!Online.SelfID && !room);
        this.Enable('加入房间', !!Online.SelfID && !room && this.code.length === 6);
        this.Enable('房间号输入', !room);
        this.Enable('离开房间', !!room);
        this.Enable('准备', !!room && room.phase === 'lobby');
        this.Enable('开始游戏', Online.IsHost && room?.members.length === 2 && room.members.every(m => m.ready) && room.phase === 'lobby');
        for (const name of [...this.maps, ...this.modes]) {
            this.Enable(name, Online.IsHost && room?.phase === 'lobby');
            this.Text(name + '/文字', (name === map || name === mode ? '✓ ' : '') + name);
            const selected = this.N(name + '/' + name + '选中标记');
            if (selected) selected.active = name === map;
        }
        if (room) this.N('数字键盘').active = false;
    }
    public OnButtonClick(event: EventTouch): void {
        const name = event.getCurrentTarget().name;
        if (/^数字[0-9]$/.test(name)) {
            if (this.code.length < 6) this.code += name.slice(-1);
            this.Refresh(); return;
        }
        if (this.maps.includes(name) || this.modes.includes(name)) {
            if (!Online.IsHost) return;
            const [map, mode] = Online.Map.split('_');
            Online.Send('select_map', { map: this.maps.includes(name) ? name + '_' + mode : map + '_' + name });
            return;
        }
        switch (name) {
            case '关闭': Online.Disconnect(); ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.联机界面); break;
            case '连接': Online.Connect(); break;
            case '创建房间': Online.Create(); break;
            case '加入房间': Online.Join(this.code); break;
            case '房间号输入': this.N('数字键盘').active = true; break;
            case '退格': this.code = this.code.slice(0, -1); this.Refresh(); break;
            case '清空': this.code = ''; this.Refresh(); break;
            case '完成输入':
            case '取消输入': this.N('数字键盘').active = false; break;
            case '离开房间': Online.Leave(); break;
            case '准备': {
                const ready = Online.Room?.members.find(m => m.id === Online.SelfID)?.ready;
                if (ready || this.CanReady(true)) Online.Send('ready', { ready: !ready, map: Online.Map });
                break;
            }
            case '开始游戏':
                if (this.CanReady(true)) Online.Send('start');
                else Online.Send('ready', { ready: false, map: Online.Map });
                break;
        }
    }
    private StartBattle(): void {
        if (!this.CanReady(true)) { Online.Battle = false; Online.Leave(); return; }
        ZRSJZ_OnlineBattle.PreviousModel = ZRSJZ_GameData.Instance.CurModel;
        ZRSJZ_GameData.Instance.CurModel = '1p';
        ZRSJZ_GameData.Instance.CurMap = Online.Map;
        ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.联机界面);
        ZRSJZ_UIManager.Instance.ShowPanel(ZRSJZ_PANEL.加载界面, 'ZRSJZ_Game');
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, Component, Label, Node, Sprite, SpriteFrame, UITransform } from 'cc';
import { ZRSJZ_PROP_CONFIG } from '../ZRSJZ_Constant';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_ShopItem')
export class ZRSJZ_ShopItem extends Component {

    Sprite: Sprite = null;
    IconSprite: Sprite = null;
    NameLabel: Label = null;
    PriceLabel: Label = null;
    Chekcked: Node = null;

    private _init: boolean = false;
    async Init(shopName: string) {
        if (!this._init) {
            this._init = true;
            this.Sprite = this.node.getComponent(Sprite);
            this.IconSprite = this.node.getChildByName("Icon").getComponent(Sprite);
            this.NameLabel = this.node.getChildByName("Name").getComponent(Label);
            this.PriceLabel = this.node.getChildByName("Price").getComponent(Label);
            this.Chekcked = this.node.getChildByName("Checked");
        }
        this.Chekcked.active = false;
        const shopData = ZRSJZ_PROP_CONFIG.get(shopName);
        this.NameLabel.string = shopName;
        this.PriceLabel.string = FormatMoney(shopData.UnitPrice, true);
        this.Sprite.spriteFrame = await ZRSJZ_UIManager.Instance.GetPropGridUI(`${shopData.Quality}1_2`);
        this.IconSprite.spriteFrame = await ZRSJZ_UIManager.Instance.GetPropUI(shopName);
        this.ScaleNodeToFit(this.IconSprite.node);
    }

    private ScaleNodeToFit(targetNode: Node): void {
        if (!targetNode) {
            return;
        }

        const parentUITransform = this.getComponent(UITransform);
        const targetUITransform = targetNode.getComponent(UITransform);
        if (!parentUITransform || !targetUITransform) {
            return;
        }

        const parentWidth = parentUITransform.width - 20;
        const parentHeight = parentUITransform.height - 20;
        const targetWidth = targetUITransform.width;
        const targetHeight = targetUITransform.height;

        if (parentWidth <= 0 || parentHeight <= 0 || targetWidth <= 0 || targetHeight <= 0) {
            return;
        }

        const scaleX = parentWidth / targetWidth;
        const scaleY = parentHeight / targetHeight;
        const scale = Math.floor(Math.min(scaleX, scaleY) * 100);

        targetNode.setScale(scale / 100, scale / 100, 1);
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_AccountService } from "../Service/ZRSJZ_AccountService";
import { _decorator, Button, EventTouch, find, isValid, Label, Node, Sprite, UITransform, v3 } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_PANEL, ZRSJZ_PROP_CONFIG } from '../ZRSJZ_Constant';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_TaskService } from "../Service/ZRSJZ_TaskService";
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_GetBulletPanel')
export class ZRSJZ_GetBulletPanel extends ZRSJZ_Panel {
    private _ammoName: string = "";
    private _unitPrice: number = 0;
    private _maxCount: number = 0;
    private _count: number = 0;
    private _nameLabel: Label = null;
    private _countLabel: Label = null;
    private _priceLabel: Label = null;
    private _icon: Sprite = null;
    private _track: Node = null;
    private _fill: Sprite = null;
    private _handle: Node = null;
    private _isPurchasing: boolean = false;

    protected onLoad(): void {
        this._nameLabel = find("Panel/PropName", this.node)?.getComponent(Label) ?? null;
        this._countLabel = find("Panel/数目底/PropName", this.node)?.getComponent(Label) ?? null;
        this._priceLabel = find("Panel/PropPrice/Price", this.node)?.getComponent(Label) ?? null;
        this._icon = find("Panel/PropIcon", this.node)?.getComponent(Sprite) ?? null;
        this._track = find("Panel/数目条底", this.node);
        this._fill = find("Panel/数目条底/数目条", this.node)?.getComponent(Sprite) ?? null;
        this._handle = find("Panel/数目条底/滑块", this.node);

        this.BindButton(find("Panel/减", this.node));
        this.BindButton(find("Panel/加", this.node));
        this.BindButton(find("Mask", this.node));
        this._track?.on(Node.EventType.TOUCH_START, this.OnSliderTouch, this);
        this._track?.on(Node.EventType.TOUCH_MOVE, this.OnSliderTouch, this);
        this._track?.on(Node.EventType.TOUCH_END, this.OnSliderTouch, this);
        this._track?.on(Node.EventType.TOUCH_CANCEL, this.OnSliderTouch, this);
    }

    protected onDestroy(): void {
        // 父节点销毁时，滑动条子节点先于本组件销毁，不能再访问其事件处理器。
        const track = this._track;
        this._track = null;
        if (!isValid(track, true)) return;
        track.off(Node.EventType.TOUCH_START, this.OnSliderTouch, this);
        track.off(Node.EventType.TOUCH_MOVE, this.OnSliderTouch, this);
        track.off(Node.EventType.TOUCH_END, this.OnSliderTouch, this);
        track.off(Node.EventType.TOUCH_CANCEL, this.OnSliderTouch, this);
    }

    public Show(ammoName: string): void {
        super.Show();
        const ammoData = ZRSJZ_PROP_CONFIG.get(ammoName);
        if (!ammoData || ammoData.PropType !== "弹药") {
            ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.购买子弹弹窗);
            return;
        }

        this._ammoName = ammoName;
        this._isPurchasing = false;
        this._unitPrice = Math.max(1, Math.floor(ammoData.UnitPrice));
        this._maxCount = Math.min(999, Math.floor(ZRSJZ_GameData.Instance.Gold / this._unitPrice));
        this._count = this._maxCount > 0 ? 1 : 0;
        if (this._nameLabel) this._nameLabel.string = ammoName;
        void ZRSJZ_UIManager.Instance.GetPropUI(ammoName).then(spriteFrame => {
            if (this.node.isValid && this._ammoName === ammoName && this._icon) {
                this._icon.spriteFrame = spriteFrame;
            }
        });
        this.RefreshDisplay();
    }

    public OnButtonClick(event: EventTouch): void {
        if (ZRSJZ_UIManager.Dragging) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "减":
                this.SetCount(this._count - 1);
                break;
            case "加":
                this.SetCount(this._count + 1);
                break;
            case "购买":
                this.Purchase();
                break;
            case "Mask":
            case "关闭":
            case "Close":
                ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.购买子弹弹窗);
                break;
        }
    }

    private BindButton(node: Node): void {
        if (!node) return;
        const button = node.getComponent(Button) ?? node.addComponent(Button);
        button.node.on(Node.EventType.TOUCH_START, this.OnButtonClick, this);
    }

    private readonly OnSliderTouch = (event: EventTouch): void => {
        if (!this._track || this._maxCount <= 0) return;
        const transform = this._track.getComponent(UITransform);
        if (!transform) return;
        const local = transform.convertToNodeSpaceAR(v3(
            event.getUILocation().x,
            event.getUILocation().y,
            0,
        ));
        const width = transform.contentSize.width;
        const progress = Math.max(0, Math.min(1, local.x / width + transform.anchorPoint.x));
        this.SetCount(Math.max(1, Math.round(progress * this._maxCount)));
        event.propagationStopped = true;
    };

    private SetCount(count: number): void {
        this._count = Math.max(0, Math.min(this._maxCount, Math.floor(count)));
        this.RefreshDisplay();
    }

    private RefreshDisplay(): void {
        const progress = this._maxCount > 0 ? this._count / this._maxCount : 0;
        if (this._countLabel) this._countLabel.string = `${this._count}/${this._maxCount}`;
        if (this._priceLabel) this._priceLabel.string = FormatMoney(this._count * this._unitPrice, true);
        if (this._fill) this._fill.fillRange = progress;
        if (this._handle && this._track) {
            const width = this._track.getComponent(UITransform)?.contentSize.width ?? 0;
            this._handle.setPosition(
                (progress - 0.5) * width,
                this._handle.position.y,
                this._handle.position.z,
            );
        }
    }

    private async Purchase(): Promise<void> {
        if (this._isPurchasing) return;
        if (!this._ammoName || this._count <= 0) {
            ZRSJZ_UIManager.Instance.ShowTip("金币不足，无法购买子弹");
            return;
        }
        const totalPrice = this._count * this._unitPrice;
        this._isPurchasing = true;
        const awards = [{
            PropName: this._ammoName,
            Count: this._count,
        }];
        if (!await ZRSJZ_UIManager.Instance.CanReceivePropAwards(awards)) {
            this._isPurchasing = false;
            ZRSJZ_UIManager.Instance.ShowTip("仓库已满，请先整理仓库！");
            return;
        }
        if (ZRSJZ_GameData.Instance.Gold < totalPrice) {
            this._isPurchasing = false;
            ZRSJZ_UIManager.Instance.ShowTip("金币不足");
            return;
        }

        ZRSJZ_AccountService.ChangeGold(-totalPrice);
        const result = await ZRSJZ_UIManager.Instance.ReceivePropAwards(awards);
        if (result.PlacedPropIDs.length === 0 && result.MailAwards.length === 0) {
            ZRSJZ_AccountService.ChangeGold(totalPrice);
            this._isPurchasing = false;
            ZRSJZ_UIManager.Instance.ShowTip("子弹加入仓库失败");
            return;
        }

        ZRSJZ_UIManager.Instance.ShowTip(`成功购买${this._count}发${this._ammoName}`);
        ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.购买子弹弹窗);
        ZRSJZ_TaskService.CompleteTask(`在商城购买[${this._ammoName}]`, this._count);
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_PetBackpackView } from '../UI/ZRSJZ_PetBackpackView';
import { ZRSJZ_InventoryService } from "../Service/ZRSJZ_InventoryService";
import { _decorator, EventTouch, find, Label, Layout, Node, ScrollView, Sprite, SpriteFrame, Widget } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_Prepare } from '../UI/ZRSJZ_Prepare';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_INVENTORY, ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from '../Manager/ZRSJZ_EventManager';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_Inventory } from '../UI/ZRSJZ_Inventory';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_BackpackPanel')
export class ZRSJZ_BackpackPanel extends ZRSJZ_Panel {
    private _playerIndex: number = 0;

    @property(SpriteFrame)
    DiscardSFs: SpriteFrame[] = [];

    Prepare: ZRSJZ_Prepare = null;
    BackpackContent: Node = null;
    public ScrollView: ScrollView = null;
    private _totalValue: Label = null;
    private _discardArea: Node = null;
    private _discardSprite: Sprite = null;
    private _isOrganizing: boolean = false;
    private _inventoryShowVersion: number = 0;
    private _freeExpansion: Node = null;

    private _petBackpackView: ZRSJZ_PetBackpackView = null;
    private _petBackpackRefreshTime = 0;

    protected lateUpdate(dt: number): void {
        this._petBackpackRefreshTime -= dt;
        if (this._petBackpackRefreshTime > 0) return;
        this._petBackpackRefreshTime = 0.2;
        this._petBackpackView?.Refresh(this._playerIndex);
    }

    protected onLoad(): void {
        this._petBackpackView = new ZRSJZ_PetBackpackView(this.node);
        this.Prepare = find("Panel/备战", this.node).getComponent(ZRSJZ_Prepare);
        this.BackpackContent = find("Panel/背包/View/Content", this.node);
        this.ScrollView = find("Panel/背包", this.node).getComponent(ScrollView);
        this._totalValue = (find("Panel/背包总价值/Count", this.node)
            ?? find("Panel/武器装备/背包总价值/Count", this.node))?.getComponent(Label);
        this._discardArea = find("Panel/丢弃范围", this.node);
        this._discardSprite = find("Panel/丢弃范围", this.node).getComponent(Sprite);
        this.ResolveFreeExpansion();
    }


    protected onEnable(): void {
        this._petBackpackView?.Refresh(this._playerIndex);
        this.Prepare.Show(true, this._playerIndex, true);
        this.ShowBackpack();
        this.RefreshTotalValue();
        ZRSJZ_UIManager.Instance.RegisterDiscardArea(this._discardArea, this.DiscardSFs, this._playerIndex);
        ZRSJZ_EventManager.On(ZRSJZ_MyEvent.ZRSJZ_PROP_MOVE, this.PropMove, this);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE, this.RefreshTotalValue, this);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_BACKPACK_EXPANDED, this.OnBackpackExpanded, this);
    }

    protected onDisable(): void {
        this._petBackpackView?.Hide();
        this._inventoryShowVersion++;
        if (this._discardArea) this._discardArea.active = false;
        ZRSJZ_UIManager.Instance.UnregisterDiscardArea(this._discardArea, this._playerIndex);
        ZRSJZ_EventManager.Off(ZRSJZ_MyEvent.ZRSJZ_PROP_MOVE, this.PropMove, this);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE, this.RefreshTotalValue, this);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_BACKPACK_EXPANDED, this.OnBackpackExpanded, this);
    }

    Show(...args: any[]): void {
        this._playerIndex = this.PlayerIndex >= 0
            ? (this.PlayerIndex === 1 ? 1 : 0)
            : (args[0] === 1 ? 1 : 0);
        ZRSJZ_InventoryService.SetActivePlayerIndex(this._playerIndex);
        ZRSJZ_UIManager.Instance.DeactivatePlayerInventoryNodes(this._playerIndex);
        super.Show();
    }

    async OnButtonClick(event: EventTouch): Promise<void> {
        if (ZRSJZ_UIManager.Dragging) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Mask":
                ZRSJZ_UIManager.Instance.HidePlayerPanel(
                    ZRSJZ_PANEL.背包弹窗,
                    this._playerIndex,
                );
                break;
            case "整理背包":
                await this.OrganizeBackpack();
                break;
            case "免费扩容":
                ZRSJZ_UIManager.Instance.ShowPlayerPanel(
                    ZRSJZ_PANEL.背包扩容弹窗,
                    this._playerIndex,
                    this._playerIndex,
                );
                break;
        }
    }

    private async OrganizeBackpack(): Promise<void> {
        if (this._isOrganizing) return;
        this._isOrganizing = true;
        try {
            const backpackNode = await ZRSJZ_UIManager.Instance.GetInventory(
                ZRSJZ_INVENTORY.背包,
                this._playerIndex,
                true,
            );
            const organized = await backpackNode?.getComponent(ZRSJZ_Inventory)?.AutoOrganize();
            if (!organized) {
                ZRSJZ_UIManager.Instance.ShowTip("背包整理失败");
            }
        } finally {
            this._isOrganizing = false;
        }
    }

    PropMove(move: boolean) {
        const playerIndex = ZRSJZ_UIManager.DraggingPlayerIndex;
        if (playerIndex >= 0 && playerIndex !== this._playerIndex) return;
        this.ScrollView.enabled = move;
    }

    private RefreshTotalValue() {
        const totalValue = ZRSJZ_InventoryService.GetInventoryTotalValue([
            ZRSJZ_INVENTORY.宠物背包,
            ZRSJZ_INVENTORY.背包,
            ZRSJZ_INVENTORY.保险箱,
        ], this._playerIndex);
        if (this._totalValue) this._totalValue.string = FormatMoney(totalValue);
    }

    ShowBackpack() {
        const showVersion = ++this._inventoryShowVersion;
        const playerIndex = this._playerIndex;
        ZRSJZ_UIManager.Instance.GetInventory(
            ZRSJZ_INVENTORY.背包,
            playerIndex,
            true,
        ).then(async backpack => {
            await backpack.getComponent(ZRSJZ_Inventory).ShowForPlayer(
                ZRSJZ_INVENTORY.背包,
                playerIndex,
            );
            const inventory = backpack.getComponent(ZRSJZ_Inventory);
            if (
                showVersion !== this._inventoryShowVersion
                || !this.node.activeInHierarchy
                || inventory.PlayerViewIndex !== playerIndex
            ) return;
            backpack.parent = this.BackpackContent;
            backpack.setPosition(0, 0, 0);
            backpack.active = true;
            this.PlaceFreeExpansion();
        });
    }

    private PlaceFreeExpansion(): void {
        const freeExpansion = this.ResolveFreeExpansion();
        if (!freeExpansion) return;
        const isExpanded = ZRSJZ_InventoryService.IsBackpackExpanded(this._playerIndex);
        freeExpansion.active = !isExpanded;
        if (isExpanded) return;

        const widget = freeExpansion.getComponent(Widget);
        if (widget) widget.enabled = false;
        freeExpansion.parent = this.BackpackContent;
        freeExpansion.setPosition(280, 0, 0);
        freeExpansion.setSiblingIndex(this.BackpackContent.children.length - 1);
        this.BackpackContent.getComponent(Layout)?.updateLayout();
    }

    private OnBackpackExpanded(playerIndex: number): void {
        if (playerIndex !== this._playerIndex) return;
        const freeExpansion = this.ResolveFreeExpansion();
        if (freeExpansion) freeExpansion.active = false;
        this.BackpackContent?.getComponent(Layout)?.updateLayout();
    }

    /** 兼容免费扩容节点位于背包根节点或已经放入 Content 的两种预制体层级。 */
    private ResolveFreeExpansion(): Node | null {
        if (this._freeExpansion?.isValid) return this._freeExpansion;
        this._freeExpansion = find("免费扩容", this.BackpackContent)
            ?? find("Panel/背包/免费扩容", this.node);
        return this._freeExpansion;
    }

}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_PetBackpackView } from '../UI/ZRSJZ_PetBackpackView';
import { ZRSJZ_InventoryService } from "../Service/ZRSJZ_InventoryService";
import {
    _decorator,
    EventTouch,
    find,
    Label,
    Layout,
    Mask,
    Node,
    ScrollView,
    Sprite,
    SpriteFrame,
    UIOpacity,
    UITransform,
    Widget,
} from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_Prepare } from '../UI/ZRSJZ_Prepare';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from '../Manager/ZRSJZ_EventManager';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import {
    ZRSJZ_GRID_INTERVAL,
    ZRSJZ_GRID_SIZE,
    ZRSJZ_INVENTORY,
    ZRSJZ_INVENTORY_CONFIG,
    ZRSJZ_PANEL,
    ZRSJZ_PROP_CONFIG,
} from '../ZRSJZ_Constant';
import { ZRSJZ_Box } from '../Unit/ZRSJZ_Box';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_Inventory } from '../UI/ZRSJZ_Inventory';
import { ZRSJZ_BoxInventory } from '../UI/ZRSJZ_BoxInventory';
import { ZRSJZ_PropGrid } from '../UI/ZRSJZ_PropGrid';
import { ZRSJZ_PoolManager } from '../Manager/ZRSJZ_PoolManager';
import { ZRSJZ_SearchPropEffect } from '../Effect/ZRSJZ_SearchPropEffect';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_TutorialPanel } from './ZRSJZ_TutorialPanel';
const { ccclass, property } = _decorator;

type ZRSJZ_SearchReservation = {
    goods: ZRSJZ_BoxInventory,
    token: string,
    gridX: number,
    gridY: number,
    width: number,
    height: number,
};

@ccclass('ZRSJZ_GoodsPanel')
export class ZRSJZ_GoodsPanel extends ZRSJZ_Panel {
    @property({ displayName: '每件物资搜索时间（秒）', min: 0.05 })
    SearchInterval: number = 0.5;

    @property(SpriteFrame)
    DiscardSFs: SpriteFrame[] = [];

    Prepare: ZRSJZ_Prepare = null;
    BackpackContent: Node = null;
    GoodsContent: Node = null;
    public ScrollView: ScrollView = null;
    public GoodsScrollView: ScrollView = null;
    private _totalValue: Label = null;
    private _discardArea: Node = null;
    private _discardSprite: Sprite = null;
    private _isOrganizing: boolean = false;
    private _freeExpansion: Node = null;

    private _revealSerial: number = 0;
    private _arrayInventorySerial: number = 0;
    private _revealCallback: () => void = null;
    private _activeGoodsInventory: ZRSJZ_BoxInventory = null;
    private _activeBox: ZRSJZ_Box = null;
    private _playerIndex: number = 0;
    private _arrayGoodsInventory: ZRSJZ_BoxInventory = null;
    private _backpackShowVersion: number = 0;
    private readonly _searchPlaceholders: Array<Node | null> = [];
    private readonly _searchReservations = new Map<Node, ZRSJZ_SearchReservation>();

    private _petBackpackView: ZRSJZ_PetBackpackView = null;
    private _petBackpackRefreshTime = 0;

    protected lateUpdate(dt: number): void {
        this._petBackpackRefreshTime -= dt;
        if (this._petBackpackRefreshTime > 0) return;
        this._petBackpackRefreshTime = 0.2;
        this._petBackpackView?.Refresh(this._playerIndex);
    }

    protected onLoad(): void {
        this._petBackpackView = new ZRSJZ_PetBackpackView(this.node);
        this.Prepare = find("Panel/备战", this.node).getComponent(ZRSJZ_Prepare);
        this.BackpackContent = find("Panel/背包/View/Content", this.node);
        this.ScrollView = find("Panel/背包", this.node).getComponent(ScrollView);
        this._totalValue = (find("Panel/背包总价值/Count", this.node)
            ?? find("Panel/武器装备/背包总价值/Count", this.node))?.getComponent(Label);
        this._discardArea = find("Panel/丢弃范围", this.node);
        this._discardSprite = find("Panel/丢弃范围", this.node).getComponent(Sprite);
        this.ResolveFreeExpansion();
        this.GoodsContent = this.EnsureGoodsContent();
    }

    protected onEnable(): void {
        this._petBackpackView?.Refresh(this._playerIndex);
        this.Prepare.Show(true, this._playerIndex, true);
        this.ShowBackpack();
        this.RefreshTotalValue();
        ZRSJZ_UIManager.Instance.RegisterDiscardArea(this._discardArea, this.DiscardSFs, this._playerIndex);
        ZRSJZ_EventManager.On(ZRSJZ_MyEvent.ZRSJZ_PROP_MOVE, this.PropMove, this);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE, this.RefreshTotalValue, this);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_BACKPACK_EXPANDED, this.OnBackpackExpanded, this);
    }

    protected onDisable(): void {
        this._petBackpackView?.Hide();
        this._backpackShowVersion++;
        if (this._discardArea) this._discardArea.active = false;
        ZRSJZ_UIManager.Instance.UnregisterDiscardArea(this._discardArea, this._playerIndex);
        this.CancelReveal();
        if (this._activeGoodsInventory?.node?.isValid) {
            this._activeGoodsInventory.node.active = false;
        }
        this._activeBox?.EndSearch(this._playerIndex);
        this._activeBox = null;
        ZRSJZ_EventManager.Off(ZRSJZ_MyEvent.ZRSJZ_PROP_MOVE, this.PropMove, this);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE, this.RefreshTotalValue, this);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_BACKPACK_EXPANDED, this.OnBackpackExpanded, this);
    }

    Show(...args: any[]): void {
        const source = args[0];
        const box = source instanceof ZRSJZ_Box ? source : null;
        this._playerIndex = this.PlayerIndex >= 0
            ? (this.PlayerIndex === 1 ? 1 : 0)
            : box
                ? (args[1] === 1 ? 1 : 0)
                : (args[2] === 1 ? 1 : 0);
        ZRSJZ_InventoryService.SetActivePlayerIndex(this._playerIndex);
        // 防止其他入口直接打开物资弹窗而绕过密码验证。
        if (box?.RequiresPassword() && !box.IsPasswordUnlocked()) {
            ZRSJZ_UIManager.Instance.HidePlayerPanel(ZRSJZ_PANEL.物资弹窗, this._playerIndex, () => {
                ZRSJZ_UIManager.Instance.ShowPlayerPanel(
                    ZRSJZ_PANEL.密码箱弹窗,
                    this._playerIndex,
                    box,
                    this._playerIndex,
                );
            });
            return;
        }
        if (box && !box.TryBeginSearch(this._playerIndex)) {
            ZRSJZ_UIManager.Instance.ShowTip("另一名玩家正在搜索该箱子");
            ZRSJZ_UIManager.Instance.HidePlayerPanel(ZRSJZ_PANEL.物资弹窗, this._playerIndex);
            return;
        }
        this._activeBox = box;
        ZRSJZ_UIManager.Instance.DeactivatePlayerInventoryNodes(this._playerIndex);
        super.Show();
        const props = Array.isArray(source)
            ? source.filter(propName => typeof propName === 'string')
            : [];
        box?.Open();
        const intervalArg = box ? args[2] : args[1];
        const interval = typeof intervalArg === 'number'
            ? Math.max(0.05, intervalArg)
            : Math.max(0.05, this.SearchInterval);
        this.StartReveal(props, interval, box);
    }

    async OnButtonClick(event: EventTouch): Promise<void> {
        if (ZRSJZ_UIManager.Dragging) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Mask":
                if (ZRSJZ_TutorialPanel.IsTipShowing) {
                    ZRSJZ_UIManager.Instance.ShowTip("请先完成新手引导");
                    return
                } else if (ZRSJZ_GameData.Instance.CurMap == "新手村") {
                    ZRSJZ_EventManager.Emit(ZRSJZ_MyEvent.ZRSJZ_TUTORIAL, 4);
                }
                ZRSJZ_UIManager.Instance.HidePlayerPanel(ZRSJZ_PANEL.物资弹窗, this._playerIndex);
                break;
            case "整理背包":
                await this.OrganizeBackpack();
                break;
            case "免费扩容":
                ZRSJZ_UIManager.Instance.ShowPlayerPanel(
                    ZRSJZ_PANEL.背包扩容弹窗,
                    this._playerIndex,
                    this._playerIndex,
                );
                break;
        }
    }

    private async OrganizeBackpack(): Promise<void> {
        if (this._isOrganizing) return;
        this._isOrganizing = true;
        try {
            const backpackNode = await ZRSJZ_UIManager.Instance.GetInventory(
                ZRSJZ_INVENTORY.背包,
                this._playerIndex,
                true,
            );
            const organized = await backpackNode?.getComponent(ZRSJZ_Inventory)?.AutoOrganize();
            if (!organized) {
                ZRSJZ_UIManager.Instance.ShowTip("背包整理失败");
            }
        } finally {
            this._isOrganizing = false;
        }
    }

    PropMove(move: boolean) {
        const playerIndex = ZRSJZ_UIManager.DraggingPlayerIndex;
        if (playerIndex >= 0 && playerIndex !== this._playerIndex) return;
        this.ScrollView.enabled = move;
        if (this.GoodsScrollView) {
            this.GoodsScrollView.enabled = move;
        }
    }

    private RefreshTotalValue(): void {
        const totalValue = ZRSJZ_InventoryService.GetInventoryTotalValue([
            ZRSJZ_INVENTORY.宠物背包,
            ZRSJZ_INVENTORY.背包,
            ZRSJZ_INVENTORY.保险箱,
        ], this._playerIndex);
        if (this._totalValue) this._totalValue.string = FormatMoney(totalValue);
    }

    async ShowBackpack(): Promise<ZRSJZ_Inventory> {
        const showVersion = ++this._backpackShowVersion;
        const playerIndex = this._playerIndex;
        const backpack = await ZRSJZ_UIManager.Instance.GetInventory(
            ZRSJZ_INVENTORY.背包,
            playerIndex,
            true,
        );
        const inventory = backpack.getComponent(ZRSJZ_Inventory);
        await inventory.ShowForPlayer(
            ZRSJZ_INVENTORY.背包,
            playerIndex,
        );
        if (
            showVersion !== this._backpackShowVersion
            || !this.node.activeInHierarchy
            || inventory.PlayerViewIndex !== playerIndex
        ) return null;
        backpack.parent = this.BackpackContent;
        backpack.setPosition(0, 0, 0);
        backpack.active = true;
        this.PlaceFreeExpansion();
        return inventory;
    }

    private PlaceFreeExpansion(): void {
        const freeExpansion = this.ResolveFreeExpansion();
        if (!freeExpansion) return;
        const isExpanded = ZRSJZ_InventoryService.IsBackpackExpanded(this._playerIndex);
        freeExpansion.active = !isExpanded;
        if (isExpanded) return;

        const widget = freeExpansion.getComponent(Widget);
        if (widget) widget.enabled = false;
        freeExpansion.parent = this.BackpackContent;
        freeExpansion.setPosition(280, 0, 0);
        freeExpansion.setSiblingIndex(this.BackpackContent.children.length - 1);
        this.BackpackContent.getComponent(Layout)?.updateLayout();
    }

    private OnBackpackExpanded(playerIndex: number): void {
        if (playerIndex !== this._playerIndex) return;
        const freeExpansion = this.ResolveFreeExpansion();
        if (freeExpansion) freeExpansion.active = false;
        this.BackpackContent?.getComponent(Layout)?.updateLayout();
    }

    /** 兼容免费扩容节点位于背包根节点或已经放入 Content 的两种预制体层级。 */
    private ResolveFreeExpansion(): Node | null {
        if (this._freeExpansion?.isValid) return this._freeExpansion;
        this._freeExpansion = find("免费扩容", this.BackpackContent)
            ?? find("Panel/背包/免费扩容", this.node);
        return this._freeExpansion;
    }

    private async StartReveal(
        propNames: string[],
        interval: number,
        box: ZRSJZ_Box = null,
    ): Promise<void> {
        this.CancelReveal();

        const serial = this._revealSerial;
        const goods = await this.ShowGoods(box);
        if (serial !== this._revealSerial || !this.node.activeInHierarchy || !goods) {
            return;
        }
        if (propNames.length === 0 && !box?.HasUnclaimedLoot()) {
            return;
        }

        const pendingProps = box
            ? Array.from(box.GetUnclaimedLootProps())
            : propNames.slice();
        await this.ShowSearchPlaceholders(goods, pendingProps, serial);
        if (serial !== this._revealSerial || !this.node.activeInHierarchy) {
            return;
        }

        let index = 0;
        const revealNext = (): void => {
            this._revealCallback = null;
            if (serial !== this._revealSerial || !this.node.activeInHierarchy) {
                return;
            }
            if (!box && index >= propNames.length) {
                return;
            }

            const propName = box ? box.TakeNextLootProp() : propNames[index++];
            if (!propName) {
                return;
            }
            const placeholder = this._searchPlaceholders.shift() ?? null;
            const propConfig = ZRSJZ_PROP_CONFIG.get(propName);
            if (!propConfig) {
                console.warn(`[ZRSJZ_GoodsPanel] 未找到道具配置: ${propName}`);
                this.ReleaseSearchPlaceholder(placeholder);
                if (box?.HasUnclaimedLoot() || index < propNames.length) {
                    this.ScheduleNextReveal(revealNext, 0.05);
                }
                return;
            }

            const count = propConfig.PropType === "弹药" ? propConfig.MaxCount : 1;
            const propID = ZRSJZ_InventoryService.AddPropByName(propName, count);
            const propData = ZRSJZ_GameData.Instance.PropData[propID];
            propData.SourceBoxID = goods.BoxID;
            propData.IsSearchLocked = true;
            propData.IsRewardVideoLocked = box?.ConsumeRewardVideoLock(propName) === true;
            const placeholderGrid = this.GetPlaceholderGrid(placeholder);
            this.ClearSearchReservation(placeholder);
            if (placeholderGrid) {
                while (goods.Grids.length < placeholderGrid.y + propData.Height) {
                    goods.Grids.push(goods.GetEmptyRow());
                }
            }
            const usePlaceholderGrid = placeholderGrid
                && goods.CanPlace(
                    placeholderGrid.x,
                    placeholderGrid.y,
                    propData.Width,
                    propData.Height,
                );
            ZRSJZ_InventoryService.MovePropToInventory(
                propID,
                ZRSJZ_INVENTORY.物资,
                1,
                usePlaceholderGrid ? placeholderGrid.x : -1,
                usePlaceholderGrid ? placeholderGrid.y : -1,
            );
            ZRSJZ_GameData.SaveData();

            const showProp = usePlaceholderGrid
                ? goods.OccupyGrid(
                    propID,
                    placeholderGrid.x,
                    placeholderGrid.y,
                    propData.Width,
                    propData.Height,
                ).then(() => goods.ShowPropItem())
                : goods.ShowPropItem();

            showProp
                .then(async () => {
                    this.RefreshGoodsContentSize(goods.node);
                    // ShowPropItem 扩容时会在末尾新建空白格子，需把尚未搜索的
                    // 占位图重新提到最上层，避免被这些空白格子覆盖。
                    this.BringSearchPlaceholdersToFront();
                    const propNode = goods.node.children.find(child =>
                        child.getComponent(ZRSJZ_PropGrid)?.PropID === propID
                    );
                    if (propNode) {
                        const propGrid = propNode.getComponent(ZRSJZ_PropGrid);
                        propGrid.SetSearchLocked(true);
                        await this.PlaySearchEffect(
                            propNode,
                            propName,
                            interval,
                            placeholder,
                        );
                        propGrid.SetSearchLocked(false);
                        if (propGrid.PropData.Name === "CN8-突击步枪") {
                            this.scheduleOnce(() => {
                                ZRSJZ_EventManager.Emit(ZRSJZ_MyEvent.ZRSJZ_TUTORIAL, 2, propGrid.node, propGrid.PropData.InstanceID);
                            })
                        }
                        ZRSJZ_GameData.SaveData();
                    } else {
                        ZRSJZ_GameData.Instance.PropData[propID].IsSearchLocked = false;
                        ZRSJZ_GameData.SaveData();
                        this.ReleaseSearchPlaceholder(placeholder);
                    }
                })
                .catch(error => {
                    const propData = ZRSJZ_GameData.Instance.PropData[propID];
                    if (propData) {
                        propData.IsSearchLocked = false;
                        ZRSJZ_GameData.SaveData();
                    }
                    console.error(`[ZRSJZ_GoodsPanel] 显示搜索道具失败: ${propName}`, error);
                })
                .finally(() => {
                    if (
                        serial === this._revealSerial
                        && this.node.activeInHierarchy
                        && (box?.HasUnclaimedLoot() || index < propNames.length)
                    ) {
                        this.ScheduleNextReveal(revealNext, 0.05);
                    }
                });
        };

        this.ScheduleNextReveal(revealNext, 0.05);
    }

    /** 使用占位图预先确定的格子，避免前方物资取走后新物资自动向前补位。 */
    private GetPlaceholderGrid(placeholder: Node): { x: number, y: number } | null {
        if (!placeholder?.isValid) return null;

        const step = ZRSJZ_GRID_SIZE + ZRSJZ_GRID_INTERVAL;
        return {
            x: Math.round(placeholder.position.x / step),
            y: Math.round(-placeholder.position.y / step),
        };
    }

    private ScheduleNextReveal(callback: () => void, interval: number): void {
        this._revealCallback = callback;
        this.scheduleOnce(callback, interval);
    }

    private CancelReveal(): void {
        this._revealSerial++;
        this.ClearSearchPlaceholders();
        if (this._revealCallback) {
            this.unschedule(this._revealCallback);
            this._revealCallback = null;
        }
    }

    private async ShowGoods(box: ZRSJZ_Box): Promise<ZRSJZ_BoxInventory> {
        let inventory: ZRSJZ_BoxInventory;
        if (box) {
            inventory = await box.GetBoxInventory();
        } else {
            this._arrayGoodsInventory?.Dispose();
            this._arrayGoodsInventory = await ZRSJZ_BoxInventory.Create(
                `GoodsPanel_Array_${++this._arrayInventorySerial}`,
            );
            inventory = this._arrayGoodsInventory;
        }

        if (
            this._activeGoodsInventory
            && this._activeGoodsInventory !== inventory
            && this._activeGoodsInventory.node?.isValid
        ) {
            this._activeGoodsInventory.node.active = false;
        }
        this._activeGoodsInventory = inventory;
        // 箱子库存不属于“玩家库存”枚举，但在双人局内同样只能响应
        // 打开它的玩家所发起的拖动和格子高亮事件。
        inventory.PlayerViewIndex = this._playerIndex;

        const goods = inventory.node;
        goods.parent = this.GoodsContent;
        goods.setPosition(0, 0, 0);
        goods.active = true;
        await inventory.ShowPropItem();

        const transform = goods.getComponent(UITransform);
        const contentTransform = this.GoodsContent.getComponent(UITransform);
        if (transform && contentTransform) {
            transform.width = contentTransform.width;
            this.RefreshGoodsContentSize(goods);
        }
        return inventory;
    }

    private RefreshGoodsContentSize(goods: Node): void {
        const goodsTransform = goods?.getComponent(UITransform);
        const contentTransform = this.GoodsContent?.getComponent(UITransform);
        if (goodsTransform && contentTransform) {
            contentTransform.height = Math.max(866, goodsTransform.height);
        }
    }

    private async PlaySearchEffect(
        propNode: Node,
        propName: string,
        duration: number,
        placeholder: Node = null,
    ): Promise<void> {
        const propOpacity = propNode.getComponent(UIOpacity)
            ?? propNode.addComponent(UIOpacity);
        propOpacity.opacity = 0;
        let effectNode: Node = null;

        try {
            effectNode = await ZRSJZ_PoolManager.Instance.GetNode(
                "Prefabs/Effect/SearchPropEffect",
            );
            if (!effectNode || !propNode?.isValid) {
                propOpacity.opacity = 255;
                return;
            }

            effectNode.parent = propNode.parent;
            effectNode.setPosition(propNode.position);
            effectNode.active = true;
            this.BringSearchPlaceholdersToFront();
            effectNode.setSiblingIndex(effectNode.parent.children.length - 1);
            this.ReleaseSearchPlaceholder(placeholder);
            placeholder = null;
            const effect = effectNode.getComponent(ZRSJZ_SearchPropEffect);
            if (!effect) {
                propOpacity.opacity = 255;
                return;
            }
            await effect.Play(propNode, propName, duration);
        } catch (error) {
            if (propNode?.isValid) {
                propOpacity.opacity = 255;
            }
            throw error;
        } finally {
            this.ReleaseSearchPlaceholder(placeholder);
            if (effectNode?.isValid) {
                ZRSJZ_PoolManager.Instance.PutNode(effectNode);
            }
        }
    }

    /**
     * 按库存相同的从左到右、从上到下规则，预先摆放尚未揭示的开箱图片。
     * 占位节点会同时在 Grids 中写入临时标记，使未搜索和正在搜索的位置不可放置。
     */
    private async ShowSearchPlaceholders(
        goods: ZRSJZ_BoxInventory,
        propNames: readonly string[],
        serial: number,
    ): Promise<void> {
        this.ClearSearchPlaceholders();
        const grids = goods.Grids.map(row => row.slice());
        const colCount = goods.InventoryConfig.Col;
        const step = ZRSJZ_GRID_SIZE + ZRSJZ_GRID_INTERVAL;
        const emptyRow = (): string[] => Array(colCount).fill("");
        const reservations: Array<(ZRSJZ_SearchReservation & { propName: string }) | null> = [];
        const clearPlannedReservations = (): void => {
            for (const reservation of reservations) {
                if (reservation) this.ClearSearchReservationData(reservation);
            }
        };

        for (let index = 0; index < propNames.length; index++) {
            if (serial !== this._revealSerial || !this.node.activeInHierarchy) {
                clearPlannedReservations();
                return;
            }

            const propName = propNames[index];
            const gridType = ZRSJZ_PROP_CONFIG.get(propName)?.GridType;
            if (!gridType) {
                reservations.push(null);
                continue;
            }
            const [height, width] = gridType.split("_").map(Number);
            let gridX = -1;
            let gridY = -1;

            while (gridY < 0) {
                for (let y = 0; y < grids.length && gridY < 0; y++) {
                    for (let x = 0; x <= colCount - width; x++) {
                        let canPlace = true;
                        for (let row = y; row < y + height && canPlace; row++) {
                            if (!grids[row]) {
                                canPlace = false;
                                break;
                            }
                            for (let col = x; col < x + width; col++) {
                                if (grids[row][col] !== "") {
                                    canPlace = false;
                                    break;
                                }
                            }
                        }
                        if (canPlace) {
                            gridX = x;
                            gridY = y;
                            break;
                        }
                    }
                }
                if (gridY < 0) {
                    grids.push(emptyRow());
                }
            }

            while (grids.length < gridY + height + 3) {
                grids.push(emptyRow());
            }
            while (goods.Grids.length < grids.length) {
                goods.Grids.push(goods.GetEmptyRow());
            }
            const token = `__search_locked_${serial}_${index}`;
            for (let row = gridY; row < gridY + height; row++) {
                for (let col = gridX; col < gridX + width; col++) {
                    grids[row][col] = token;
                    goods.Grids[row][col] = token;
                }
            }

            reservations.push({
                goods,
                token,
                gridX,
                gridY,
                width,
                height,
                propName,
            });
        }

        for (const reservation of reservations) {
            if (!reservation) {
                this._searchPlaceholders.push(null);
                continue;
            }

            const placeholder = await ZRSJZ_PoolManager.Instance.GetNode(
                "Prefabs/Effect/SearchPropEffect",
            );
            if (
                !placeholder
                || serial !== this._revealSerial
                || !goods.node?.isValid
            ) {
                this.ReleaseSearchPlaceholder(placeholder);
                this.ClearSearchPlaceholders();
                clearPlannedReservations();
                return;
            }

            placeholder.parent = goods.node;
            placeholder.setPosition(
                reservation.gridX * step,
                -reservation.gridY * step,
                0,
            );
            placeholder.active = true;
            this._searchReservations.set(placeholder, reservation);
            await placeholder
                .getComponent(ZRSJZ_SearchPropEffect)
                ?.ShowPlaceholder(reservation.propName);
            if (serial !== this._revealSerial) {
                this.ReleaseSearchPlaceholder(placeholder);
                this.ClearSearchPlaceholders();
                clearPlannedReservations();
                return;
            }
            this._searchPlaceholders.push(placeholder);
            placeholder.setSiblingIndex(placeholder.parent.children.length - 1);
        }

        const goodsTransform = goods.node.getComponent(UITransform);
        if (goodsTransform) {
            goodsTransform.height = Math.max(goodsTransform.height, grids.length * step);
            this.RefreshGoodsContentSize(goods.node);
        }
    }

    private ClearSearchPlaceholders(): void {
        const placeholders = this._searchPlaceholders.splice(0);
        placeholders.forEach(node => this.ReleaseSearchPlaceholder(node));

        for (const [node] of Array.from(this._searchReservations.entries())) {
            this.ReleaseSearchPlaceholder(node);
        }
    }

    private BringSearchPlaceholdersToFront(): void {
        for (const placeholder of this._searchPlaceholders) {
            if (placeholder?.isValid && placeholder.parent) {
                placeholder.setSiblingIndex(placeholder.parent.children.length - 1);
            }
        }
    }

    private ReleaseSearchPlaceholder(node: Node): void {
        this.ClearSearchReservation(node);
        if (node?.isValid) {
            ZRSJZ_PoolManager.Instance.PutNode(node);
        }
    }

    private ClearSearchReservation(node: Node): void {
        if (!node) return;
        const reservation = this._searchReservations.get(node);
        if (!reservation) return;

        this._searchReservations.delete(node);
        this.ClearSearchReservationData(reservation);
    }

    private ClearSearchReservationData(reservation: ZRSJZ_SearchReservation): void {
        const { goods, token, gridX, gridY, width, height } = reservation;
        for (let row = gridY; row < gridY + height; row++) {
            for (let col = gridX; col < gridX + width; col++) {
                if (goods.Grids[row]?.[col] === token) {
                    goods.Grids[row][col] = "";
                }
            }
        }
    }

    /**
     * 兼容旧版物资弹窗：预制体没有“物资”区域时，在中间空白位置创建。
     * 后续若在预制体中手动添加 Panel/物资/View/Content，会优先使用预制体节点。
     */
    private EnsureGoodsContent(): Node {
        const existing = find("Panel/物资/View/Content", this.node);
        if (existing) {
            this.GoodsScrollView = find("Panel/物资", this.node)?.getComponent(ScrollView);
            return existing;
        }

        const panel = find("Panel", this.node);
        const goodsRoot = new Node("物资");
        goodsRoot.layer = this.node.layer;
        panel.addChild(goodsRoot);
        goodsRoot.setPosition(270, 0, 0);
        const rootTransform = goodsRoot.addComponent(UITransform);
        rootTransform.setContentSize(562, 941);

        const title = new Node("Tip");
        title.layer = this.node.layer;
        goodsRoot.addChild(title);
        title.setPosition(0, 442, 0);
        title.addComponent(UITransform).setContentSize(200, 60);
        const titleLabel = title.addComponent(Label);
        titleLabel.string = "物资";
        titleLabel.fontSize = 40;
        titleLabel.lineHeight = 54;

        const view = new Node("View");
        view.layer = this.node.layer;
        goodsRoot.addChild(view);
        view.setPosition(0, -30, 0);
        const viewTransform = view.addComponent(UITransform);
        viewTransform.setContentSize(552, 866);
        view.addComponent(Mask);

        const content = new Node("Content");
        content.layer = this.node.layer;
        view.addChild(content);
        content.setPosition(-276, 433, 0);
        const contentTransform = content.addComponent(UITransform);
        contentTransform.setAnchorPoint(0, 1);
        const goodsColumns = ZRSJZ_INVENTORY_CONFIG.get(ZRSJZ_INVENTORY.物资).Col;
        contentTransform.setContentSize(
            goodsColumns * (ZRSJZ_GRID_SIZE + ZRSJZ_GRID_INTERVAL),
            866,
        );

        this.GoodsScrollView = goodsRoot.addComponent(ScrollView);
        this.GoodsScrollView.content = content;
        this.GoodsScrollView.horizontal = goodsColumns > 4;
        this.GoodsScrollView.vertical = true;
        return content;
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_InventoryService } from "../Service/ZRSJZ_InventoryService";
import { ZRSJZ_AccountService } from "../Service/ZRSJZ_AccountService";
import { _decorator, EventTouch, find, Label, Node, ScrollView, tween, Tween, UIOpacity, UITransform, v2, Vec3 } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_INVENTORY, ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from '../Manager/ZRSJZ_EventManager';
import { ZRSJZ_Inventory } from '../UI/ZRSJZ_Inventory';
import { ZRSJZ_Prepare } from '../UI/ZRSJZ_Prepare';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_TaskService } from "../Service/ZRSJZ_TaskService";
const { ccclass, property } = _decorator;

const GridCol: number = 7;
@ccclass('ZRSJZ_WarehousePanel')
export class ZRSJZ_WarehousePanel extends ZRSJZ_Panel {

    PanelUIOpacity: UIOpacity = null;

    public Prepare: ZRSJZ_Prepare = null;
    public Content: Node = null;
    public ContentUITansform: UITransform = null;
    public ScrollView: ScrollView = null;

    public CheckedNode: Node = null;
    public SellMask: Node = null;
    public SellValue: Label = null;
    public ActualSellValue: Label = null;

    private _warehouseName: string = "";
    private _warehouseNode: Node = null;
    private _curInventory: Node = null;
    private _isSelling: boolean = false;
    private _isOrganizing: boolean = false;
    private _sellPropID: string[] = [];
    private _warehouseButtons: Node[] = [];
    private _playerLoadoutRefreshTask: Promise<void> = Promise.resolve();

    protected onLoad(): void {
        this.Prepare = find("Panel/备战", this.node).getComponent(ZRSJZ_Prepare);
        this.Content = find("Panel/仓库/Mask/Content", this.node);
        this.ContentUITansform = this.Content.getComponent(UITransform);
        this.ScrollView = find("Panel/仓库", this.node).getComponent(ScrollView);
        this.CheckedNode = find("Panel/仓库/物品按键/Checked", this.node);
        this.SellMask = find("Panel/仓库/SellMask", this.node);
        this.SellValue = find("总价值/Count", this.SellMask).getComponent(Label);
        this.ActualSellValue = find("卖出价值/Count", this.SellMask)?.getComponent(Label);
        this._warehouseNode = find("Panel/仓库/物品按键/全部", this.node);
        const buttonParent = this._warehouseNode?.parent;
        this._warehouseButtons = ["全部", "装备", "武器", "弹药", "物品"]
            .map(name => buttonParent?.getChildByName(name))
            .filter(button => button != null);
        this.RefreshWarehouseLocks();
    }

    protected onEnable(): void {
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP_ADD, this.AddSellProp, this);
        ZRSJZ_EventManager.On(ZRSJZ_MyEvent.ZRSJZ_PROP_MOVE, this.PropMove, this);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_WAREHOUSE_DROP, this.OnWarehouseDrop, this);
        ZRSJZ_EventManager.On(ZRSJZ_MyEvent.ZRSJZ_LOADOUT_PLAYER_CHANGE, this.OnLoadoutPlayerChange, this);
        this.OnLoadoutPlayerChange();
        this.RefreshWarehouseLocks();
    }

    protected onDisable(): void {
        // 弹窗被死亡流程强制关闭时，批量出售状态也必须一并清理。
        if (this._isSelling) {
            this._isSelling = false;
            this._sellPropID = [];
            if (this.SellMask) this.SellMask.active = false;
            if (this._curInventory?.isValid) {
                ZRSJZ_EventManager.EmitPersist(
                    ZRSJZ_MyEvent.ZRSJZ_SELL_PROP_HIDE,
                    this._curInventory.getComponent(ZRSJZ_Inventory)?.InventoryType,
                );
            }
        }
        if (this.ScrollView) this.ScrollView.enabled = true;
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP_ADD, this.AddSellProp, this);
        ZRSJZ_EventManager.Off(ZRSJZ_MyEvent.ZRSJZ_PROP_MOVE, this.PropMove, this);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_WAREHOUSE_DROP, this.OnWarehouseDrop, this);
        ZRSJZ_EventManager.Off(ZRSJZ_MyEvent.ZRSJZ_LOADOUT_PLAYER_CHANGE, this.OnLoadoutPlayerChange, this);
        this.ClearWarehouseDropFeedback();
    }

    protected start(): void {
        this.SwitchButton(this._warehouseNode);
    }

    // Show(...args: any[]) {
    //     if (!this.PanelUIOpacity) {
    //         this.Panel = find("Panel", this.node);
    //         this.PanelUIOpacity = this.Panel.getComponent(UIOpacity);
    //     }
    //     Tween.stopAllByTarget(this.PanelUIOpacity);
    //     this.PanelUIOpacity.opacity = 0;
    //     this.node.active = true;
    //     tween(this.PanelUIOpacity)
    //         .to(0.3, { opacity: 255 }, { easing: 'backOut' })
    //         .start();
    // }

    private OnLoadoutPlayerChange(): void {
        this._playerLoadoutRefreshTask = this._playerLoadoutRefreshTask.then(
            () => this.RefreshPlayerLoadout(),
            () => this.RefreshPlayerLoadout(),
        );
    }

    private async RefreshPlayerLoadout(): Promise<void> {
        const playerIndex = ZRSJZ_InventoryService.GetActivePlayerIndex();
        if (this.node.activeInHierarchy) await this.Prepare.Show(false, playerIndex);
    }

    //#region 仓库
    //初始化仓库
    async ShowInventory(inventoryName: string) {
        if (this._curInventory != null) {
            this._curInventory.active = false;
        }
        this._curInventory = await ZRSJZ_UIManager.Instance.GetInventory(`仓库_${inventoryName}`);
        this._curInventory.active = true;
        this._curInventory.parent = this.Content;
        this._curInventory.setPosition(Vec3.ZERO);
    }

    PropMove(move: boolean) {
        this.ScrollView.enabled = move;
    }

    //#region 按钮点击事件
    OnButtonClick(event: EventTouch) {
        if (ZRSJZ_UIManager.Dragging || this._isOrganizing) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Close":
                ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.仓库界面);
                break;
            case "批量出售":
                if (!this._isSelling) {
                    //开始选择售卖
                    this.SellMask.active = true;
                    this._isSelling = true;
                    this._sellPropID = [];
                    this.RefreshSellValue();
                    ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP_SHOW, this._curInventory.getComponent(ZRSJZ_Inventory).InventoryType);
                } else {
                    this._isSelling = false;
                    this.SellMask.active = false;
                    //售卖
                    ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP_HIDE, this._curInventory.getComponent(ZRSJZ_Inventory).InventoryType);
                    this.SellProp();
                    // console.error(this._sellPropID);
                }
                break;
            case "一键整理":
                void this.OrganizeCurrentWarehouse();
                break;
            case "Mask":
                this._isSelling = false;
                this.SellMask.active = false;
                this._sellPropID = [];
                this.RefreshSellValue();
                ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP_HIDE, this._curInventory.getComponent(ZRSJZ_Inventory).InventoryType);
                break;
            default:
                this.SwitchButton(event.getCurrentTarget());
                break;
        }
    }

    /** 只整理当前页签对应的仓库，不跨仓库移动道具。 */
    private async OrganizeCurrentWarehouse(): Promise<void> {
        if (this._isSelling) {
            ZRSJZ_UIManager.Instance.ShowTip("请先结束批量出售");
            return;
        }

        const inventoryNode = this._curInventory;
        const inventory = inventoryNode?.getComponent(ZRSJZ_Inventory);
        const expectedInventory = this.GetWarehouseInventory(this._warehouseName);
        if (
            !inventoryNode?.isValid
            || !inventory?.IsInitialized
            || inventory.InventoryType !== expectedInventory
        ) {
            ZRSJZ_UIManager.Instance.ShowTip("当前仓库尚未加载完成");
            return;
        }

        const hasProp = inventory.Grids.some(row => row.some(propID => propID !== ""));
        if (!hasProp) {
            ZRSJZ_UIManager.Instance.ShowTip("当前仓库没有需要整理的道具");
            return;
        }

        this._isOrganizing = true;
        this.ScrollView.enabled = false;
        try {
            const organized = await inventory.AutoOrganize();
            if (!organized) {
                ZRSJZ_UIManager.Instance.ShowTip("当前仓库整理失败");
                return;
            }

            // 整理后清除中间空行并同步可滚动高度。
            await inventory.ShowPropItem();
            if (this.ScrollView?.isValid) this.ScrollView.scrollToTop(0.2);
            ZRSJZ_UIManager.Instance.ShowTip("当前仓库整理完成");
        } catch (error) {
            console.error("[ZRSJZ_WarehousePanel] 当前仓库整理失败", error);
            ZRSJZ_UIManager.Instance.ShowTip("当前仓库整理失败");
        } finally {
            if (this.ScrollView?.isValid) this.ScrollView.enabled = true;
            this._isOrganizing = false;
        }
    }

    SwitchButton(warehouseNode: Node) {
        if (!warehouseNode) return;
        const inventory = this.GetWarehouseInventory(warehouseNode.name);
        if (!ZRSJZ_InventoryService.IsWarehouseUnlocked(inventory)) {
            ZRSJZ_UIManager.Instance.ShowPanel(
                ZRSJZ_PANEL.解锁仓库弹窗,
                warehouseNode.name,
                inventory,
                () => {
                    this.RefreshWarehouseLocks();
                    if (this.node.activeInHierarchy && warehouseNode.isValid) {
                        this.SwitchButton(warehouseNode);
                    }
                },
            );
            return;
        }
        const warehouseName = warehouseNode.name;
        if (this._warehouseName == warehouseName) return;
        this._warehouseName = warehouseName;
        Tween.stopAllByTarget(this.CheckedNode);
        tween(this.CheckedNode)
            .to(0.2, { position: warehouseNode.position.clone() }, { easing: 'backOut' })
            .call(() => {
                this.ShowWarehouseItem(warehouseNode);
            })
            .start();
        this.ShowInventory(warehouseName);
    }

    /** 外部解锁系统可直接调用，例如 panel.UnlockWarehouse(ZRSJZ_INVENTORY.仓库_武器)。 */
    public UnlockWarehouse(inventory: ZRSJZ_INVENTORY): boolean {
        const unlocked = ZRSJZ_InventoryService.UnlockWarehouse(inventory);
        this.RefreshWarehouseLocks();
        return unlocked;
    }

    private GetWarehouseInventory(name: string): ZRSJZ_INVENTORY {
        return `仓库_${name}` as ZRSJZ_INVENTORY;
    }

    private RefreshWarehouseLocks(): void {
        for (const button of this._warehouseButtons) {
            const inventory = this.GetWarehouseInventory(button.name);
            const locked = !ZRSJZ_InventoryService.IsWarehouseUnlocked(inventory);
            const lockNode = button.getChildByName("锁");
            if (lockNode) lockNode.active = locked;
            const checkedTrue = button.getChildByName("Checked_True");
            const checkedFalse = button.getChildByName("Checked_False");
            if (checkedTrue) checkedTrue.active = false;
            if (checkedFalse) checkedFalse.active = false;
        }
    }

    private OnWarehouseDrop(
        sourceInventory: ZRSJZ_INVENTORY,
        propID: string,
        worldPos: Vec3,
        isConfirm: boolean,
        setHandled: (handled: boolean) => void,
    ): void {
        this.ClearWarehouseDropFeedback();
        if (!worldPos) return;

        const targetButton = this._warehouseButtons.find(button =>
            button.getComponent(UITransform)?.getBoundingBoxToWorld().contains(v2(worldPos.x, worldPos.y))
        );
        if (!targetButton) return;

        const targetInventory = this.GetWarehouseInventory(targetButton.name);
        const unlocked = ZRSJZ_InventoryService.IsWarehouseUnlocked(targetInventory);
        const adaptive = this.CanPropEnterWarehouse(propID, targetInventory);
        const canTransfer = unlocked && adaptive && targetInventory !== sourceInventory;
        const feedback = targetButton.getChildByName(canTransfer ? "Checked_True" : "Checked_False");
        if (feedback) feedback.active = true;

        if (!isConfirm) return;

        // 命中按钮区后由仓库面板消费本次松手，锁定或不适配时也不能落入下方库存。
        setHandled?.(true);
        this.ClearWarehouseDropFeedback();
        if (targetInventory === sourceInventory) {
            ZRSJZ_UIManager.Instance.ShowTip("道具已经在该仓库中");
            return;
        }
        if (!unlocked) {
            ZRSJZ_UIManager.Instance.ShowTip(`${targetButton.name}仓库尚未解锁`);
            return;
        }

        const propData = ZRSJZ_GameData.Instance.PropData[propID];
        if (!propData) return;
        if (!adaptive) {
            ZRSJZ_UIManager.Instance.ShowTip(`该道具不能放入${targetButton.name}仓库`);
            return;
        }
        void this.TransferPropToWarehouse(sourceInventory, targetInventory, targetButton.name, propID);
    }

    private ClearWarehouseDropFeedback(): void {
        for (const button of this._warehouseButtons) {
            const checkedTrue = button.getChildByName("Checked_True");
            const checkedFalse = button.getChildByName("Checked_False");
            if (checkedTrue) checkedTrue.active = false;
            if (checkedFalse) checkedFalse.active = false;
        }
    }

    private CanPropEnterWarehouse(propID: string, inventory: ZRSJZ_INVENTORY): boolean {
        const propType = ZRSJZ_GameData.Instance.PropData[propID]?.PropType;
        if (!propType) return false;
        switch (inventory) {
            case ZRSJZ_INVENTORY.仓库_全部:
                return true;
            case ZRSJZ_INVENTORY.仓库_装备:
                return propType === "头盔" || propType === "防弹衣" || propType === "背包";
            case ZRSJZ_INVENTORY.仓库_武器:
                return propType === "枪" || propType === "刀";
            case ZRSJZ_INVENTORY.仓库_弹药:
                return propType === "弹药";
            case ZRSJZ_INVENTORY.仓库_物品:
                return propType === "物品" || propType === "门禁卡" || propType === "房卡";
            default:
                return false;
        }
    }

    private async TransferPropToWarehouse(
        sourceInventory: ZRSJZ_INVENTORY,
        targetInventory: ZRSJZ_INVENTORY,
        targetName: string,
        propID: string,
    ): Promise<void> {
        try {
            const targetNode = await ZRSJZ_UIManager.Instance.GetInventory(targetInventory);
            const target = targetNode?.getComponent(ZRSJZ_Inventory);
            if (!target || !target.IsAdaptive(propID)) {
                ZRSJZ_UIManager.Instance.ShowTip(`该道具不能放入${targetName}仓库`);
                return;
            }
            const moved = await target.TryReceiveProp(sourceInventory, propID, true);
            if (!moved) {
                ZRSJZ_UIManager.Instance.ShowTip(`${targetName}仓库空间不足`);
            }
        } finally {
            // 成功、失败或异步加载异常都恢复两边仓库的格子显示状态。
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_GRID_SHOW, sourceInventory);
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_GRID_SHOW, targetInventory);
        }
    }

    ShowWarehouseItem(target: Node) {
        if (this._warehouseNode) {
            find("默认", this._warehouseNode).active = true;
            find("选中", this._warehouseNode).active = false;
        }
        this._warehouseNode = target;
        find("默认", this._warehouseNode).active = false;
        find("选中", this._warehouseNode).active = true;
    }

    AddSellProp(propID: string) {
        if (this._sellPropID.includes(propID)) {
            this._sellPropID.splice(this._sellPropID.indexOf(propID), 1);
        } else {
            this._sellPropID.push(propID);
        }
        this.RefreshSellValue();
    }

    SellProp() {
        let totalValue = 0;
        let tatalCount = 0;
        this._sellPropID.forEach(propID => {
            const propData = ZRSJZ_GameData.Instance.PropData[propID];
            if (!propData) return;

            totalValue += ZRSJZ_InventoryService.GetPropSellValue(propData);
            tatalCount += propData.CurCount;
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP, propID);
            ZRSJZ_InventoryService.RemovePropID(propID);
        });
        if (totalValue > 0) {
            ZRSJZ_AccountService.ChangeGold(totalValue);
            ZRSJZ_UIManager.Instance.ShowCurrencyEffect();
            ZRSJZ_TaskService.CompleteTask("出售任意物品", tatalCount);
        }
        this._sellPropID = [];
        this.RefreshSellValue();
    }

    private RefreshSellValue() {
        const totalValue = this._sellPropID.reduce((value, propID) => {
            const propData = ZRSJZ_GameData.Instance.PropData[propID];
            return value + (propData ? propData.UnitPrice * propData.CurCount : 0);
        }, 0);
        this.SellValue.string = FormatMoney(totalValue);
        const actualValue = this._sellPropID.reduce((value, propID) =>
            value + ZRSJZ_InventoryService.GetPropSellValue(ZRSJZ_GameData.Instance.PropData[propID]), 0);
        if (this.ActualSellValue) this.ActualSellValue.string = FormatMoney(actualValue);
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, EventTouch, find, Label, Node, ScrollView, sp, tween, Tween, UITransform, Vec3 } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_GRID_INTERVAL, ZRSJZ_GRID_SIZE, ZRSJZ_INVENTORY, ZRSJZ_PANEL } from '../ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_PoolManager } from '../Manager/ZRSJZ_PoolManager';
import { ZRSJZ_PropGrid } from '../UI/ZRSJZ_PropGrid';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ProjectEvent, ProjectEventManager } from 'db://assets/Scripts/Framework/Managers/ProjectEventManager';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_WinPanel')
export class ZRSJZ_WinPanel extends ZRSJZ_Panel {

    Earnings: Label = null;
    Evacuate: Label = null;
    BattleTime: Label = null;
    KillCount: Label = null;
    Skeleton: sp.Skeleton = null;
    Point: Node = null;
    Mask: Node = null;
    PropContent: Node = null;
    PropScrollView: ScrollView = null;

    private readonly _propColumnCount: number = 6;
    private _showPropVersion: number = 0;
    private _propNodeVersions: Map<Node, number> = new Map<Node, number>();
    private _isReturning: boolean = false;

    protected onLoad(): void {
        this.Earnings = find("Panel/收益/Earnings", this.node).getComponent(Label);
        this.Evacuate = find("Panel/Desc/撤离方式/Count", this.node).getComponent(Label);
        this.BattleTime = find("Panel/Desc/对局时间/Count", this.node).getComponent(Label);
        this.KillCount = find("Panel/Desc/击杀人数/Count", this.node).getComponent(Label);
        this.Skeleton = find("Panel/WinSkeleton", this.node).getComponent(sp.Skeleton);
        this.Point = find("Panel/WinPoint", this.node);
        this.Mask = find("Panel/Mask", this.node);
        this.PropContent = find("Panel/物资框/View/Content", this.node);
        this.PropScrollView = find("Panel/物资框", this.node).getComponent(ScrollView);
    }

    Show(...args: any[]) {
        super.Show();
        this._isReturning = false;
        this.Mask.active = true;
        this.Evacuate.string = args[0];
        this.BattleTime.string = args[1];
        this.KillCount.string = args[2];
        this.ShowAllProp(args[3]);
        Tween.stopAllByTarget(this.Skeleton.node);
        // this.Skeleton.node.setPosition(Vec3.ZERO);
        this.Skeleton.node.setScale(1, 1, 1);
        this.Skeleton.setAnimation(0, "shengli", false);
        this.Skeleton.setCompleteListener(() => {
            this.Skeleton.setAnimation(0, "daiji", true);
            this.Mask.active = false;
            tween(this.Skeleton.node)
                .to(0.3, { worldPosition: this.Point.worldPosition.clone() }, { easing: 'circIn' })
                .start();
            tween(this.Skeleton.node)
                .to(0.3, { scale: Vec3.ONE }, { easing: 'circIn' })
                .start();
        });
        ProjectEventManager.emit(ProjectEvent.游戏结束, "真人三角洲");
    }

    async ShowAllProp(propID: string[]) {
        const showVersion = ++this._showPropVersion;
        const propIDs = Array.isArray(propID) ? propID : [];
        const occupiedGrids: boolean[][] = [];
        const propPlacements: {
            id: string,
            gridX: number,
            gridY: number,
            width: number,
            height: number,
        }[] = [];
        let earnings = 0;
        let occupiedRowCount = 0;

        this.ClearPropContent();

        for (const id of propIDs) {
            const propData = ZRSJZ_GameData.Instance.PropData[id];
            if (!propData) {
                console.warn(`[ZRSJZ_WinPanel] 未找到战利品ID: ${id}`);
                continue;
            }

            earnings += propData.UnitPrice * propData.CurCount;
            const width = Math.max(1, Math.min(this._propColumnCount, Math.floor(propData.Width || 1)));
            const height = Math.max(1, Math.floor(propData.Height || 1));
            const gridPos = this.FindPropGrid(occupiedGrids, width, height);
            this.OccupyPropGrid(occupiedGrids, gridPos.x, gridPos.y, width, height);
            propPlacements.push({ id, gridX: gridPos.x, gridY: gridPos.y, width, height });
            occupiedRowCount = Math.max(occupiedRowCount, gridPos.y + height);
        }

        const contentHeight = occupiedRowCount === 0
            ? 0
            : occupiedRowCount * ZRSJZ_GRID_SIZE + (occupiedRowCount - 1) * ZRSJZ_GRID_INTERVAL;
        this.PropContent.getComponent(UITransform).height = contentHeight;
        this.Earnings.string = FormatMoney(earnings);

        for (const placement of propPlacements) {
            if (showVersion !== this._showPropVersion) return;

            const propNode = await ZRSJZ_PoolManager.Instance.GetNode("Prefabs/UI/PropGrid");
            if (!propNode) continue;

            const propGrid = propNode.getComponent(ZRSJZ_PropGrid);
            propNode.active = false;
            propGrid.enabled = false;
            propNode.parent = this.PropContent;
            this._propNodeVersions.set(propNode, showVersion);
            propNode.setPosition(
                placement.gridX * (ZRSJZ_GRID_SIZE + ZRSJZ_GRID_INTERVAL),
                -placement.gridY * (ZRSJZ_GRID_SIZE + ZRSJZ_GRID_INTERVAL),
            );
            propNode.getComponent(UITransform).setContentSize(
                placement.width * ZRSJZ_GRID_SIZE + (placement.width - 1) * ZRSJZ_GRID_INTERVAL,
                placement.height * ZRSJZ_GRID_SIZE + (placement.height - 1) * ZRSJZ_GRID_INTERVAL,
            );
            // 结算界面使用自己计算的紧凑网格，不继承道具在库存中的旋转状态。
            // 必须把坐标传给 Init，否则初始化方向时会按默认的 (-1, -1) 重置位置，导致全部重叠。
            await propGrid.Init(
                placement.id,
                placement.gridX,
                placement.gridY,
                ZRSJZ_INVENTORY.仓库_全部,
                false,
            );

            if (showVersion !== this._showPropVersion || !this.node.active) {
                if (this._propNodeVersions.get(propNode) === showVersion) {
                    this.PutPropNode(propNode);
                }
                return;
            }

            propNode.active = true;
        }

        if (showVersion !== this._showPropVersion) return;

        this.scheduleOnce(() => {
            if (showVersion === this._showPropVersion && this.node.active) {
                this.PropScrollView.scrollToTop();
            }
        });
    }

    private ClearPropContent(): void {
        for (const child of [...this.PropContent.children]) {
            this.PutPropNode(child);
        }
        this.PropContent.getComponent(UITransform).height = 0;
    }

    private FindPropGrid(grids: boolean[][], width: number, height: number): { x: number, y: number } {
        for (let y = 0; ; y++) {
            for (let x = 0; x <= this._propColumnCount - width; x++) {
                let canPlace = true;
                for (let row = y; row < y + height && canPlace; row++) {
                    for (let col = x; col < x + width; col++) {
                        if (grids[row]?.[col]) {
                            canPlace = false;
                            break;
                        }
                    }
                }
                if (canPlace) return { x, y };
            }
        }
    }

    private OccupyPropGrid(
        grids: boolean[][],
        gridX: number,
        gridY: number,
        width: number,
        height: number,
    ): void {
        for (let row = gridY; row < gridY + height; row++) {
            if (!grids[row]) grids[row] = new Array(this._propColumnCount).fill(false);
            for (let col = gridX; col < gridX + width; col++) {
                grids[row][col] = true;
            }
        }
    }

    private PutPropNode(propNode: Node): void {
        const propGrid = propNode.getComponent(ZRSJZ_PropGrid);
        this._propNodeVersions.delete(propNode);
        propNode.getComponent(UITransform)?.setContentSize(ZRSJZ_GRID_SIZE, ZRSJZ_GRID_SIZE);
        ZRSJZ_PoolManager.Instance.PutNode(propNode);
        if (propGrid) propGrid.enabled = true;
    }

    public async OnButtonClick(event: EventTouch): Promise<void> {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Mask":
                if (this._isReturning) return;
                this._isReturning = true;
                await ZRSJZ_UIManager.Instance.FinishGameInventory(true);
                ZRSJZ_UIManager.Instance.ShowPanel(ZRSJZ_PANEL.加载界面, "ZRSJZ_Start");
                ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.胜利弹窗);
                break;
        }
    }


}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_AccountService } from "../Service/ZRSJZ_AccountService";
import { _decorator, Button, EventHandler, EventTouch, find, instantiate, Label, Node, Prefab, sp, Sprite, SpriteFrame, Tween, tween } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_PANEL, ZRSJZ_PROP_CONFIG, ZRSJZ_PROP_PROPERTY, ZRSJZ_PROP_PROPERTY_MAX, ZRSJZ_PROP_QUALITY, ZRSJZ_SHOP_CONFIG, ZRSJZ_WEAPON_SKIN } from '../ZRSJZ_Constant';
import { ZRSJZ_PoolManager } from '../Manager/ZRSJZ_PoolManager';
import { ZRSJZ_ShopItem } from '../UI/ZRSJZ_ShopItem';
import { ZRSJZ_Tools } from '../ZRSJZ_Tools';
import { ZRSJZ_ShopStats } from '../UI/ZRSJZ_ShopStats';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import Banner from 'db://assets/Scripts/Banner';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_ShowPanel')
export class ZRSJZ_ShowPanel extends ZRSJZ_Panel {

    @property(Prefab)
    WeaponSkin: Prefab = null;

    @property(SpriteFrame)
    SkineTypeSFs: SpriteFrame[] = [];

    public CheckedNode: Node = null;
    public ShopTypeNode: Node = null;
    public ShopItemContent: Node = null;
    public ShopIcon: Sprite = null;
    public ShopName: Label = null;
    public ShopLeft: Node = null;
    public ShopRight: Node = null;
    public Shop: Node = null;
    public ShopPurchase: Node = null;
    public ShopVideo: Node = null;
    public ShopUse: Node = null;
    public ShopUsing: Node = null;
    public ShopPrice: Label = null;
    public ShopCurrency: Node = null;
    public ShopDesc: Label = null;
    public ShopProperty: Node = null;
    public ShopSkin: Node = null;
    public EffectSkeleton: sp.Skeleton = null;;

    private _shopPropertyMap: Map<string, ZRSJZ_ShopStats> = new Map<string, ZRSJZ_ShopStats>();
    private _shopType: string = "";
    private _curShop: string = "";
    private _curShops: string[] = [];
    private _curShopsTs: ZRSJZ_ShopItem[] = [];
    private _curShowIndex: number = 0;
    private _shopPrice: number = 0;
    private _scale: number = 2;
    private _selectedWeaponSkin: string = null;
    private _isWeaponSkinOperation: boolean = false;
    private _weaponSkinNodes: Node[] = [];
    private _shopListVersion: number = 0;
    private _shopDisplayVersion: number = 0;
    private _isPurchasing: boolean = false;

    protected onLoad(): void {
        this.CheckedNode = find("Panel/商品类型/Checked", this.node);
        this.ShopTypeNode = find("Panel/商品类型/武器", this.node);
        this.ShopItemContent = find("Panel/商品/view/Content", this.node);
        this.ShopIcon = find("Panel/展示/Icon", this.node).getComponent(Sprite);
        this.ShopName = find("Panel/展示/Name", this.node).getComponent(Label);
        this.ShopLeft = find("Panel/展示/上一个", this.node);
        this.ShopRight = find("Panel/展示/下一个", this.node);
        this.Shop = find("Panel/商品", this.node);
        this.ShopPurchase = find("Panel/购买", this.node);
        this.ShopVideo = find("Panel/视频获取", this.node);
        this.ShopUse = find("Panel/使用", this.node);
        this.ShopUsing = find("Panel/使用中", this.node);
        const useButton = this.ShopUse.getComponent(Button) ?? this.ShopUse.addComponent(Button);
        const useClickEvent = new EventHandler();
        useClickEvent.target = this.node;
        useClickEvent.component = "ZRSJZ_ShowPanel";
        useClickEvent.handler = "OnButtonClick";
        useButton.clickEvents = [useClickEvent];
        this.ShopPrice = find("Panel/购买/Price", this.node).getComponent(Label);
        this.ShopCurrency = find("Panel/购买/金币", this.node);
        this.ShopDesc = find("Panel/详情/描述/Desc", this.node).getComponent(Label);
        this.ShopProperty = find("Panel/详情/属性", this.node);
        this.ShopSkin = find("Panel/详情/皮肤", this.node);
        this.EffectSkeleton = find("Panel/展示/Effect", this.node).getComponent(sp.Skeleton);

        this.ShopProperty.getChildByName("Layout").children.forEach(child => {
            const shopStats = child.getComponent(ZRSJZ_ShopStats);
            shopStats.Init();
            this._shopPropertyMap.set(child.name, shopStats);
        });
    }

    protected onEnable(): void {
        this.SwitchButton(this.ShopTypeNode, true);
    }

    OnButtonClick(event: EventTouch) {
        if (ZRSJZ_UIManager.Dragging) return;
        const targetNode = event.getCurrentTarget();
        const targetName = targetNode.name;
        const shopTypes = ["武器", "头盔", "防弹衣", "背包", "匕首", "弹药", "房卡"];
        // 当前商品分类已选中时，不播放音效，也不重复刷新商品列表。
        if (shopTypes.includes(targetName) && targetName === this._shopType) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (targetName) {
            case "Close":
                ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.商店界面);
                break;
            case "购买":
                this.OnPurchase();
                break;
            case "视频获取":
                this.OnWatchWeaponSkinVideo();
                break;
            case "使用":
                this.OnUseWeaponSkin();
                break;
            case "使用中":
                break;
            case "上一个":
                this._curShopsTs[this._curShowIndex].Chekcked.active = false;
                this._curShowIndex--;
                this.ShowShop();
                this.TweenShop();
                break;
            case "下一个":
                this._curShopsTs[this._curShowIndex].Chekcked.active = false;
                this._curShowIndex++;
                this.ShowShop();
                this.TweenShop();
                break;
            case "武器":
            case "头盔":
            case "防弹衣":
            case "背包":
            case "匕首":
            case "弹药":
            case "房卡":
                this._scale = targetName == "防弹衣" || targetName == "背包" ? 1 : 2;
                this.SwitchButton(targetNode);
                break;
            default:
                if (targetName.startsWith("WeaponSkin_")) {
                    const skinIndex = Number(targetName.replace("WeaponSkin_", ""));
                    const skins = ZRSJZ_WEAPON_SKIN.get(this._curShop);
                    if (skins?.[skinIndex]) {
                        this._selectedWeaponSkin = skins[skinIndex].Name;
                        this._isWeaponSkinOperation = true;
                        this.ShowShopPreview(this._selectedWeaponSkin);
                        this.RefreshWeaponSkinState();
                        this.RefreshPurchaseState();
                    }
                    break;
                }
                const clickIndex = Number(targetName);
                if (clickIndex == this._curShowIndex) {
                    this._isWeaponSkinOperation = false;
                    this._selectedWeaponSkin = ZRSJZ_AccountService.GetWeaponSkin(this._curShop);
                    this.ShowShopPreview(this._curShop);
                    this.RefreshWeaponSkinState();
                    this.RefreshPurchaseState();
                    break;
                }
                this._curShopsTs[this._curShowIndex].Chekcked.active = false;
                this._curShowIndex = clickIndex;
                this.ShowShop();
                break;
        }
    }

    SwitchButton(shopTypeNode: Node, isShow: boolean = false) {
        const shopType = shopTypeNode.name;
        if (this._shopType == shopType && !isShow) return;
        this.ShopPurchase.active = false;
        this.ShopVideo.active = false;
        this.ShopLeft.active = false;
        this.ShopRight.active = false;
        this._shopType = shopType;
        Tween.stopAllByTarget(this.CheckedNode);
        tween(this.CheckedNode)
            .to(0.2, { position: shopTypeNode.position.clone() }, { easing: 'backOut' })
            .call(() => {
                this.ShowShopItem();
            })
            .start();
    }

    async ShowShopItem() {
        const version = ++this._shopListVersion;
        const shops = ZRSJZ_SHOP_CONFIG.get(this._shopType) ?? [];
        this._curShops = shops;
        this._curShowIndex = 0;
        this.RemoveShopItem();
        this._curShopsTs = [];
        const shopItems = await Promise.all(shops.map(async (shopName, index) => {
            const shopItem: Node = await ZRSJZ_PoolManager.Instance.GetNode("Prefabs/UI/ShopItem");
            shopItem.name = index.toString();
            await shopItem.getComponent(ZRSJZ_ShopItem).Init(shopName);
            const clickEventHandler = new EventHandler();
            clickEventHandler.target = this.node;
            clickEventHandler.component = "ZRSJZ_ShowPanel";
            clickEventHandler.handler = "OnButtonClick";
            const button = shopItem.getComponent(Button);
            if (button) button.clickEvents = [clickEventHandler];
            return shopItem;
        }));

        this.ShopPurchase.active = true;
        this.ShowShopButton();
        if (version !== this._shopListVersion) {
            shopItems.forEach(shopItem => ZRSJZ_PoolManager.Instance.PutNode(shopItem));
            return;
        }
        shopItems.forEach(shopItem => shopItem.parent = this.ShopItemContent);
        this._curShopsTs = shopItems.map(shopItem => shopItem.getComponent(ZRSJZ_ShopItem));
        if (this._curShopsTs.length > 0) this.ShowShop();

    }

    RemoveShopItem() {
        for (let index: number = this.ShopItemContent.children.length - 1; index >= 0; index--) {
            ZRSJZ_PoolManager.Instance.PutNode(this.ShopItemContent.children[index]);
        }
    }

    ShowShopButton() {
        const canSwitchGoods = this._shopType !== "房卡";
        this.ShopLeft.active = canSwitchGoods && this._curShowIndex > 0;
        this.ShopRight.active = canSwitchGoods && this._curShowIndex < this._curShops.length - 1;
    }

    async ShowShop() {
        const version = ++this._shopDisplayVersion;
        this.ShowShopButton();
        this._curShop = this._curShops[this._curShowIndex];
        this._selectedWeaponSkin = null;
        this._isWeaponSkinOperation = false;
        this.ClearWeaponSkinNodes();
        this.ShopSkin.active = false;
        this.ShopName.string = this._curShop;
        const shopIcon = await ZRSJZ_UIManager.Instance.GetPropUI(this._curShop);
        if (version !== this._shopDisplayVersion) return;
        this.ShopIcon.spriteFrame = shopIcon;
        const shopData = ZRSJZ_PROP_CONFIG.get(this._curShop);
        // this._shopPrice = shopData.UnitPrice * shopData.MaxCount;
        this._shopPrice = Math.floor(shopData.UnitPrice);
        this.ShopPrice.string = FormatMoney(this._shopPrice, true);
        this._curShopsTs[this._curShowIndex].Chekcked.active = true;
        ZRSJZ_Tools.ScaleNodeToFit(this.ShopIcon.node, 500, 200);
        // this.ShopIcon.node.setScale(this._scale, this._scale, 1);
        this.ShowShopDesc(this._curShop);
        this.RefreshPurchaseState();
        this.EffectSkeleton.setAnimation(0, "1", false);
    }

    ShowShopDesc(shopName: string) {
        //显示商品描述
        this.ShopDesc.string = ZRSJZ_PROP_CONFIG.get(shopName).Description;

        //显示商品属性
        if (ZRSJZ_PROP_PROPERTY.has(shopName)) {
            this.ShopProperty.active = true;
            const shopProperty = ZRSJZ_PROP_PROPERTY.get(shopName);
            for (const [key, shopStats] of this._shopPropertyMap) {
                if (shopProperty.hasOwnProperty(key)) {
                    shopStats.Show(shopProperty[key], ZRSJZ_PROP_PROPERTY_MAX.get(key))
                } else {
                    shopStats.Hide();
                }
            }
        } else {
            this.ShopProperty.active = false;
        }

        this.ShowWeaponSkins(shopName);
    }

    private async ShowWeaponSkins(weaponName: string): Promise<void> {
        this.ClearWeaponSkinNodes();
        const skins = ZRSJZ_WEAPON_SKIN.get(weaponName);
        this.ShopSkin.active = !!skins?.length;
        if (!skins?.length) return;

        for (let index = 0; index < skins.length; index++) {
            // ShowShop 可能在图片加载期间切换到了其他商品，旧列表不再继续创建。
            if (weaponName !== this._curShop) return;
            const skinConfig = skins[index];
            const skinName = skinConfig.Name;
            const skinNode = instantiate(this.WeaponSkin);
            skinNode.name = `WeaponSkin_${index}`;
            skinNode.active = true;
            skinNode.parent = this.ShopSkin.getChildByName("皮肤");
            const iconSpriteFrame = await ZRSJZ_UIManager.Instance.GetPropUI(skinName);
            const icon = skinNode.getChildByName("Icon")?.getComponent(Sprite);
            if (icon) icon.spriteFrame = iconSpriteFrame;
            const qualitySprite = skinNode.getComponent(Sprite);
            if (qualitySprite) qualitySprite.spriteFrame = this.GetSkinQualitySpriteFrame(skinConfig.Quality);
            if (weaponName !== this._curShop) {
                skinNode.destroy();
                return;
            }

            const nameLabel = skinNode.getChildByName("Name")?.getComponent(Label);
            if (nameLabel) nameLabel.string = skinName;

            const button = skinNode.getComponent(Button) ?? skinNode.addComponent(Button);
            const clickEventHandler = new EventHandler();
            clickEventHandler.target = this.node;
            clickEventHandler.component = "ZRSJZ_ShowPanel";
            clickEventHandler.handler = "OnButtonClick";
            button.clickEvents = [clickEventHandler];
            this._weaponSkinNodes.push(skinNode);
        }
        if (!this._isWeaponSkinOperation) {
            this._selectedWeaponSkin = ZRSJZ_AccountService.GetWeaponSkin(weaponName);
        }
        this.RefreshWeaponSkinState();
        this.RefreshPurchaseState();
    }

    private ClearWeaponSkinNodes(): void {
        this._weaponSkinNodes.forEach(node => node?.isValid && node.destroy());
        this._weaponSkinNodes = [];
    }

    private async ShowShopPreview(spriteName: string): Promise<void> {
        const shopName = this._curShop;
        const spriteFrame = await ZRSJZ_UIManager.Instance.GetPropUI(spriteName);
        if (shopName !== this._curShop) return;
        if (this._isWeaponSkinOperation && spriteName !== this._selectedWeaponSkin) return;
        if (!this._isWeaponSkinOperation && spriteName !== shopName) return;

        this.ShopIcon.spriteFrame = spriteFrame;
        ZRSJZ_Tools.ScaleNodeToFit(this.ShopIcon.node, 500, 200);
        this.ShopIcon.node.setScale(this._scale, this._scale, 1);
    }

    /** SkineTypeSFs 顺序：白、蓝、紫、金、红；绿色暂无专用资源，回退到白色框。 */
    private GetSkinQualitySpriteFrame(quality: ZRSJZ_PROP_QUALITY): SpriteFrame {
        const indexMap: Partial<Record<ZRSJZ_PROP_QUALITY, number>> = {
            [ZRSJZ_PROP_QUALITY.白色]: 0,
            [ZRSJZ_PROP_QUALITY.绿色]: 0,
            [ZRSJZ_PROP_QUALITY.蓝色]: 1,
            [ZRSJZ_PROP_QUALITY.紫色]: 2,
            [ZRSJZ_PROP_QUALITY.金色]: 3,
            [ZRSJZ_PROP_QUALITY.红色]: 4,
        };
        return this.SkineTypeSFs[indexMap[quality] ?? 0] ?? this.SkineTypeSFs[0] ?? null;
    }

    private RefreshWeaponSkinState(): void {
        const skins = ZRSJZ_WEAPON_SKIN.get(this._curShop) ?? [];
        this._weaponSkinNodes.forEach((skinNode, index) => {
            const skinName = skins[index]?.Name;
            if (!skinName) return;
            const checked = skinNode.getChildByName("Checked");
            if (checked) checked.active = skinName === this._selectedWeaponSkin;
        });
    }

    private RefreshPurchaseState(): void {
        if (!this._isWeaponSkinOperation || !this._selectedWeaponSkin) {
            this.ShopPurchase.active = true;
            this.ShopVideo.active = false;
            this.ShopUse.active = false;
            this.ShopUsing.active = false;
            this.ShopCurrency.active = true;
            this.ShopPrice.string = FormatMoney(this._shopPrice, true);
            return;
        }

        const owned = ZRSJZ_AccountService.HasWeaponSkin(this._curShop, this._selectedWeaponSkin);
        const using = ZRSJZ_AccountService.GetWeaponSkin(this._curShop) === this._selectedWeaponSkin;
        const skinConfig = ZRSJZ_WEAPON_SKIN.get(this._curShop)
            ?.find(skin => skin.Name === this._selectedWeaponSkin);
        this.ShopPurchase.active = !owned && skinConfig?.UnlockType === "金币";
        this.ShopVideo.active = !owned && skinConfig?.UnlockType === "视频";
        this.ShopUse.active = owned && !using;
        this.ShopUsing.active = using;
        this.ShopCurrency.active = true;
        this.ShopPrice.string = skinConfig === undefined ? "未配置" : FormatMoney(skinConfig.Price, true);
    }

    private async OnPurchase(): Promise<void> {
        if (this._isWeaponSkinOperation && this._selectedWeaponSkin) {
            const owned = ZRSJZ_AccountService.HasWeaponSkin(this._curShop, this._selectedWeaponSkin);
            if (owned) {
                this.RefreshPurchaseState();
                return;
            }

            const skinConfig = ZRSJZ_WEAPON_SKIN.get(this._curShop)
                ?.find(skin => skin.Name === this._selectedWeaponSkin);
            if (!skinConfig || skinConfig.UnlockType !== "金币") {
                ZRSJZ_UIManager.Instance.ShowTip("该皮肤不能使用金币购买");
                return;
            }

            if (ZRSJZ_GameData.Instance.Gold < skinConfig.Price) {
                ZRSJZ_UIManager.Instance.ShowTip("金币不足");
                return;
            }
            ZRSJZ_AccountService.ChangeGold(-skinConfig.Price);
            ZRSJZ_AccountService.AddWeaponSkin(this._curShop, this._selectedWeaponSkin);
            this.RefreshWeaponSkinState();
            this.RefreshPurchaseState();
            ZRSJZ_UIManager.Instance.ShowTip("皮肤购买成功");
            return;
        }

        const shopData = ZRSJZ_PROP_CONFIG.get(this._curShop);
        if (shopData?.PropType === "弹药") {
            ZRSJZ_UIManager.Instance.ShowPanel(
                ZRSJZ_PANEL.购买子弹弹窗,
                this._curShop,
            );
            return;
        }

        if (this._isPurchasing || !shopData) return;
        this._isPurchasing = true;
        const shopName = this._curShop;
        const shopPrice = this._shopPrice;
        const count = shopData.MaxCount ?? 1;
        try {
            const awards = [{ PropName: shopName, Count: count }];
            if (!await ZRSJZ_UIManager.Instance.CanReceivePropAwards(awards)) {
                ZRSJZ_UIManager.Instance.ShowTip("仓库已满，请先整理仓库！");
                return;
            }
            if (ZRSJZ_GameData.Instance.Gold < shopPrice) {
                ZRSJZ_UIManager.Instance.ShowTip("金币不足");
                return;
            }
            ZRSJZ_AccountService.ChangeGold(-shopPrice);
            await ZRSJZ_UIManager.Instance.ReceivePropAwards(awards);
            ZRSJZ_UIManager.Instance.ShowTip("购买成功");
        } finally {
            this._isPurchasing = false;
        }
    }

    private async OnWatchWeaponSkinVideo(): Promise<void> {
        if (!this._isWeaponSkinOperation || !this._selectedWeaponSkin) return;

        const weaponName = this._curShop;
        const skinName = this._selectedWeaponSkin;
        const skinConfig = ZRSJZ_WEAPON_SKIN.get(weaponName)
            ?.find(skin => skin.Name === skinName);
        if (!skinConfig || skinConfig.UnlockType !== "视频") {
            ZRSJZ_UIManager.Instance.ShowTip("该皮肤不能通过视频解锁");
            return;
        }
        if (ZRSJZ_AccountService.HasWeaponSkin(weaponName, skinName)) {
            this.RefreshPurchaseState();
            return;
        }

        Banner.Instance.ShowVideoAd(async () => {
            ZRSJZ_AccountService.AddWeaponSkin(weaponName, skinName);
            this.RefreshWeaponSkinState();
            this.RefreshPurchaseState();
            ZRSJZ_UIManager.Instance.ShowTip("视频观看完成，皮肤已解锁");
        });
    }

    private async OnUseWeaponSkin(): Promise<void> {
        if (!this._isWeaponSkinOperation || !this._selectedWeaponSkin) return;
        if (!ZRSJZ_AccountService.HasWeaponSkin(this._curShop, this._selectedWeaponSkin)) {
            this.RefreshPurchaseState();
            return;
        }
        if (!ZRSJZ_AccountService.SetWeaponSkin(this._curShop, this._selectedWeaponSkin)) {
            ZRSJZ_UIManager.Instance.ShowTip("皮肤使用失败");
            return;
        }
        this.RefreshWeaponSkinState();
        this.RefreshPurchaseState();
        ZRSJZ_UIManager.Instance.ShowTip("皮肤使用成功");
    }

    TweenShop() {
        Tween.stopAllByTarget(this.ShopItemContent);
        const offset: number = this.Shop.worldPosition.x - this.ShopItemContent.children[this._curShowIndex].worldPosition.x;
        tween(this.ShopItemContent)
            .to(0.3, { x: this.ShopItemContent.x + offset }, { easing: 'backOut' })
            .start();
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, EventTouch, find, Label, Node } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { GetSpecialOperationConfig, ZRSJZ_PANEL, ZRSJZ_SPECIAL_OPERATION_CONFIG, ZRSJZ_SpecialOperationConfig } from '../ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_PoolManager } from '../Manager/ZRSJZ_PoolManager';
import { ZRSJZ_TaskAward } from '../UI/ZRSJZ_TaskAward';
import { ZRSJZ_Game } from '../ZRSJZ_Game';
import { ZRSJZ_SpecialOperationsTaskIcon } from '../Unit/ZRSJZ_SpecialOperationsTaskIcon';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_SpecialOperationsPanel')
export class ZRSJZ_SpecialOperationsPanel extends ZRSJZ_Panel {

    TaskDesc: Label = null;
    TaskAwardCount: Label = null;
    Time: Label = null;
    TaskAwardContent: Node = null;
    private _mapKey: string = "";
    private _sourceTaskPoint: ZRSJZ_SpecialOperationsTaskIcon = null;
    private _requestPlayerIndex: number = 0;
    private _currentConfig: Readonly<ZRSJZ_SpecialOperationConfig> = null;
    private _refreshVersion: number = 0;

    protected onLoad(): void {
        this.TaskDesc = find("Panel/TaskDesc", this.node).getComponent(Label);
        // 预制体中钞票数量和概率奖励列表的节点都叫 TaskAward，不能用同一条 find 路径查找。
        this.TaskAwardCount = find("Panel/TaskAward", this.node).getComponent(Label);
        this.Time = find("Panel/Time", this.node).getComponent(Label);
        const panel = find("Panel", this.node);
        const propAwardRoot = panel.children.find(child =>
            child.name === "TaskAward" && !!child.getChildByName("View"),
        );
        this.TaskAwardContent = propAwardRoot?.getChildByName("View")?.getChildByName("Content") ?? null;
    }

    public Show(...args: any[]): void {
        super.Show();
        this._mapKey = typeof args[0] === "string" ? args[0] : ZRSJZ_GameData.Instance.CurMap;
        this._sourceTaskPoint = args[1] instanceof ZRSJZ_SpecialOperationsTaskIcon
            ? args[1]
            : null;
        this._requestPlayerIndex = Number(args[2]) === 1 ? 1 : 0;
        const baseConfig = ZRSJZ_SPECIAL_OPERATION_CONFIG.get(this._mapKey);
        const taskType = baseConfig
            ? this._sourceTaskPoint?.ResolveTaskType(baseConfig.TaskType)
            : undefined;
        const config = GetSpecialOperationConfig(this._mapKey, taskType);
        this._currentConfig = config ?? null;
        this.RefreshTask(config);
    }

    private async RefreshTask(config: Readonly<ZRSJZ_SpecialOperationConfig> | undefined): Promise<void> {
        const refreshVersion = ++this._refreshVersion;
        this.ClearPropAwards();

        if (!config) {
            this.TaskDesc.string = "当前地图暂无特别行动任务";
            this.TaskAwardCount.string = "0";
            if (this.Time) this.Time.string = "0s";
            return;
        }

        // 原预制体描述区域较矮，使用两行内可完整显示的字号，避免覆盖下方奖励标题。

        this.TaskDesc.string = `${config.TaskDesc}`;
        this.TaskAwardCount.string = FormatMoney(config.GoldReward);
        if (this.Time) this.Time.string = `${config.TimeLimitSeconds}s`;

        if (!this.TaskAwardContent) {
            console.warn("[ZRSJZ_SpecialOperationsPanel] 未找到概率奖励 Content 节点");
            return;
        }
        for (const award of config.PropAwards) {
            const awardNode = await ZRSJZ_PoolManager.Instance.GetNode("Prefabs/UI/TaskAward");
            if (!awardNode) continue;
            if (refreshVersion !== this._refreshVersion || !this.node.isValid) {
                ZRSJZ_PoolManager.Instance.PutNode(awardNode);
                continue;
            }
            awardNode.parent = this.TaskAwardContent;
            awardNode.active = true;
            const awardUI = awardNode.getComponent(ZRSJZ_TaskAward);
            awardUI.Init(award.PropName, award.Count);
            // TaskAward 原本的数量区域用于显示该物资的独立掉落概率。
            awardUI.Count.string = `${Math.round(award.Probability * 100)}%`;
        }
    }

    private ClearPropAwards(): void {
        if (!this.TaskAwardContent) return;
        for (const child of [...this.TaskAwardContent.children]) {
            ZRSJZ_PoolManager.Instance.PutNode(child);
        }
    }

    OnButtonClick(event: EventTouch) {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Mask":
            case "关闭":
                this.ClosePanel();
                break;
            case "领取任务":
                if (this._currentConfig?.TaskType === "待定") {
                    void ZRSJZ_UIManager.Instance.ShowTip("该任务暂未开放");
                    return;
                }
                if (ZRSJZ_Game.Instance?.IsSpecialOperationInProgress()) {
                    void ZRSJZ_UIManager.Instance.ShowTip("任务正在进行中");
                    return;
                }
                if (!ZRSJZ_Game.Instance?.AcceptSpecialOperation(
                    this._mapKey,
                    this._sourceTaskPoint,
                    this._requestPlayerIndex,
                )) {
                    return;
                }
                this.ClosePanel();
                break;
        }
    }

    private ClosePanel(): void {
        if (this.PlayerIndex >= 0) {
            ZRSJZ_UIManager.Instance.HidePlayerPanel(
                ZRSJZ_PANEL.特别行动弹窗,
                this.PlayerIndex,
            );
        } else {
            ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.特别行动弹窗);
        }
    }


}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_AccountService } from "../Service/ZRSJZ_AccountService";
import { _decorator, Button, director, find, Label, Node, Sprite, SpriteFrame, Tween, tween, UITransform, v3, Widget } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_PANEL, ZRSJZ_ROLE_CONFIG, ZRSJZ_SKIN_CONFIG, ZRSJZ_WEAPON_SKIN } from '../ZRSJZ_Constant';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';

import { ZRSJZ_GameData } from '../ZRSJZ_GameData';

const { ccclass, property } = _decorator;

type SignInReward = {
    name: string;
    countText: string;
    gold?: number;
    propName?: string;
    propCount?: number;
    weaponSkin?: { weaponName: string; skinName: string };
    roleSkin?: { roleName: string; skinName: string };
    /** 视频皮肤没有金币售价时，单独指定重复领取的折算价值。 */
    duplicateGold?: number;
};

const SIGN_IN_REWARDS: readonly SignInReward[] = [
    { name: '钞票', countText: 'x100万', gold: 1000000 },
    { name: 'K50-云雾', countText: 'x1', weaponSkin: { weaponName: 'K50-轻机枪', skinName: 'K50-云雾' } },
    { name: '钞票', countText: 'x300万', gold: 3000000 },
    { name: 'W76-紫墟', countText: 'x1', weaponSkin: { weaponName: 'W76-狙击枪', skinName: 'W76-紫墟' }, duplicateGold: 4000000 },
    { name: '钞票', countText: 'x500万', gold: 5000000 },
    { name: 'W76-狙击枪', countText: 'x1', propName: 'W76-狙击枪', propCount: 1 },
    { name: '烬猎', countText: 'x1', roleSkin: { roleName: '威蓝', skinName: '弑岚' } },
];

@ccclass('ZRSJZ_SignInPanel')
export class ZRSJZ_SignInPanel extends ZRSJZ_Panel {
    private static _entryButton: Node = null;

    @property([SpriteFrame])
    SignItemSFs: SpriteFrame[] = [];

    private _signItems: Node[] = [];

    protected onLoad(): void {
        this.BindCloseButton();
        this.BindSignItems();
    }

    public Show(...args: any[]): void {
        // if (ZRSJZ_AccountService.IsSignInCompleted()) {
        //     this.node.active = false;
        //     return;
        // }
        this.RefreshSignItems();
        super.Show(...args);
    }



    private BindCloseButton(): void {
        const closeButton = find('Panel/关闭', this.node);
        if (!closeButton) {
            console.warn('[ZRSJZ_SignInPanel] 未找到关闭按钮');
            return;
        }

        const button = closeButton.getComponent(Button) ?? closeButton.addComponent(Button);
        button.target = closeButton;
        button.transition = Button.Transition.SCALE;
        button.zoomScale = 1.2;
        closeButton.on(Node.EventType.TOUCH_END, this.ClosePanel, this);
        find('Mask', this.node).on(Node.EventType.TOUCH_END, this.ClosePanel, this);
    }

    private BindSignItems(): void {
        const items = find('Panel/All/Items', this.node);
        const all = find('Panel/All', this.node);
        for (let dayIndex = 0; dayIndex < SIGN_IN_REWARDS.length; dayIndex++) {
            const itemName = `SignItem${dayIndex + 1}`;
            const item = items?.getChildByName(itemName) ?? all?.getChildByName(itemName);
            if (!item) {
                console.warn(`[ZRSJZ_SignInPanel] 未找到 ${itemName}`);
                continue;
            }

            this._signItems[dayIndex] = item;
            const button = item.getComponent(Button) ?? item.addComponent(Button);
            button.target = item;
            button.transition = Button.Transition.SCALE;
            button.zoomScale = 0.96;
            item.on(Node.EventType.TOUCH_END, () => void this.OnSignItemClick(dayIndex), this);
        }
    }

    private RefreshSignItems(): void {
        const claimedCount = ZRSJZ_AccountService.GetSignInClaimedCount();
        const canClaimToday = this.CanClaimToday();

        for (let dayIndex = 0; dayIndex < SIGN_IN_REWARDS.length; dayIndex++) {
            const item = this._signItems[dayIndex];
            if (!item) continue;

            const reward = SIGN_IN_REWARDS[dayIndex];
            this.SetLabel(item, 'Title', `第${this.GetChineseDay(dayIndex + 1)}天`);
            this.SetLabel(item, 'Name', reward.name);
            this.SetLabel(item, 'Count', reward.countText);

            const checked = item.getChildByName('Checked');
            const signed = item.getChildByName('已签到');
            const state = item.getChildByName('State');
            const isClaimed = dayIndex < claimedCount;
            const isCurrentDay = dayIndex === claimedCount;
            const isClaimable = isCurrentDay && canClaimToday;

            // 前六天只有“可领取”状态使用高亮底图，其余状态统一使用普通底图。
            if (dayIndex < 6 && this.SignItemSFs.length >= 2) {
                const itemSprite = item.getComponent(Sprite);
                if (itemSprite) itemSprite.spriteFrame = this.SignItemSFs[isClaimable ? 1 : 0];
            }

            if (checked) {
                Tween.stopAllByTarget(checked);
                checked.setScale(v3(1, 1, 1));
                checked.active = isClaimable;
                if (isClaimable) {
                    tween(checked)
                        .to(0.5, { scale: v3(1.06, 1.06, 1) }, { easing: 'sineInOut' })
                        .to(0.5, { scale: v3(1, 1, 1) }, { easing: 'sineInOut' })
                        .union()
                        .repeatForever()
                        .start();
                }
            }
            if (signed) signed.active = isClaimed;

            if (state) {
                if (isClaimed) {
                    this.SetNodeLabel(state, '已签到');
                } else if (isClaimable) {
                    this.SetNodeLabel(state, '可领取');
                } else {
                    this.SetNodeLabel(state, '待领取');
                }
            }
        }
    }

    private async OnSignItemClick(dayIndex: number): Promise<void> {
        const claimedCount = ZRSJZ_AccountService.GetSignInClaimedCount();
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        if (dayIndex < claimedCount) {
            ZRSJZ_UIManager.Instance.ShowTip('该奖励已经领取');
            return;
        }
        if (dayIndex > claimedCount) {
            ZRSJZ_UIManager.Instance.ShowTip('请按顺序完成签到');
            return;
        }
        if (!this.CanClaimToday()) {
            ZRSJZ_UIManager.Instance.ShowTip('今日已经签到，请明天再来');
            return;
        }

        const reward = SIGN_IN_REWARDS[dayIndex];
        if (!reward) return;
        // 先验证皮肤及折算配置，避免未发奖励就占用当天签到。
        const skinReward = this.ResolveSkinReward(reward);
        if ((reward.weaponSkin || reward.roleSkin) && !skinReward) {
            console.error('[ZRSJZ_SignInPanel] 签到皮肤奖励配置无效', reward);
            ZRSJZ_UIManager.Instance.ShowTip('奖励配置异常，请稍后再试');
            return;
        }

        const claimedDayIndex = ZRSJZ_AccountService.ClaimSignInReward();
        if (claimedDayIndex !== dayIndex) {
            this.RefreshSignItems();
            return;
        }

        let sentToMail = false;
        let convertedGold = 0;
        if (reward.gold) {
            ZRSJZ_AccountService.ChangeGold(reward.gold);
            ZRSJZ_UIManager.Instance.ShowCurrencyEffect();
        } else if (skinReward) {
            if (skinReward.owned) {
                convertedGold = skinReward.gold;
                ZRSJZ_AccountService.ChangeGold(convertedGold);
                ZRSJZ_UIManager.Instance.ShowCurrencyEffect();
            } else if (reward.weaponSkin) {
                ZRSJZ_AccountService.AddWeaponSkin(reward.weaponSkin.weaponName, reward.weaponSkin.skinName);
            } else {
                ZRSJZ_AccountService.AddSkin(reward.roleSkin.roleName, reward.roleSkin.skinName);
            }
        } else if (reward.propName) {
            const result = await ZRSJZ_UIManager.Instance.ReceivePropAwards([{
                PropName: reward.propName,
                Count: reward.propCount ?? 1,
            }]);
            if (result.MailAwards.length > 0) {
                sentToMail = true;
            }
        }

        this.RefreshSignItems();
        ZRSJZ_UIManager.Instance.ShowTip(
            convertedGold > 0
                ? `签到成功，已拥有${reward.name}，已折算为${FormatMoney(convertedGold)}金币`
                : sentToMail
                    ? `签到成功，${reward.name}${reward.countText}已发送至邮件`
                    : `签到成功，获得${reward.name}${reward.countText}`,
        );
        if (ZRSJZ_AccountService.IsSignInCompleted()) {
            this.ClosePanel();
        }
    }

    private ResolveSkinReward(reward: SignInReward): { owned: boolean; gold: number } | null {
        let owned: boolean;
        let price: number;
        if (reward.weaponSkin) {
            const { weaponName, skinName } = reward.weaponSkin;
            const config = ZRSJZ_WEAPON_SKIN.get(weaponName)?.find(skin => skin.Name === skinName);
            if (!config) return null;
            owned = ZRSJZ_AccountService.HasWeaponSkin(weaponName, skinName);
            price = config.UnlockType === '金币' ? config.Price : 0;
        } else if (reward.roleSkin) {
            const { roleName, skinName } = reward.roleSkin;
            const config = ZRSJZ_SKIN_CONFIG.get(skinName);
            if (!config || !ZRSJZ_ROLE_CONFIG.get(roleName)?.Skin.includes(skinName)) return null;
            owned = (ZRSJZ_GameData.Instance.HaveSkin ?? []).includes(skinName);
            price = 1000000;
        } else {
            return null;
        }
        const gold = reward.duplicateGold ?? price;
        if (!Number.isFinite(gold) || gold <= 0 || !Number.isInteger(gold)) return null;
        return { owned, gold };
    }

    private ClosePanel(): void {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.签到弹窗);
    }

    private CanClaimToday(): boolean {
        return ZRSJZ_AccountService.CanClaimSignInReward();
    }

    private SetLabel(item: Node, childName: string, text: string): void {
        const label = item.getChildByName(childName)?.getComponent(Label);
        if (label) label.string = text;
    }

    private SetNodeLabel(node: Node, text: string): void {
        const label = node.getComponent(Label);
        if (label) label.string = text;
    }

    private GetChineseDay(day: number): string {
        return ['一', '二', '三', '四', '五', '六', '七'][day - 1] ?? `${day}`;
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { _decorator, Component, EventTouch, Label, Node, Sprite, SpriteFrame } from 'cc';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_Tools } from '../ZRSJZ_Tools';
import { ZRSJZ_PANEL, ZRSJZ_PROP_CONFIG } from '../ZRSJZ_Constant';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from '../Manager/ZRSJZ_EventManager';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_InventoryService } from '../Service/ZRSJZ_InventoryService';
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_TaskAward')
export class ZRSJZ_TaskAward extends Component {

    @property(SpriteFrame)
    BottomSF: SpriteFrame = null;

    @property(SpriteFrame)
    GoldSF: SpriteFrame = null;

    @property(SpriteFrame)
    ExpSF: SpriteFrame = null;
    @property(SpriteFrame)
    WarehouseSF: SpriteFrame = null;

    Bottom: Sprite = null;
    Icon: Sprite = null;
    Name: Label = null;
    Count: Label = null;
    Check: Node = null;
    Checked: Node = null;

    PropName: string = "";
    SelectionKey: string = "";

    private _isInit: boolean = false;
    /** 防止节点回池并快速复用后，上一轮异步资源覆盖当前奖励。 */
    private _refreshVersion: number = 0;
    private _isGeting: boolean = false;
    private _isGetCheck: boolean = false;

    protected onEnable(): void {
        this.node.on(Node.EventType.TOUCH_END, this.OnTouchEnd, this);
        ZRSJZ_EventManager.OnPersist(ZRSJZ_MyEvent.ZRSJZ_MAIL_GET_PROP, this.GetShow, this);
    }

    protected onDisable(): void {
        this.node.off(Node.EventType.TOUCH_END, this.OnTouchEnd, this);
        ZRSJZ_EventManager.OffPersist(ZRSJZ_MyEvent.ZRSJZ_MAIL_GET_PROP, this.GetShow, this);
    }

    Init(propName: string, count: number, selectionKey: string = propName) {
        const refreshVersion = ++this._refreshVersion;
        if (!this._isInit) {
            this._isInit = true;
            this.Bottom = this.getComponent(Sprite);
            this.Icon = this.node.getChildByName("Icon").getComponent(Sprite);
            this.Name = this.node.getChildByName("Name").getComponent(Label);
            this.Count = this.node.getChildByName("Count").getComponent(Label);
            this.Check = this.node.getChildByName("未选");
            this.Checked = this.node.getChildByName("勾选");
        }

        this.PropName = propName;
        this.SelectionKey = selectionKey;
        this._isGeting = false;
        this._isGetCheck = false;
        this.ShowGetButton();
        this.Name.string = propName;
        this.Count.string = propName === "钞票" ? FormatMoney(count) : count.toString();
        if (propName.startsWith('仓库_') && propName.endsWith('扩容')) {
            this.Name.string = propName === '仓库_全部扩容'
                ? '主库'
                : propName.replace('仓库_', '').replace('扩容', '仓库');
            this.Count.string = `+${count}行`;
            this.Icon.spriteFrame = this.WarehouseSF;
            this.Bottom.spriteFrame = this.BottomSF;
            ZRSJZ_Tools.ScaleNodeToFit(this.Icon.node, 110, 110);
        } else if (propName === '安全箱扩容') {
            this.Count.string = '3×3';
            this.Icon.spriteFrame = this.WarehouseSF;
            this.Bottom.spriteFrame = this.BottomSF;
            ZRSJZ_Tools.ScaleNodeToFit(this.Icon.node, 110, 110);
        } else if (propName == "钞票") {
            this.Icon.spriteFrame = this.GoldSF;
            this.Bottom.spriteFrame = this.BottomSF;
        } else if (propName == "经验") {
            this.Icon.spriteFrame = this.ExpSF;
            this.Bottom.spriteFrame = this.BottomSF;
        } else {
            ZRSJZ_UIManager.Instance.GetPropUI(propName).then(sf => {
                if (refreshVersion !== this._refreshVersion || !this.node.isValid) return;
                this.Icon.spriteFrame = sf;
                ZRSJZ_Tools.ScaleNodeToFit(this.Icon.node, 110, 110);
            });

            const prop = ZRSJZ_PROP_CONFIG.get(propName);
            if (!prop) {
                console.warn(`[ZRSJZ_TaskAward] 未找到奖励道具配置: ${propName}`);
                this.Icon.spriteFrame = null;
                this.Bottom.spriteFrame = this.BottomSF;
                return;
            }
            ZRSJZ_UIManager.Instance.GetPropGridUI(`${prop.Quality}1_1`).then(sf => {
                if (refreshVersion !== this._refreshVersion || !this.node.isValid) return;
                this.Bottom.spriteFrame = sf;
            });
        }
    }

    GetShow(show: boolean) {
        this._isGeting = show;
        this._isGetCheck = false;
        this.ShowGetButton();
    }

    //显示售卖按钮
    ShowGetButton() {
        this.Check.active = this._isGeting && !this._isGetCheck;
        this.Checked.active = this._isGeting && this._isGetCheck;
    }

    OnTouchEnd(event: EventTouch) {
        // 钞票和经验只有数值展示，不属于可查看详情的道具。
        if (this.PropName === "钞票" || this.PropName === "经验") return;

        if (this._isGeting) {
            ZRSJZ_AudioManager.Instance.PlaySound("点击");
            this._isGetCheck = !this._isGetCheck;
            this.ShowGetButton();
            ZRSJZ_EventManager.EmitPersist(
                ZRSJZ_MyEvent.ZRSJZ_MAIL_GET_PROP_ADD,
                this.SelectionKey,
                this._isGetCheck,
            );
            return;
        }

        // 邮件未处于选择领取状态时，以及其他奖励展示场景中，点击普通道具显示只读详情。
        if (!ZRSJZ_PROP_CONFIG.has(this.PropName)) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        const playerIndex = ZRSJZ_InventoryService.GetActivePlayerIndex();
        ZRSJZ_UIManager.Instance.ShowPlayerPanel(
            ZRSJZ_PANEL.道具弹窗,
            playerIndex,
            this.PropName,
            playerIndex,
            true,
        );
    }

}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_GameData } from "../ZRSJZ_GameData";
import { ZRSJZ_PET_SKILL_EFFECT_CONFIG, ZRSJZ_PetBattleSkillConfig, ZRSJZ_PET_CONFIG, ZRSJZ_PET_GENE_CONFIG, ZRSJZ_PET_SKIN_CONFIG, ZRSJZ_PET_SKILL_CONFIG, ZRSJZ_PROP_CONFIG, ZRSJZ_PetGeneConfig, ZRSJZ_PetPlayerBonus } from "../ZRSJZ_Constant";
import { ZRSJZ_InventoryService } from "./ZRSJZ_InventoryService";
import { ZRSJZ_FragmentService } from './ZRSJZ_FragmentService';
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from "../Manager/ZRSJZ_EventManager";

export class ZRSJZ_PetService {
    public static AddPet(petName: string): boolean {
        const config = ZRSJZ_PET_CONFIG.get(petName);
        const data = ZRSJZ_GameData.Instance;
        if (!data || !config || this.CheckPet(petName)) return false;
        if (!data.PetData) data.PetData = {};
        data.PetData[petName] = { Skins: [config.PetSkins[0] ?? petName], Level: 0 };
        ZRSJZ_GameData.SaveData();
        return true;
    }

    public static GetPetGrade(petName: string): number {
        const level = this.CheckPet(petName) ? ZRSJZ_GameData.Instance.PetData[petName].Level : 0;
        return Number.isFinite(level) ? Math.max(0, Math.floor(level)) : 0;
    }

    public static GetGeneCostOwned(gene: Readonly<ZRSJZ_PetGeneConfig>): number {
        return gene.CostProp === "金币" ? ZRSJZ_GameData.Instance.Gold
            : gene.CostProp === "宠物碎片" ? ZRSJZ_FragmentService.GetCount()
            : ZRSJZ_InventoryService.GetPropCountByName(gene.CostProp);
    }

    public static GetGeneConfig(petName: string, level: number): Readonly<ZRSJZ_PetGeneConfig> | undefined {
        const base = ZRSJZ_PET_GENE_CONFIG.find(item => item.Level === level);
        if (!base) return undefined;
        return { ...base, Value: ZRSJZ_PET_CONFIG.get(petName)?.PetGeneValues?.[level] ?? base.Value };
    }

    public static GetSkill(petName: string, index: number) {
        return ZRSJZ_PET_SKILL_CONFIG.get(ZRSJZ_PET_CONFIG.get(petName)?.PetSkills[index]);
    }

    /** 战斗端合并专属参数；UI仍只读取公共技能表。 */
    public static GetBattleSkill(petName: string, index: number): Readonly<ZRSJZ_PetBattleSkillConfig> {
        const skill = this.GetSkill(petName, index);
        return skill ? { ...ZRSJZ_PET_SKILL_EFFECT_CONFIG.get(skill.Name), ...skill } : null;
    }

    public static IsSkillUnlocked(petName: string, index: number): boolean {
        if (!this.CheckPet(petName)) return false;
        const skill = this.GetSkill(petName, index);
        if (!skill) return false;
        if (skill.Unlock === "购买") return true;
        if (skill.Unlock === "视频") return ZRSJZ_GameData.Instance.PetData[petName].VideoSkillUnlocked === true;
        const gene = this.GetGeneConfig(petName, skill.GeneLevel);
        return gene?.Type === "技能" && this.GetPetGrade(petName) >= skill.GeneLevel;
    }

    public static GetSkillUnlockText(petName: string, index: number): string {
        if (this.IsSkillUnlocked(petName, index)) return "已解锁";
        const skill = this.GetSkill(petName, index);
        if (!skill) return "技能未配置";
        return skill.Unlock === "视频" ? "观看视频永久解锁"
            : skill.Unlock === "基因" ? `学习Lv.${skill.GeneLevel}基因解锁` : "购买宠物后解锁";
    }

    /** 仅由激励视频成功回调传true；旧存档缺失该字段时视为尚未视频解锁。 */
    public static TryUnlockVideoSkill(petName: string, videoRewarded: boolean = false): string {
        if (!this.CheckPet(petName)) return "请先购买宠物";
        if (this.GetSkill(petName, 3)?.Unlock !== "视频") return "视频技能配置不存在";
        if (this.IsSkillUnlocked(petName, 3)) return "";
        if (!videoRewarded) return "请完整观看视频后解锁";
        ZRSJZ_GameData.Instance.PetData[petName].VideoSkillUnlocked = true;
        ZRSJZ_GameData.SaveData();
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_PET_GENE_CHANGE, petName);
        return "";
    }

    public static GetPlayerPassiveBonus(petName: string = ZRSJZ_GameData.Instance?.CurPet): ZRSJZ_PetPlayerBonus {
        const bonus = { Attack: 0, MaxHP: 0, DamageReduction: 0 };
        if (!this.CheckPet(petName)) return bonus;
        for (let index = 0; index < 4; index++) {
            const skill = this.GetBattleSkill(petName, index);
            if (skill?.Kind !== "被动" || !this.IsSkillUnlocked(petName, index) || !skill.PlayerBonus) continue;
            bonus.Attack += skill.PlayerBonus.Attack;
            bonus.MaxHP += skill.PlayerBonus.MaxHP;
            bonus.DamageReduction = 1 - (1 - bonus.DamageReduction)
                * Math.max(0, 1 - Math.max(0, skill.PlayerBonus.DamageReduction));
        }
        return bonus;
    }

    public static GetGeneLearnError(petName: string, level: number): string {
        if (!this.CheckPet(petName)) return "请先解锁宠物";
        const gene = this.GetGeneConfig(petName, level);
        if (!gene) return "基因配置不存在";
        const learned = this.GetPetGrade(petName);
        if (level <= learned) return "已学习";
        if (level !== learned + 1) return `请先学习Lv.${learned + 1}`;
        if (!Number.isSafeInteger(gene.CostCount) || gene.CostCount < 0
            || !Number.isFinite(gene.Value) || gene.Value <= 0
            || (gene.Type === "技能" && !Number.isSafeInteger(gene.Value))
            || (gene.CostProp !== "金币" && !ZRSJZ_PROP_CONFIG.has(gene.CostProp))) return "基因配置不正确";
        if (this.GetGeneCostOwned(gene) < gene.CostCount) return `${gene.CostProp}不足`;
        return "";
    }

    /** 同步校验和扣费，等级是唯一学习进度，重复点击不会重复发放加成。 */
    public static TryLearnGene(petName: string, level: number): string {
        const error = this.GetGeneLearnError(petName, level);
        if (error) return error;
        const gene = this.GetGeneConfig(petName, level)!;
        const data = ZRSJZ_GameData.Instance;
        const previousLevel = data.PetData[petName].Level;
        // ConsumeProp会通知库存并存档，先写等级，让同一次库存存档包含学习结果。
        data.PetData[petName].Level = level;
        if (gene.CostProp === "金币") data.Gold -= gene.CostCount;
        else if (gene.CostProp === "宠物碎片") data.PetFragments = ZRSJZ_FragmentService.GetCount() - gene.CostCount;
        else if (gene.CostCount > 0 && !ZRSJZ_InventoryService.ConsumeProp(gene.CostProp, gene.CostCount)) {
            data.PetData[petName].Level = previousLevel;
            return `${gene.CostProp}不足`;
        }
        ZRSJZ_GameData.SaveData();
        if (gene.CostProp === "金币" || gene.CostProp === "宠物碎片") ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE);
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_PET_GENE_CHANGE, petName);
        return "";
    }

    /** 基础属性 + 已学基因 + 当前穿戴皮肤；每次重新汇总，不修改配置或存档属性。 */
    public static GetPetStats(petName: string, playerIndex: number = 0) {
        const config = ZRSJZ_PET_CONFIG.get(petName);
        const result = { Attack: config?.PetHarmony ?? 0, HP: config?.PetHP ?? 0,
            Defense: config?.PetArmor ?? 0, Backpack: config?.PetBackpack ?? 0,
            AttackSpeedMultiplier: 1, Skills: [] as string[] };
        const level = this.GetPetGrade(petName);
        for (const base of ZRSJZ_PET_GENE_CONFIG) {
            const gene = this.GetGeneConfig(petName, base.Level)!;
            if (gene.Level > level) continue;
            switch (gene.Type) {
                case "生命值": result.HP += gene.Value; break;
                case "防御": result.Defense += gene.Value; break;
                case "攻击": result.Attack += gene.Value; break;
                case "攻速": result.AttackSpeedMultiplier += gene.Value; break;
                case "背包": result.Backpack += gene.Value; break;
            }
        }
        const skinBonus = this.GetPetSkinBonus(petName, playerIndex);
        result.Attack += skinBonus.Attack;
        result.HP += skinBonus.HP;
        result.Defense += skinBonus.Defense;
        result.Backpack += skinBonus.Backpack;
        result.AttackSpeedMultiplier *= 1 + skinBonus.AttackSpeedMultiplier;
        result.Skills = config?.PetSkills.filter((_, index) => this.IsSkillUnlocked(petName, index)) ?? [];
        return result;
    }

    /** 仅当前已拥有且穿戴的皮肤生效，使用与皮肤界面一致的PetSkinAddition配置。 */
    public static GetPetSkinBonus(petName: string, playerIndex: number = 0) {
        const bonus = { Attack: 0, HP: 0, Defense: 0, Backpack: 0, AttackSpeedMultiplier: 0 };
        const addition = ZRSJZ_PET_SKIN_CONFIG.get(this.GetCurrentSkin(petName, playerIndex))?.PetSkinAddition ?? "";
        for (const entry of addition.split(/[,，、;；\n]+/)) {
            const match = entry.trim().match(/^(攻击|生命值|防御|背包|攻速)\s*[+＋]\s*(\d+(?:\.\d+)?)\s*([%％]?)$/);
            if (!match) continue;
            const value = Number(match[2]);
            if (!Number.isFinite(value)) continue;
            // 攻速用百分比，其余属性使用固定数值，避免把“攻击+10%”误算为攻击+10。
            if (match[1] === "攻速") {
                if (match[3]) bonus.AttackSpeedMultiplier += value / 100;
                continue;
            }
            if (match[3]) continue;
            switch (match[1]) {
                case "攻击": bonus.Attack += value; break;
                case "生命值": bonus.HP += value; break;
                case "防御": bonus.Defense += value; break;
                case "背包": bonus.Backpack += value; break;
            }
        }
        return bonus;
    }

    public static GetGeneEffectText(petName: string, gene: Readonly<ZRSJZ_PetGeneConfig>): string {
        gene = this.GetGeneConfig(petName, gene.Level) ?? gene;
        if (gene.Type === "攻速") return `攻速+${Math.round(gene.Value * 100)}%`;
        if (gene.Type === "技能") {
            const skills = (ZRSJZ_PET_CONFIG.get(petName)?.PetSkills ?? []).map(id => ZRSJZ_PET_SKILL_CONFIG.get(id));
            const names = skills.filter(skill => skill?.Unlock === "基因" && skill.GeneLevel === gene.Level).map(skill => skill.Name);
            return names.length ? `解锁${names.join("、")}` : "该等级未配置技能";
        }
        return `${gene.Type}+${gene.Value}`;
    }

    public static CheckPet(petName: string): boolean {
        const pets = ZRSJZ_GameData.Instance?.PetData;
        return !!pets && Object.prototype.hasOwnProperty.call(pets, petName) && !!pets[petName];
    }

    public static CheckPetSkin(petName: string, skinName: string): boolean {
        return this.CheckPet(petName) && ZRSJZ_GameData.Instance.PetData[petName].Skins.includes(skinName);
    }

    public static GetBattlePet(playerIndex: number = 0): string {
        const data = ZRSJZ_GameData.Instance;
        const name = playerIndex === 1 ? data?.Player2Pet : data?.CurPet;
        return name && this.CheckPet(name) && ZRSJZ_PET_CONFIG.has(name) ? name : "";
    }

    public static SetBattlePet(petName: string, playerIndex: number = 0): boolean {
        if (!ZRSJZ_PET_CONFIG.has(petName) || !this.CheckPet(petName)) return false;
        const data = ZRSJZ_GameData.Instance;
        if (playerIndex === 1) {
            data.Player2Pet = petName;
            ZRSJZ_GameData.SaveData();
            return true;
        }
        if (data.CurPet === petName) return true;
        if (this.CheckPet(data.CurPet)) {
            data.PetData[data.CurPet].CurrentSkin = this.GetCurrentSkin(data.CurPet);
        }
        const skinName = this.GetCurrentSkin(petName);
        data.CurPet = petName;
        data.CurPetSkin = skinName;
        data.PetData[petName].CurrentSkin = skinName;
        ZRSJZ_GameData.SaveData();
        return true;
    }

    public static GetCurrentSkin(petName: string, playerIndex: number = 0): string {
        if (!this.CheckPet(petName)) return "";
        const data = ZRSJZ_GameData.Instance;
        const pet = data.PetData[petName];
        const skins = ZRSJZ_PET_CONFIG.get(petName)?.PetSkins ?? [];
        const valid = (name: string) => skins.includes(name) && this.CheckPetSkin(petName, name);
        const fallback = skins.find(skin => this.CheckPetSkin(petName, skin)) ?? "";
        if (!Array.isArray(pet.PlayerSkins)) {
            // 一次性迁移两名玩家，之后修改玩家1不会改变玩家2的默认值。
            const legacy = pet.CurrentSkin || (data.CurPet === petName ? data.CurPetSkin : "");
            const initial = valid(legacy) ? legacy : fallback;
            pet.PlayerSkins = [initial, initial];
            ZRSJZ_GameData.SaveData();
        }
        const saved = pet.PlayerSkins[playerIndex === 1 ? 1 : 0];
        return valid(saved) ? saved : fallback;
    }

    public static UseSkin(petName: string, skinName: string, playerIndex: number = 0): boolean {
        if (!ZRSJZ_PET_CONFIG.get(petName)?.PetSkins.includes(skinName)
            || !this.CheckPetSkin(petName, skinName)) return false;
        this.GetCurrentSkin(petName, playerIndex);
        const data = ZRSJZ_GameData.Instance;
        const index = playerIndex === 1 ? 1 : 0;
        data.PetData[petName].PlayerSkins[index] = skinName;
        if (index === 0) {
            data.PetData[petName].CurrentSkin = skinName;
            if (data.CurPet === petName) data.CurPetSkin = skinName;
        }
        ZRSJZ_GameData.SaveData();
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_PET_SKIN_CHANGE, petName);
        return true;
    }

    public static GetSkinUnlock(skinName: string): { resource: string; label: string; count: number } {
        const condition = ZRSJZ_PET_SKIN_CONFIG.get(skinName)?.PetSkinUnlock ?? "";
        if (!condition) return { resource: "", label: "免费获取", count: 0 };
        const separator = condition.indexOf("x");
        const resource = (separator < 0 ? condition : condition.slice(0, separator)).trim();
        const label = separator < 0 ? "" : condition.slice(separator + 1).trim();
        return { resource, label: resource === "金币" ? FormatMoney(Number(label), true) : label, count: Number(label) };
    }

    public static TryUnlockSkin(petName: string, skinName: string, videoRewarded: boolean = false): string {
        if (!this.CheckPet(petName)) return "请先解锁宠物";
        if (!ZRSJZ_PET_CONFIG.get(petName)?.PetSkins.includes(skinName)
            || !ZRSJZ_PET_SKIN_CONFIG.has(skinName)) return "宠物皮肤配置不存在";
        if (this.CheckPetSkin(petName, skinName)) return "";
        const { resource, count } = this.GetSkinUnlock(skinName);
        const data = ZRSJZ_GameData.Instance;
        if (resource === "视频") {
            if (!videoRewarded) return "请完整观看视频后解锁";
        } else if (resource) {
            if (!Number.isSafeInteger(count) || count <= 0) return "皮肤解锁数量配置不正确";
            if (resource === "金币") {
                if (data.Gold < count) return "金币不足";
                data.Gold -= count;
            } else if (resource === "宠物碎片") {
                if (ZRSJZ_FragmentService.GetCount() < count) return "宠物碎片不足";
                data.PetFragments = ZRSJZ_FragmentService.GetCount() - count;
            } else {
                if (!ZRSJZ_PROP_CONFIG.has(resource)) return "皮肤解锁道具配置不存在";
                if (!ZRSJZ_InventoryService.ConsumeProp(resource, count)) return `${resource}不足`;
            }
        }
        data.PetData[petName].Skins.push(skinName);
        ZRSJZ_GameData.SaveData();
        if (resource === "金币" || resource === "宠物碎片") ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE);
        return "";
    }

    public static GetUnlockLabel(petName: string): string {
        const config = ZRSJZ_PET_CONFIG.get(petName);
        if (!config) return "无法解锁";
        if (config.PetUnlock === "金币解锁") return `${FormatMoney(config.PetUnlockValue ?? 0, true)}金币解锁`;
        if (config.PetUnlock === "等级解锁") return `${config.PetUnlockValue ?? 0}级解锁`;
        if (config.PetUnlock === "宠物碎片解锁") return `${config.PetUnlockValue ?? 0}宠物碎片解锁`;
        return config.PetUnlock || "免费解锁";
    }

    /** 可直接购买/领取的宠物提醒；视频解锁不作为已满足购买条件。 */
    public static CanUnlockPet(petName: string): boolean {
        const config = ZRSJZ_PET_CONFIG.get(petName);
        if (!config || this.CheckPet(petName)) return false;
        const data = ZRSJZ_GameData.Instance;
        const value = config.PetUnlockValue;
        switch (config.PetUnlock) {
            case "": case "免费解锁": return true;
            case "金币解锁": return Number.isInteger(value) && value > 0 && data.Gold >= value;
            case "等级解锁": return Number.isInteger(value) && value > 0 && data.Grade >= value;
            case "宠物碎片解锁": return Number.isSafeInteger(value) && value > 0 && ZRSJZ_FragmentService.GetCount() >= value;
            default: return false;
        }
    }

    /** 视频奖励只能由广告成功回调传入；条件不足和未知配置均不发放宠物。 */
    public static TryUnlockPet(petName: string, videoRewarded: boolean = false): string {
        const config = ZRSJZ_PET_CONFIG.get(petName);
        const data = ZRSJZ_GameData.Instance;
        if (!config || !data) return "宠物配置不存在";
        if (this.CheckPet(petName)) return "";
        let cost = 0;
        let fragmentCost = 0;
        switch (config.PetUnlock) {
            case "宠物碎片解锁":
                fragmentCost = config.PetUnlockValue;
                if (!Number.isSafeInteger(fragmentCost) || fragmentCost <= 0) return "宠物解锁条件配置不完整";
                if (ZRSJZ_FragmentService.GetCount() < fragmentCost) return "宠物碎片不足";
                break;
            case "视频解锁":
                if (!videoRewarded) return "请完整观看视频后解锁";
                break;
            case "金币解锁":
            case "等级解锁": {
                const value = config.PetUnlockValue;
                if (!Number.isInteger(value) || value <= 0) return "宠物解锁条件配置不完整";
                if (config.PetUnlock === "金币解锁") {
                    if (data.Gold < value) return "金币不足";
                    cost = value;
                } else if (data.Grade < value) return `账号达到${value}级后解锁`;
                break;
            }
            case "":
            case "免费解锁":
                break;
            default:
                return `尚未满足解锁条件：${config.PetUnlock}`;
        }
        // 扣费与宠物写入同一次存档，重复回调不会重复扣费或重置等级。
        data.Gold -= cost;
        if (fragmentCost > 0) data.PetFragments = ZRSJZ_FragmentService.GetCount() - fragmentCost;
        this.AddPet(petName);
        if (cost > 0 || fragmentCost > 0) ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE);
        return "";
    }
}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import {
    ZRSJZ_AMMO_MAX_COUNT,
    ZRSJZ_AssistFightingGiftConfig,
    ZRSJZ_GridData,
    ZRSJZ_INVENTORY,
    ZRSJZ_INVENTORY_CONFIG,
    ZRSJZ_MAP_CONFIG,
    ZRSJZ_PROP_CONFIG,
    ZRSJZ_PROP_SELL_RATES,
    ZRSJZ_PropData,
} from "../ZRSJZ_Constant";
import { ZRSJZ_GameData } from "../ZRSJZ_GameData";
import { ZRSJZ_EventManager, ZRSJZ_MyEvent } from "../Manager/ZRSJZ_EventManager";

/** 道具、装备、仓库、弹药及房卡相关业务。 */
export class ZRSJZ_InventoryService {
    /** 单独出售、批量出售及预览共用；整叠折价后向下取整到钞票整数。 */
    public static GetPropSellValue(prop: Pick<ZRSJZ_PropData, "PropType" | "UnitPrice" | "CurCount">): number {
        if (!prop) return 0;
        const rate = ZRSJZ_PROP_SELL_RATES[prop.PropType] ?? 1;
        const price = Number.isFinite(prop.UnitPrice) ? Math.max(0, prop.UnitPrice) : 0;
        const count = Number.isFinite(prop.CurCount) ? Math.max(0, Math.floor(prop.CurCount)) : 0;
        return Math.floor(price * count * rate);
    }

    /** 所有进入战斗的入口复用同一门槛，战斗内消耗弹药不会追溯取消准入。 */
    public static GetBattleEntryError(mapKey: string, playerIndexes: number[] = [0]): string {
        const config = ZRSJZ_MAP_CONFIG.get(mapKey);
        if (!config) return '该关卡暂未开放';
        const missing = config.RequiredLoadoutValue - this.GetLoadoutValue(playerIndexes);
        return missing > 0 ? `战备价值不足，还需${FormatMoney(missing)}，无法进入该关卡` : '';
    }
    public static GetLoadoutValue(playerIndexes: number[] = [0]): number {
        const carriedInventories = new Set<ZRSJZ_INVENTORY>([
            ZRSJZ_INVENTORY.卡包,
            ZRSJZ_INVENTORY.弹药,
            ZRSJZ_INVENTORY.武器_枪,
            ZRSJZ_INVENTORY.武器_头盔,
            ZRSJZ_INVENTORY.武器_防弹衣,
            ZRSJZ_INVENTORY.武器_背包,
            ZRSJZ_INVENTORY.武器_刀,
        ]);
        const playerIndexSet = new Set(playerIndexes);
        const propIDs = new Set<string>();
        for (const playerIndex of playerIndexes) {
            this.GetWeaponryIDs(playerIndex).filter(Boolean).forEach(id => propIDs.add(id));
            this.GetAmmoIDs(playerIndex).filter(Boolean).forEach(id => propIDs.add(id));
        }

        for (const propID in ZRSJZ_GameData.Instance.PropData) {
            const propData = ZRSJZ_GameData.Instance.PropData[propID];
            if (
                propData
                && carriedInventories.has(propData.CurInventory)
                && playerIndexSet.has(propData.OwnerPlayerIndex ?? 0)
            ) {
                propIDs.add(propID);
            }
        }

        let totalValue = 0;
        propIDs.forEach(propID => {
            const propData = ZRSJZ_GameData.Instance.PropData[propID];
            if (!propData) return;
            totalValue += Math.max(0, propData.UnitPrice || 0) * Math.max(0, propData.CurCount || 0);
        });
        return totalValue;
    }


    /** 调用方完成双向占格校验后，一次性提交交换，最后才保存及广播。 */
    public static ApplySwap(moves: { id: string, inventory: ZRSJZ_INVENTORY, playerIndex: number,
        gridX: number, gridY: number, isRotate: boolean, sourceBoxID: string }[]): void {
        const data = ZRSJZ_GameData.Instance;
        const equipment = [ZRSJZ_INVENTORY.武器_枪, ZRSJZ_INVENTORY.武器_头盔, ZRSJZ_INVENTORY.武器_防弹衣,
            ZRSJZ_INVENTORY.武器_背包, ZRSJZ_INVENTORY.武器_刀];
        const ids = new Set(moves.map(move => move.id));
        const equipmentEvents: { name: string, equipped: boolean, player: number }[] = [];
        for (const player of [0, 1]) {
            for (const refs of [this.GetWeaponryIDs(player), this.GetAmmoIDs(player)]) {
                refs.forEach((id, index) => { if (ids.has(id)) refs[index] = ''; });
            }
        }
        for (const move of moves) {
            const prop = data.PropData[move.id];
            if (equipment.includes(prop.CurInventory)) {
                equipmentEvents.push({ name: prop.Name, equipped: false, player: prop.OwnerPlayerIndex ?? 0 });
            }
            prop.CurInventory = move.inventory;
            prop.OwnerPlayerIndex = this.IsPlayerInventory(move.inventory) ? (move.playerIndex === 1 ? 1 : 0) : -1;
            prop.SourceBoxID = move.inventory === ZRSJZ_INVENTORY.物资 ? move.sourceBoxID : '';
            prop.GridData.forEach(grid => { grid.GridX = -1; grid.GridY = -1; });
            const grid = prop.GridData[move.inventory === ZRSJZ_INVENTORY.仓库_全部 ? 0 : 1];
            grid.GridX = move.gridX;
            grid.GridY = move.gridY;
            grid.IsRotate = move.isRotate;
            const slot = equipment.indexOf(move.inventory);
            if (slot >= 0) {
                this.GetWeaponryIDs(move.playerIndex)[slot] = move.id;
                equipmentEvents.push({ name: prop.Name, equipped: true, player: move.playerIndex });
            }
            if (move.inventory === ZRSJZ_INVENTORY.弹药) this.GetAmmoIDs(move.playerIndex)[move.gridY * 3 + move.gridX] = move.id;
        }
        this.RefreshRoomCardIDs(0);
        this.RefreshRoomCardIDs(1);
        ZRSJZ_GameData.SaveData();
        // 先通知卸下，再通知装备，监听者始终读到完整的新配置。
        equipmentEvents.sort((a, b) => Number(a.equipped) - Number(b.equipped)).forEach(event =>
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SHOW_EQUIPMENT, event.name, event.equipped, event.player));
        new Set(equipmentEvents.map(event => event.player)).forEach(player =>
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_LOADOUT_CHANGE, player));
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE);
    }

    //#region 版本1之后新增
    //获取对应仓库的行数
    public static GetInventoryRow(inventory: ZRSJZ_INVENTORY, defaultValue: number = 0): number {
        const data = ZRSJZ_GameData.Instance;
        if (!data.InventoryRow.hasOwnProperty(inventory)) {
            data.InventoryRow[inventory] = defaultValue;
            ZRSJZ_GameData.SaveData();
        }
        return data.InventoryRow[inventory];
    }

    public static AddInventoryRow(inventory: ZRSJZ_INVENTORY, addRow: number) {
        const data = ZRSJZ_GameData.Instance;
        if (!data.InventoryRow.hasOwnProperty(inventory)) {
            if (!ZRSJZ_INVENTORY_CONFIG.has(inventory)) {
                console.error(`没找到仓库${inventory}`);
                return;
            }
            const defaultValue = ZRSJZ_INVENTORY_CONFIG.get(inventory)?.Row ?? 0;
            data.InventoryRow[inventory] = defaultValue;
        }
        data.InventoryRow[inventory] += addRow;
        ZRSJZ_GameData.SaveData();
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_ADD_ROW, inventory, addRow);
    }

    //#regionend

    private static _activePlayerIndex: number = 0;
    /** 单局扩容状态；只存在内存中，玩家1和玩家2互不影响。 */
    private static _backpackExpanded: boolean[] = [false, false];
    private static _petBackpackSlots: number[] = [0, 0];

    public static SetPetBackpackSlots(playerIndex: number, slots: number): void {
        this._petBackpackSlots[playerIndex === 1 ? 1 : 0] = Number.isFinite(slots) ? Math.max(0, Math.floor(slots)) : 0;
    }

    public static GetPetBackpackSlots(playerIndex: number): number {
        return this._petBackpackSlots[playerIndex === 1 ? 1 : 0];
    }

    public static SetActivePlayerIndex(playerIndex: number): void {
        this._activePlayerIndex = playerIndex === 1 ? 1 : 0;
    }

    public static GetActivePlayerIndex(): number {
        return this._activePlayerIndex;
    }

    public static GetWeaponryIDs(playerIndex: number = this._activePlayerIndex): string[] {
        const data = ZRSJZ_GameData.Instance;
        return playerIndex === 1 ? data.Player2WeaponryID : data.WeaponryID;
    }

    public static GetAmmoIDs(playerIndex: number = this._activePlayerIndex): string[] {
        const data = ZRSJZ_GameData.Instance;
        return playerIndex === 1 ? data.Player2AmmoID : data.AmmoID;
    }

    public static GetRoomCardIDs(playerIndex: number = this._activePlayerIndex): string[] {
        const data = ZRSJZ_GameData.Instance;
        return playerIndex === 1 ? data.Player2RoomCard : data.RoomCard;
    }

    public static IsBackpackExpanded(playerIndex: number = this._activePlayerIndex): boolean {
        const normalizedPlayerIndex = playerIndex === 1 ? 1 : 0;
        return this._backpackExpanded[normalizedPlayerIndex] === true;
    }

    /** 每名玩家每局只能领取一次。 */
    public static ExpandBackpack(playerIndex: number = this._activePlayerIndex): boolean {
        const normalizedPlayerIndex = playerIndex === 1 ? 1 : 0;
        if (this._backpackExpanded[normalizedPlayerIndex]) return false;
        this._backpackExpanded[normalizedPlayerIndex] = true;
        return true;
    }

    /** 开始或离开对局时清空本局扩容。 */
    public static ResetBackpackExpansion(): void {
        this._backpackExpanded = [false, false];
        this._petBackpackSlots = [0, 0];
    }

    public static IsPlayerInventory(inventory: ZRSJZ_INVENTORY): boolean {
        return inventory === ZRSJZ_INVENTORY.宠物背包
            || inventory === ZRSJZ_INVENTORY.背包
            || inventory === ZRSJZ_INVENTORY.保险箱
            || inventory === ZRSJZ_INVENTORY.卡包
            || inventory === ZRSJZ_INVENTORY.弹药
            || inventory === ZRSJZ_INVENTORY.武器_枪
            || inventory === ZRSJZ_INVENTORY.武器_头盔
            || inventory === ZRSJZ_INVENTORY.武器_防弹衣
            || inventory === ZRSJZ_INVENTORY.武器_背包
            || inventory === ZRSJZ_INVENTORY.武器_刀;
    }

    public static IsPropOwnedByActivePlayer(prop: ZRSJZ_PropData): boolean {
        if (!this.IsPlayerInventory(prop.CurInventory)) return true;
        return (prop.OwnerPlayerIndex ?? 0) === this._activePlayerIndex;
    }

    public static AddPropByName(propName: string, count: number = 1): string {
        const config = ZRSJZ_PROP_CONFIG.get(propName);
        if (!config) return "";
        const data = ZRSJZ_GameData.Instance;
        const propID = this.GetPropID();
        const prop = new ZRSJZ_PropData();
        prop.InstanceID = propID;
        prop.Name = propName;
        prop.PropType = config.PropType;
        prop.CurInventory = ZRSJZ_INVENTORY.仓库_全部;
        prop.UnitPrice = config.UnitPrice;
        prop.MaxCount = config.MaxCount;
        prop.CurCount = count;
        prop.Width = Number(config.GridType[2]);
        prop.Height = Number(config.GridType[0]);
        prop.GridData = [this.CreateEmptyGridData(), this.CreateEmptyGridData()];
        data.PropData[propID] = prop;
        ZRSJZ_GameData.SaveData();
        return propID;
    }

    /**
     * 按道具名称向综合仓库增加指定总数量，并按配置的最大堆叠数自动拆分。
     * 返回本次创建的实例 ID；名称不存在或数量无效时返回空数组。
     */
    public static AddPropsToWarehouseByName(propName: string, totalCount: number = 1): string[] {
        const normalizedName = typeof propName === "string" ? propName.trim() : "";
        const normalizedCount = Math.floor(Number(totalCount));
        const config = ZRSJZ_PROP_CONFIG.get(normalizedName);
        if (!config || !Number.isFinite(normalizedCount) || normalizedCount <= 0) return [];

        const maxCount = Math.max(1, Math.floor(Number(config.MaxCount) || 1));
        const createdIDs: string[] = [];
        let remaining = normalizedCount;
        while (remaining > 0) {
            const stackCount = Math.min(maxCount, remaining);
            const propID = this.AddPropByName(normalizedName, stackCount);
            if (!propID) break;
            createdIDs.push(propID);
            remaining -= stackCount;
        }

        if (createdIDs.length > 0) this.NotifyInventoryChanged();
        return createdIDs;
    }

    public static AddAmmoToWarehouse(ammoName: string, totalCount: number): string[] {
        const config = ZRSJZ_PROP_CONFIG.get(ammoName);
        if (!config || config.PropType !== "弹药") return [];
        const data = ZRSJZ_GameData.Instance;
        const createdIDs: string[] = [];
        let remaining = Math.max(0, Math.floor(totalCount));
        while (remaining > 0) {
            const stackCount = Math.min(ZRSJZ_AMMO_MAX_COUNT, remaining);
            const propID = this.AddPropByName(ammoName, stackCount);
            const prop = data.PropData[propID];
            if (prop) {
                prop.CurInventory = ZRSJZ_INVENTORY.仓库_全部;
                prop.CurCount = stackCount;
                prop.MaxCount = ZRSJZ_AMMO_MAX_COUNT;
            }
            createdIDs.push(propID);
            remaining -= stackCount;
        }
        if (createdIDs.length > 0) this.NotifyInventoryChanged();
        return createdIDs;
    }

    public static RemovePropID(propID: string): void {
        const data = ZRSJZ_GameData.Instance;
        if (!data.PropData.hasOwnProperty(propID)) return;
        delete data.PropData[propID];
        this.RemoveLoadoutReference(propID);
        this.RefreshRoomCardIDs(0);
        this.RefreshRoomCardIDs(1);
        this.NotifyInventoryChanged();
    }

    public static SetWeaponry(weaponryIndex: number, weaponryID: string, playerIndex: number = this._activePlayerIndex): void {
        const normalizedPlayerIndex = playerIndex === 1 ? 1 : 0;
        const weaponryIDs = this.GetWeaponryIDs(normalizedPlayerIndex);
        if (weaponryIDs[weaponryIndex] === weaponryID) return;
        weaponryIDs[weaponryIndex] = weaponryID;
        ZRSJZ_GameData.SaveData();
        ZRSJZ_EventManager.EmitPersist(
            ZRSJZ_MyEvent.ZRSJZ_LOADOUT_CHANGE,
            normalizedPlayerIndex,
        );
    }

    public static SetAmmoID(ammoID: string[], playerIndex: number = this._activePlayerIndex): void {
        const data = ZRSJZ_GameData.Instance;
        const normalizedIDs = ammoID.slice(0, 6);
        while (normalizedIDs.length < 6) normalizedIDs.push("");
        if (playerIndex === 1) data.Player2AmmoID = normalizedIDs;
        else data.AmmoID = normalizedIDs;
        ZRSJZ_GameData.SaveData();
    }

    /**
     * 用助战礼包完整替换指定玩家的枪、头盔、防弹衣、背包和六格弹药。
     * 原装备实例不会销毁，而是解除玩家归属后等待放回仓库；近战武器保持不变。
     * replacedPropIDs 用于返回被替换的实例，由调用方完成格子放置和满仓邮件兜底。
     */
    public static ApplyAssistFightingGift(
        gift: Readonly<ZRSJZ_AssistFightingGiftConfig>,
        playerIndex: number = this._activePlayerIndex,
        replacedPropIDs?: string[],
    ): boolean {
        const normalizedPlayerIndex = playerIndex === 1 ? 1 : 0;
        const equipment = [
            { name: gift.WeaponName, type: "枪", slot: 0, inventory: ZRSJZ_INVENTORY.武器_枪 },
            { name: gift.HelmetName, type: "头盔", slot: 1, inventory: ZRSJZ_INVENTORY.武器_头盔 },
            { name: gift.ArmorName, type: "防弹衣", slot: 2, inventory: ZRSJZ_INVENTORY.武器_防弹衣 },
            { name: gift.BackpackName, type: "背包", slot: 3, inventory: ZRSJZ_INVENTORY.武器_背包 },
        ] as const;
        const ammoConfig = ZRSJZ_PROP_CONFIG.get(gift.AmmoName);
        if (
            equipment.some(item => ZRSJZ_PROP_CONFIG.get(item.name)?.PropType !== item.type)
            || ammoConfig?.PropType !== "弹药"
        ) {
            console.error("[ZRSJZ_InventoryService] 助战礼包存在无效装备配置", gift);
            return false;
        }

        const data = ZRSJZ_GameData.Instance;
        const weaponryIDs = this.GetWeaponryIDs(normalizedPlayerIndex);
        const ammoIDs = this.GetAmmoIDs(normalizedPlayerIndex);
        const replacedIDs = new Set<string>([
            ...weaponryIDs.slice(0, 4),
            ...ammoIDs,
        ].filter(Boolean));
        replacedIDs.forEach(propID => {
            this.ReturnPropToWarehouse(propID);
            if (replacedPropIDs && !replacedPropIDs.includes(propID)) {
                replacedPropIDs.push(propID);
            }
        });

        for (const item of equipment) {
            const propID = this.AddPropByName(item.name, 1);
            const prop = data.PropData[propID];
            if (!prop) return false;
            this.PlaceAssistGiftProp(prop, item.inventory, 0, 0, normalizedPlayerIndex);
            weaponryIDs[item.slot] = propID;
        }

        const stackCount = Math.max(0, Math.min(6, Math.floor(gift.AmmoStackCount || 0)));
        const newAmmoIDs: string[] = [];
        for (let index = 0; index < stackCount; index++) {
            const propID = this.AddPropByName(gift.AmmoName, ZRSJZ_AMMO_MAX_COUNT);
            const prop = data.PropData[propID];
            if (!prop) return false;
            this.PlaceAssistGiftProp(
                prop,
                ZRSJZ_INVENTORY.弹药,
                index % 3,
                Math.floor(index / 3),
                normalizedPlayerIndex,
            );
            newAmmoIDs.push(propID);
        }
        while (newAmmoIDs.length < 6) newAmmoIDs.push("");
        if (normalizedPlayerIndex === 1) data.Player2AmmoID = newAmmoIDs;
        else data.AmmoID = newAmmoIDs;

        ZRSJZ_EventManager.EmitPersist(
            ZRSJZ_MyEvent.ZRSJZ_LOADOUT_CHANGE,
            normalizedPlayerIndex,
        );
        this.NotifyInventoryChanged();
        return true;
    }

    /**
     * 将三种礼包弹药装备到指定玩家的六格弹药栏。
     * 每种 120 发会按单格 60 发拆成两组，不依赖全局活动玩家，
     * 因此双人模式下不会改动另一名玩家的弹药。
     */
    public static ApplyAmmoGift(
        ammoNames: readonly string[],
        countPerAmmo: number,
        playerIndex: number = this._activePlayerIndex,
        replacedPropIDs?: string[],
    ): boolean {
        const normalizedPlayerIndex = playerIndex === 1 ? 1 : 0;
        const normalizedNames = ammoNames.slice(0, 3);
        const totalPerAmmo = Math.max(0, Math.floor(countPerAmmo));
        if (
            normalizedNames.length !== 3
            || new Set(normalizedNames).size !== 3
            || totalPerAmmo <= 0
            || normalizedNames.some(name => ZRSJZ_PROP_CONFIG.get(name)?.PropType !== "弹药")
        ) {
            console.error("[ZRSJZ_InventoryService] 弹药大礼包配置无效", ammoNames, countPerAmmo);
            return false;
        }

        const stackCountPerAmmo = Math.ceil(totalPerAmmo / ZRSJZ_AMMO_MAX_COUNT);
        if (stackCountPerAmmo * normalizedNames.length > 6) {
            console.error("[ZRSJZ_InventoryService] 弹药大礼包超出六格弹药栏容量");
            return false;
        }

        const data = ZRSJZ_GameData.Instance;
        const replacedIDs = new Set(
            this.GetAmmoIDs(normalizedPlayerIndex).filter(Boolean),
        );
        replacedIDs.forEach(propID => {
            this.ReturnPropToWarehouse(propID);
            if (replacedPropIDs && !replacedPropIDs.includes(propID)) {
                replacedPropIDs.push(propID);
            }
        });

        const newAmmoIDs: string[] = [];
        for (const ammoName of normalizedNames) {
            let remaining = totalPerAmmo;
            while (remaining > 0) {
                const count = Math.min(ZRSJZ_AMMO_MAX_COUNT, remaining);
                const propID = this.AddPropByName(ammoName, count);
                const prop = data.PropData[propID];
                if (!prop) return false;
                const slotIndex = newAmmoIDs.length;
                this.PlaceAssistGiftProp(
                    prop,
                    ZRSJZ_INVENTORY.弹药,
                    slotIndex % 3,
                    Math.floor(slotIndex / 3),
                    normalizedPlayerIndex,
                );
                newAmmoIDs.push(propID);
                remaining -= count;
            }
        }
        while (newAmmoIDs.length < 6) newAmmoIDs.push("");
        if (normalizedPlayerIndex === 1) data.Player2AmmoID = newAmmoIDs;
        else data.AmmoID = newAmmoIDs;

        this.NotifyInventoryChanged();
        return true;
    }

    public static ChangePropGridPos(propID: string, index: number, x: number, y: number, isRotate?: boolean): void {
        const prop = ZRSJZ_GameData.Instance.PropData[propID];
        if (!prop?.GridData?.[index]) return;
        prop.GridData[index].GridX = x;
        prop.GridData[index].GridY = y;
        if (isRotate !== undefined) prop.GridData[index].IsRotate = isRotate;
        ZRSJZ_GameData.SaveData();
    }

    public static MovePropToInventory(
        propID: string,
        inventory: ZRSJZ_INVENTORY,
        gridIndex: number,
        x: number,
        y: number,
        isRotate?: boolean,
        playerIndex: number = this._activePlayerIndex,
    ): void {
        const prop = ZRSJZ_GameData.Instance.PropData[propID];
        if (!prop?.GridData?.[gridIndex]) return;
        prop.CurInventory = inventory;
        prop.OwnerPlayerIndex = this.IsPlayerInventory(inventory)
            ? (playerIndex === 1 ? 1 : 0)
            : -1;
        for (const gridData of prop.GridData) {
            gridData.GridX = -1;
            gridData.GridY = -1;
        }
        prop.GridData[gridIndex].GridX = x;
        prop.GridData[gridIndex].GridY = y;
        if (isRotate !== undefined) prop.GridData[gridIndex].IsRotate = isRotate;
        this.RefreshRoomCardIDs(0);
        this.RefreshRoomCardIDs(1);
        this.NotifyInventoryChanged();
    }

    public static IsWarehouseUnlocked(inventory: ZRSJZ_INVENTORY): boolean {
        return true;
    }

    public static UnlockWarehouse(inventory: ZRSJZ_INVENTORY): boolean {
        const warehouses = [
            ZRSJZ_INVENTORY.仓库_装备,
            ZRSJZ_INVENTORY.仓库_武器,
            ZRSJZ_INVENTORY.仓库_弹药,
            ZRSJZ_INVENTORY.仓库_物品,
        ];
        if (!warehouses.includes(inventory) || this.IsWarehouseUnlocked(inventory)) return false;
        const data = ZRSJZ_GameData.Instance;
        if (!data.UnlockedWarehouses) data.UnlockedWarehouses = [ZRSJZ_INVENTORY.仓库_全部];
        data.UnlockedWarehouses.push(inventory);
        this.NotifyInventoryChanged();
        return true;
    }

    public static GetEquippedRoomCardID(roomCardName: string, playerIndex: number = this._activePlayerIndex): string {
        if (!roomCardName) return "";
        const data = ZRSJZ_GameData.Instance;
        return Object.keys(data.PropData).find(propID => {
            const prop = data.PropData[propID];
            return prop?.Name === roomCardName
                && (prop.PropType === "房卡" || prop.PropType === "门禁卡")
                && prop.CurInventory === ZRSJZ_INVENTORY.卡包
                && (prop.OwnerPlayerIndex ?? 0) === playerIndex;
        }) ?? "";
    }

    public static HasEquippedRoomCard(roomCardName: string, playerIndex: number = this._activePlayerIndex): boolean {
        return this.GetEquippedRoomCardID(roomCardName, playerIndex) !== "";
    }

    public static ConsumeEquippedRoomCard(roomCardName: string, playerIndex: number = this._activePlayerIndex): boolean {
        const roomCardID = this.GetEquippedRoomCardID(roomCardName, playerIndex);
        if (!roomCardID) return false;
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP, roomCardID);
        delete ZRSJZ_GameData.Instance.PropData[roomCardID];
        this.RefreshRoomCardIDs(playerIndex);
        this.NotifyInventoryChanged();
        return true;
    }

    public static GetInventoryTotalValue(
        inventories: readonly ZRSJZ_INVENTORY[],
        playerIndex: number = this._activePlayerIndex,
    ): number {
        const inventorySet = new Set(inventories);
        return Object.values(ZRSJZ_GameData.Instance.PropData).reduce((total, prop) =>
            inventorySet.has(prop.CurInventory)
                && (!this.IsPlayerInventory(prop.CurInventory)
                    || (prop.OwnerPlayerIndex ?? 0) === playerIndex)
                ? total + prop.UnitPrice * prop.CurCount
                : total,
            0);
    }

    public static RemoveInventoryRows(inventory: ZRSJZ_INVENTORY, removedRows: number[]): void {
        if (removedRows.length === 0) return;
        const gridIndex = inventory === ZRSJZ_INVENTORY.仓库_全部 ? 0 : 1;
        for (const prop of Object.values(ZRSJZ_GameData.Instance.PropData)) {
            if (prop.CurInventory !== inventory) continue;
            const gridData = prop.GridData[gridIndex];
            if (!gridData || gridData.GridY < 0) continue;
            gridData.GridY -= removedRows.filter(row => row < gridData.GridY).length;
        }
        ZRSJZ_GameData.SaveData();
    }

    public static ReloadPropData(): void {
        const data = ZRSJZ_GameData.Instance;
        for (const propID in data.PropData) {
            const inventory = data.PropData[propID].CurInventory;
            if (inventory === ZRSJZ_INVENTORY.背包 || inventory === ZRSJZ_INVENTORY.宠物背包 || inventory === ZRSJZ_INVENTORY.物资) {
                delete data.PropData[propID];
            }
        }
        ZRSJZ_GameData.SaveData();
    }

    public static GetPropCountByName(propName: string): number {
        return Object.values(ZRSJZ_GameData.Instance.PropData).reduce((count, prop) =>
            prop.Name === propName ? count + prop.CurCount : count,
            0);
    }

    public static ConsumeProp(propName: string, count: number = 1): boolean {
        if (this.GetPropCountByName(propName) < count) return false;
        const data = ZRSJZ_GameData.Instance;
        for (const propID in data.PropData) {
            const prop = data.PropData[propID];
            if (prop.Name !== propName) continue;
            if (count < prop.CurCount) {
                prop.CurCount -= count;
                count = 0;
                break;
            }
            count -= prop.CurCount;
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_SELL_PROP, propID);
            this.RemoveLoadoutReference(propID);
            delete data.PropData[propID];
        }
        this.RefreshRoomCardIDs(0);
        this.RefreshRoomCardIDs(1);
        this.NotifyInventoryChanged();
        return count === 0;
    }

    public static AddAllProp(): void {
        for (const propName of ZRSJZ_PROP_CONFIG.keys()) this.AddPropByName(propName);
    }

    public static AddAllAmmo(count: number): void {
        for (const name of ["1级子弹", "2级子弹", "3级子弹", "4级子弹", "5级子弹", "6级子弹"]) {
            this.AddPropByName(name, count);
        }
    }

    private static GetPropID(): string {
        const data = ZRSJZ_GameData.Instance;
        data.PropID++;
        ZRSJZ_GameData.SaveData();
        return `ZRSJZ_PropID_${data.PropID}`;
    }

    private static CreateEmptyGridData(): ZRSJZ_GridData {
        const gridData = new ZRSJZ_GridData();
        gridData.IsRotate = false;
        gridData.GridX = -1;
        gridData.GridY = -1;
        return gridData;
    }

    private static ReturnPropToWarehouse(propID: string): void {
        const prop = ZRSJZ_GameData.Instance.PropData[propID];
        if (!prop) return;
        prop.CurInventory = ZRSJZ_INVENTORY.仓库_全部;
        prop.OwnerPlayerIndex = -1;
        prop.SourceBoxID = "";
        for (const gridData of prop.GridData ?? []) {
            gridData.GridX = -1;
            gridData.GridY = -1;
        }
    }

    private static PlaceAssistGiftProp(
        prop: ZRSJZ_PropData,
        inventory: ZRSJZ_INVENTORY,
        gridX: number,
        gridY: number,
        playerIndex: number,
    ): void {
        prop.CurInventory = inventory;
        prop.OwnerPlayerIndex = playerIndex;
        prop.SourceBoxID = "";
        for (const gridData of prop.GridData ?? []) {
            gridData.GridX = -1;
            gridData.GridY = -1;
        }
        if (prop.GridData?.[1]) {
            prop.GridData[1].GridX = gridX;
            prop.GridData[1].GridY = gridY;
            prop.GridData[1].IsRotate = false;
        }
    }

    private static RefreshRoomCardIDs(playerIndex: number): void {
        const roomCardIDs = ["低级房卡", "中级房卡", "高级房卡"]
            .map(roomCardName => this.GetEquippedRoomCardID(roomCardName, playerIndex));
        if (playerIndex === 1) ZRSJZ_GameData.Instance.Player2RoomCard = roomCardIDs;
        else ZRSJZ_GameData.Instance.RoomCard = roomCardIDs;
    }

    private static RemoveLoadoutReference(propID: string): void {
        const changedPlayers = new Set<number>();
        for (const playerIndex of [0, 1]) {
            const weaponryIDs = this.GetWeaponryIDs(playerIndex);
            const ammoIDs = this.GetAmmoIDs(playerIndex);
            for (let index = 0; index < weaponryIDs.length; index++) {
                if (weaponryIDs[index] === propID) {
                    weaponryIDs[index] = "";
                    changedPlayers.add(playerIndex);
                }
            }
            for (let index = 0; index < ammoIDs.length; index++) {
                if (ammoIDs[index] === propID) ammoIDs[index] = "";
            }
        }
        changedPlayers.forEach(playerIndex => {
            ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_LOADOUT_CHANGE, playerIndex);
        });
    }

    private static NotifyInventoryChanged(): void {
        ZRSJZ_EventManager.EmitPersist(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE);
        ZRSJZ_GameData.SaveData();
    }

}

import { FormatMoney } from "../ZRSJZ_NumberFormat";
import { ZRSJZ_InventoryService } from "../Service/ZRSJZ_InventoryService";
import { ZRSJZ_AccountService } from "../Service/ZRSJZ_AccountService";
import { _decorator, Component, EventTouch, find, Label, Node, Sprite } from 'cc';
import { ZRSJZ_Panel } from './ZRSJZ_Panel';
import { ZRSJZ_ShopStats } from '../UI/ZRSJZ_ShopStats';
import { ZRSJZ_UIManager } from '../Manager/ZRSJZ_UIManager';
import { ZRSJZ_INVENTORY, ZRSJZ_PANEL, ZRSJZ_PROP_CONFIG, ZRSJZ_PROP_PROPERTY, ZRSJZ_PROP_PROPERTY_MAX } from '../ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../ZRSJZ_GameData';
import { ZRSJZ_Tools } from '../ZRSJZ_Tools';
import { ZRSJZ_Inventory } from '../UI/ZRSJZ_Inventory';
import { ZRSJZ_InventoryWeaponry } from '../UI/ZRSJZ_InventoryWeaponry';
import { ZRSJZ_AudioManager } from '../Manager/ZRSJZ_AudioManager';
import { ZRSJZ_TaskService } from "../Service/ZRSJZ_TaskService";
const { ccclass, property } = _decorator;

@ccclass('ZRSJZ_PropPanel')
export class ZRSJZ_PropPanel extends ZRSJZ_Panel {
    Name: Label = null;
    PropGrid: Sprite = null;
    PropIcon: Sprite = null;
    Price: Label = null;
    PropDesc1: Node = null;
    PropDesc2: Node = null;
    PropProperty: Node = null;
    LoadBtn: Node = null;
    UnloadBtn: Node = null;
    ReplaceBtn: Node = null;
    SellBtn: Node = null;

    private _propPropertyMap: Map<string, ZRSJZ_ShopStats> = new Map<string, ZRSJZ_ShopStats>();
    private _propID: string = "";
    private _showVersion: number = 0;
    private _isOperating: boolean = false;

    protected onLoad(): void {
        this.Name = find("Panel/PropName", this.node).getComponent(Label);
        this.PropGrid = find("Panel/PropGrid", this.node).getComponent(Sprite);
        this.PropIcon = find("Panel/PropGrid/PropIcon", this.node).getComponent(Sprite);
        this.Price = find("Panel/PropPrice/Price", this.node).getComponent(Label);
        this.PropDesc1 = find("Panel/描述1", this.node);
        this.PropDesc2 = find("Panel/描述2", this.node);
        this.PropProperty = find("Panel/属性", this.node);
        this.LoadBtn = find("Panel/Buttons/装备", this.node);
        this.UnloadBtn = find("Panel/Buttons/卸下", this.node);
        this.ReplaceBtn = find("Panel/Buttons/替换", this.node);
        this.SellBtn = find("Panel/Buttons/出售", this.node);

        this.PropProperty.getChildByName("Layout").children.forEach(child => {
            const shopStats = child.getComponent(ZRSJZ_ShopStats);
            shopStats.Init();
            this._propPropertyMap.set(child.name, shopStats);
        });
    }

    Show(...args: any[]) {
        this.PlayerIndex = args[1] === 1
            ? 1
            : args[1] === 0
                ? 0
                : ZRSJZ_InventoryService.GetActivePlayerIndex();
        super.Show();
        this.ShowProp(args[0], args[2] === true);
    }

    async ShowProp(propIDOrName: string, forceReadOnly: boolean = false) {
        const propData = ZRSJZ_GameData.Instance.PropData[propIDOrName];
        const propName = propData?.Name ?? propIDOrName;
        const propConfig = ZRSJZ_PROP_CONFIG.get(propName);
        if (!propConfig) {
            console.error("没找到道具Id或配置:", propIDOrName);
            ZRSJZ_UIManager.Instance.HidePlayerPanel(ZRSJZ_PANEL.道具弹窗, this.PlayerIndex);
            return;
        }

        const isConfigPreview = !propData;
        const isReadOnly = forceReadOnly || isConfigPreview;
        this._propID = propIDOrName;
        this._isOperating = false;
        const showVersion = ++this._showVersion;
        this.Name.string = propName;
        this.Price.string = FormatMoney(isConfigPreview ? propConfig.UnitPrice : propData.UnitPrice * propData.CurCount,);
        if (ZRSJZ_PROP_PROPERTY.has(propName)) {
            //有属性
            this.PropDesc1.active = true;
            this.PropDesc2.active = false;
            this.PropProperty.active = true;
            //显示desc
            find("Desc", this.PropDesc1).getComponent(Label).string = `${propConfig.Description}`;
            //显示属性
            const propProperty = ZRSJZ_PROP_PROPERTY.get(propName);
            for (const [key, propStats] of this._propPropertyMap) {
                if (propProperty.hasOwnProperty(key)) {
                    propStats.Show(propProperty[key], ZRSJZ_PROP_PROPERTY_MAX.get(key))
                } else {
                    propStats.Hide();
                }
            }
        } else {
            this.PropDesc1.active = false;
            this.PropDesc2.active = true;
            this.PropProperty.active = false;
            find("Desc", this.PropDesc2).getComponent(Label).string = `${propConfig.Description}`;
        }
        //显示按钮
        if (isReadOnly) {
            this.LoadBtn.active = false;
            this.UnloadBtn.active = false;
            this.ReplaceBtn.active = false;
            this.SellBtn.active = false;
        } else if (propConfig.PropType == "物品" || propConfig.PropType == "弹药") {
            this.LoadBtn.active = false;
            this.UnloadBtn.active = false;
            this.ReplaceBtn.active = false;
            this.SellBtn.active = !ZRSJZ_UIManager.IsBattle;
        } else {
            const isLockedEquipment = propData.CurInventory === ZRSJZ_INVENTORY.武器_刀
                || (
                    ZRSJZ_UIManager.IsBattle
                    && propData.CurInventory === ZRSJZ_INVENTORY.武器_背包
                );
            if (isLockedEquipment) {
                this.LoadBtn.active = false;
                this.UnloadBtn.active = false;
                this.ReplaceBtn.active = false;
                this.SellBtn.active = false;
            } else {
                const weaponryIDs = ZRSJZ_InventoryService.GetWeaponryIDs(
                    this.PlayerIndex === 1 ? 1 : 0,
                );
                const weaponIndex = ZRSJZ_Tools.GetWeaponryIndexByType(propConfig.PropType);
                const equippedID = weaponryIDs[weaponIndex];
                const equippedProp = ZRSJZ_GameData.Instance.PropData[equippedID];
                const expectedInventory = this.GetWeaponryInventory(propConfig.PropType);
                if (
                    equippedID
                    && (
                        !equippedProp
                        || equippedProp.CurInventory !== expectedInventory
                        || (equippedProp.OwnerPlayerIndex ?? 0) !== this.PlayerIndex
                    )
                ) {
                    // 装备已卸下但旧存档仍保留 ID 时，在展示按钮前立即纠正。
                    ZRSJZ_InventoryService.SetWeaponry(
                        weaponIndex,
                        "",
                        this.PlayerIndex,
                    );
                }
                const isLoading = weaponryIDs[weaponIndex] === propIDOrName;
                this.UnloadBtn.active = isLoading;
                const isHaveWeapon = weaponryIDs[weaponIndex] != "";
                this.LoadBtn.active = !isLoading && !isHaveWeapon;
                this.ReplaceBtn.active = !isLoading && isHaveWeapon;
                this.SellBtn.active = !ZRSJZ_UIManager.IsBattle;
            }
        }

        const [gridSpriteFrame, propSpriteFrame] = await Promise.all([
            ZRSJZ_UIManager.Instance.GetPropGridUI(`${propConfig.Quality}1_2`),
            ZRSJZ_UIManager.Instance.GetPropUI(propName),
        ]);
        if (
            showVersion !== this._showVersion
            || this._propID !== propIDOrName
            || !this.node.active
        ) return;
        this.PropGrid.spriteFrame = gridSpriteFrame;
        this.PropIcon.spriteFrame = propSpriteFrame;
        ZRSJZ_Tools.ScaleNodeToFit(this.PropIcon.node, 269 - 30, 132 - 30);
    }

    async OnButtonClick(event: EventTouch) {
        if (ZRSJZ_UIManager.Dragging) return;
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "Mask":
                this.ClosePanel();
                break;
            case "卸下":
                await this.UnloadProp();
                break;
            case "装备":
                await this.EquipProp(false);
                break;
            case "替换":
                await this.EquipProp(true);
                break;
            case "出售":
                await this.SellProp();
                ZRSJZ_UIManager.Instance.ShowCurrencyEffect();
                break;
        }
    }

    private ClosePanel() {
        this._showVersion++;
        ZRSJZ_UIManager.Instance.HidePlayerPanel(ZRSJZ_PANEL.道具弹窗, this.PlayerIndex);
    }

    private GetWeaponryInventory(propType: string): ZRSJZ_INVENTORY {
        const inventories = [
            ZRSJZ_INVENTORY.武器_枪,
            ZRSJZ_INVENTORY.武器_头盔,
            ZRSJZ_INVENTORY.武器_防弹衣,
            ZRSJZ_INVENTORY.武器_背包,
            ZRSJZ_INVENTORY.武器_刀,
        ];
        return inventories[ZRSJZ_Tools.GetWeaponryIndexByType(propType)];
    }

    private async EquipProp(isReplace: boolean) {
        if (this._isOperating) return;
        const propData = ZRSJZ_GameData.Instance.PropData[this._propID];
        if (!propData) return;

        const inventoryType = this.GetWeaponryInventory(propData.PropType);
        const inventory = (await ZRSJZ_UIManager.Instance.GetInventory(
            inventoryType,
            this.PlayerIndex,
            ZRSJZ_UIManager.IsBattle,
        ))?.getComponent(ZRSJZ_InventoryWeaponry);
        if (!inventory) {
            console.error("装备栏尚未初始化:", inventoryType);
            return;
        }
        await inventory.ShowForPlayer(inventoryType, this.PlayerIndex);

        this._isOperating = true;
        try {
            const success = isReplace
                ? await inventory.ReplaceProp(this._propID)
                : await inventory.ChangeGrid(this._propID);
            if (success) this.ClosePanel();
        } finally {
            this._isOperating = false;
        }
    }

    private async UnloadProp() {
        if (this._isOperating) return;
        const propData = ZRSJZ_GameData.Instance.PropData[this._propID];
        if (!propData) return;

        const weaponryInventory = (await ZRSJZ_UIManager.Instance.GetInventory(
            propData.CurInventory,
            this.PlayerIndex,
            ZRSJZ_UIManager.IsBattle,
        ))?.getComponent(ZRSJZ_InventoryWeaponry);
        if (!weaponryInventory) return;
        await weaponryInventory.ShowForPlayer(propData.CurInventory, this.PlayerIndex);

        this._isOperating = true;
        try {
            if (ZRSJZ_UIManager.IsBattle) {
                const backpack = (await ZRSJZ_UIManager.Instance.GetInventory(
                    ZRSJZ_INVENTORY.背包,
                    this.PlayerIndex,
                    true,
                ))?.getComponent(ZRSJZ_Inventory);
                if (!backpack) return;

                // 由背包先完成容量、旋转和整理判断；成功转移后装备栏才会被清空。
                const hasEnoughGridCount = backpack.HasEnoughEmptyGridCount(this._propID);
                const success = await backpack.TryReceiveProp(
                    propData.CurInventory,
                    this._propID,
                    true,
                );
                if (!success) {
                    ZRSJZ_UIManager.Instance.ShowTip(
                        hasEnoughGridCount
                            ? "装备无法存放"
                            : "背包空间不足，无法卸下装备",
                    );
                    return;
                }
                this.ClosePanel();
                return;
            }

            const targetInventory = ZRSJZ_Tools.GetInventoryByPropType(propData.PropType);
            if (!targetInventory) return;
            const categoryInventory = (await ZRSJZ_UIManager.Instance.GetInventory(targetInventory))
                ?.getComponent(ZRSJZ_Inventory);
            let storedInventory = targetInventory;
            let isStored = await categoryInventory?.TryReceiveProp(
                propData.CurInventory,
                this._propID,
                false,
            ) ?? false;
            if (!isStored && targetInventory !== ZRSJZ_INVENTORY.仓库_全部) {
                const mainInventory = (await ZRSJZ_UIManager.Instance.GetInventory(
                    ZRSJZ_INVENTORY.仓库_全部,
                ))?.getComponent(ZRSJZ_Inventory);
                isStored = await mainInventory?.TryReceiveProp(
                    propData.CurInventory,
                    this._propID,
                    false,
                ) ?? false;
                storedInventory = ZRSJZ_INVENTORY.仓库_全部;
            }
            if (!isStored) {
                ZRSJZ_UIManager.Instance.ShowTip("仓库空间不足，无法卸下装备");
                return;
            }
            await this.RefreshWarehouseInventories(storedInventory);
            this.ClosePanel();
        } finally {
            this._isOperating = false;
        }
    }

    private async SellProp() {
        if (this._isOperating) return;
        const propData = ZRSJZ_GameData.Instance.PropData[this._propID];
        if (!propData) return;

        this._isOperating = true;
        try {
            // 先等待各库存清理节点，避免删除数据后异步刷新仍访问该道具。
            for (const inventoryNode of ZRSJZ_UIManager.Instance.GetAllInventoryNodes()) {
                const inventory = inventoryNode.getComponent(ZRSJZ_Inventory);
                if (inventory?.Grids.some(row => row.includes(this._propID))) {
                    await inventory.RemoveProp(this._propID);
                }
            }
            ZRSJZ_TaskService.CompleteTask("出售任意物品", propData.CurCount);
            ZRSJZ_AccountService.ChangeGold(ZRSJZ_InventoryService.GetPropSellValue(propData));
            ZRSJZ_InventoryService.RemovePropID(this._propID);
            this.ClosePanel();
        } finally {
            this._isOperating = false;
        }
    }

    private async RefreshWarehouseInventories(targetInventory: ZRSJZ_INVENTORY) {
        const inventories = [ZRSJZ_INVENTORY.仓库_全部, targetInventory];
        for (const inventoryType of inventories) {
            const inventory = ZRSJZ_UIManager.Instance.InventoryMap
                .get(inventoryType)?.getComponent(ZRSJZ_Inventory);
            if (inventory) await inventory.ShowPropItem();
        }
    }

}

import { FormatMoney } from "../../../73_ZRSJZ/Scripts/ZRSJZ_NumberFormat";
import { _decorator, Button, Color, Event, find, Graphics, isValid, Label, Layout, Node, ScrollView, Sprite, SpriteFrame, UITransform, Vec2 } from 'cc';
import { EDITOR } from 'cc/env';
import { ZRSJZ_Panel } from '../../../73_ZRSJZ/Scripts/Panel/ZRSJZ_Panel';
import { ZRSJZ_PANEL, ZRSJZ_PET_GENE_CONFIG, ZRSJZ_PetGeneType } from '../../../73_ZRSJZ/Scripts/ZRSJZ_Constant';
import { ZRSJZ_PetService } from '../../../73_ZRSJZ/Scripts/Service/ZRSJZ_PetService';
import { ZRSJZ_UIManager } from '../../../73_ZRSJZ/Scripts/Manager/ZRSJZ_UIManager';
import { ZRSJZ_AudioManager } from '../../../73_ZRSJZ/Scripts/Manager/ZRSJZ_AudioManager';
import { ZRSJZ_MyEvent } from '../../../73_ZRSJZ/Scripts/Manager/ZRSJZ_EventManager';
import { ZRSJZ_Tools } from '../../../73_ZRSJZ/Scripts/ZRSJZ_Tools';
const { ccclass, property, executeInEditMode } = _decorator;

@ccclass('ZRSJZ_PetGenePanel')
@executeInEditMode
export class ZRSJZ_PetGenePanel extends ZRSJZ_Panel {
    @property(SpriteFrame) HPSF: SpriteFrame = null;
    @property(SpriteFrame) DefenseSF: SpriteFrame = null;
    @property(SpriteFrame) AttackSF: SpriteFrame = null;
    @property(SpriteFrame) AttackSpeedSF: SpriteFrame = null;
    @property(SpriteFrame) SkillSF: SpriteFrame = null;
    @property(SpriteFrame) BackpackSF: SpriteFrame = null;
    @property(SpriteFrame) GoldSF: SpriteFrame = null;

    private _petName = "";
    private _selectedLevel = 1;
    private _iconRequest = 0;
    private _skillIconRequest = 0;
    private readonly _skillFrames = new Map<string, SpriteFrame>();
    private _learning = false;
    private _eventNode: Node = null;
    private _tree: Node = null;
    private _scroll: ScrollView = null;
    private readonly _nodes = new Map<number, Node>();

    protected onLoad(): void {
        this.BuildTree();
        if (EDITOR) this.PreviewGenes();
    }

    protected onEnable(): void {
        if (EDITOR) return;
        this._eventNode = ZRSJZ_UIManager.Instance?.node ?? null;
        this._eventNode?.on(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE, this.Refresh, this);
        this._eventNode?.on(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE, this.Refresh, this);
        this._eventNode?.on(ZRSJZ_MyEvent.ZRSJZ_PET_GENE_CHANGE, this.Refresh, this);
    }

    protected onDisable(): void {
        ++this._iconRequest;
        ++this._skillIconRequest;
        if (isValid(this._eventNode, true)) {
            this._eventNode.off(ZRSJZ_MyEvent.ZRSJZ_INVENTORY_CHANGE, this.Refresh, this);
            this._eventNode.off(ZRSJZ_MyEvent.ZRSJZ_CURRENCY_CHANGE, this.Refresh, this);
            this._eventNode.off(ZRSJZ_MyEvent.ZRSJZ_PET_GENE_CHANGE, this.Refresh, this);
        }
        this._eventNode = null;
    }

    Show(petName: string): void {
        super.Show();
        this._petName = petName;
        this.BuildTree();
        this.SelectNext();
    }

    private GetFrame(type: ZRSJZ_PetGeneType): SpriteFrame {
        return {
            "生命值": this.HPSF, "防御": this.DefenseSF, "攻击": this.AttackSF,
            "攻速": this.AttackSpeedSF, "技能": this.SkillSF, "背包": this.BackpackSF
        }[type];
    }

    /** 供MCP在预制体编辑模式预览，不读写玩家存档。 */
    public PreviewGenes(learnedLevel: string = "0", selectedLevel: string = "", materialCount: string = "0"): void {
        if (!EDITOR) return;
        this.BuildTree();
        const learned = Math.max(0, Number(learnedLevel) || 0);
        this._selectedLevel = Number(selectedLevel) || Math.min(learned + 1, ZRSJZ_PET_GENE_CONFIG.length);
        this.RenderTree(learned);
        const gene = ZRSJZ_PET_GENE_CONFIG.find(item => item.Level === this._selectedLevel) ?? ZRSJZ_PET_GENE_CONFIG[0];
        this.SetLabel("效果", ZRSJZ_PetService.GetGeneEffectText("星核幼龙", gene));
        this.SetLabel("Tip", "学习消耗：" + gene.CostProp);
        this.SetLabel("消耗道具数量", gene.CostProp === "金币" ? FormatMoney(Number(materialCount)) + "/" + FormatMoney(gene.CostCount, true) : materialCount + "/" + gene.CostCount);
        const count = find("Panel/消耗道具数量", this.node)?.getComponent(Label);
        if (count) count.color = Number(materialCount) >= gene.CostCount ? new Color(40, 180, 55) : new Color(230, 65, 55);
        this.SetLabel("学习/tip", "学习");
        find("Panel/已学习", this.node).active = gene.Level <= learned;
        find("Panel/学习", this.node).active = gene.Level > learned;
        const icon = find("Panel/Icon", this.node)?.getComponent(Sprite);
        if (icon) { icon.sizeMode = Sprite.SizeMode.CUSTOM; icon.spriteFrame = this.GetFrame(gene.Type); }
        this._scroll?.scrollToLeft(0);
    }

    private BuildTree(): void {
        const scrollNode = find("Panel/Ganes", this.node) ?? find("Panel/Genas", this.node);
        this._scroll = scrollNode?.getComponent(ScrollView) ?? null;
        const content = scrollNode && find("View/Content", scrollNode);
        this._tree = content?.getChildByName("Gane") ?? null;
        if (!this._tree) return;
        if (this._scroll) {
            this._scroll.content = content;
            this._scroll.horizontal = true;
            this._scroll.vertical = false;
            this._scroll.cancelInnerEvents = true;
        }
        const template = this._tree.getChildByName("Lv1");
        if (!template) return;
        this._nodes.clear();
        // 两行基因每五级汇合；随配置扩展宽度，末级也可滚动到。
        const width = Math.ceil(ZRSJZ_PET_GENE_CONFIG.length / 5) * 540 + 100;
        const layout = content.getComponent(Layout);
        if (layout) layout.enabled = false;
        content.getComponent(UITransform).setContentSize(width, 450);
        this._tree.getComponent(UITransform).setContentSize(width, 450);
        this._tree.setPosition(width / 2, 0, 0);
        const background = this._tree.getComponent(Sprite);
        if (background) background.enabled = false;
        for (const gene of ZRSJZ_PET_GENE_CONFIG) {
            let node = this._tree.getChildByName("Lv" + gene.Level);
            // 编辑器中不能instantiate场景节点，否则副本会沿用原节点的编辑器ID。
            if (EDITOR && node && node !== template && node.uuid === template.uuid) {
                node.removeFromParent();
                node.destroy();
                node = null;
            }
            if (!node) {
                node = new Node("Lv" + gene.Level);
                node.layer = template.layer;
                node.setParent(this._tree);
                node.addComponent(UITransform).setContentSize(116, 116);
                node.addComponent(Sprite);
                const labelNode = new Node("lv");
                labelNode.layer = template.layer;
                labelNode.setParent(node);
                labelNode.setPosition(0, -43.894, 0);
                const label = labelNode.addComponent(Label);
                const source = template.getChildByName("lv").getComponent(Label);
                label.font = source.font;
                label.useSystemFont = source.useSystemFont;
                label.fontFamily = source.fontFamily;
                label.fontSize = source.fontSize;
                label.lineHeight = source.lineHeight;
                label.color = source.color;
                label.isBold = source.isBold;
                label.enableOutline = source.enableOutline;
                label.outlineColor = source.outlineColor;
                label.outlineWidth = source.outlineWidth;
            }
            node.active = true;
            const slot = (gene.Level - 1) % 5;
            const group = Math.floor((gene.Level - 1) / 5);
            const x = -width / 2 + 80 + group * 540 + [0, 198, 0, 198, 366][slot];
            node.setPosition(x, [160, 160, -150, -150, 5][slot], 0);
            const sprite = node.getComponent(Sprite);
            if (sprite) {
                sprite.sizeMode = Sprite.SizeMode.CUSTOM;
                sprite.spriteFrame = this.GetFrame(gene.Type) ?? sprite.spriteFrame;
            }
            const label = node.getChildByName("lv")?.getComponent(Label);
            if (label) label.string = "lv." + gene.Level;
            this._nodes.set(gene.Level, node);
            if (!EDITOR) this.BindButton(node);
        }
        for (const node of this._tree.children) {
            if (/^Lv\d+$/.test(node.name) && !this._nodes.has(Number(node.name.slice(2)))) node.active = false;
        }
        this.DrawBranches();
        // 选中素材为实心黄底，放在图标下层形成光圈，不能盖住基因图标。
        this._tree.getChildByName("选中")?.setSiblingIndex(1);
        this.FitLabel("效果", 34, 281, 90);
        this.FitLabel("Tip", 30, 420, 45);
        find("Panel/Tip", this.node)?.setPosition(518, 33, 0);
        this.FitLabel("消耗道具数量", 28, 120, 38);
        this.FitLabel("学习/tip", 40, 220, 63);
        if (!EDITOR) {
            this.BindButton(find("Panel/关闭", this.node));
            this.BindButton(find("Panel/学习", this.node));
        }
    }

    private FitLabel(path: string, fontSize: number, width: number, height: number): void {
        const label = find("Panel/" + path, this.node)?.getComponent(Label);
        if (!label) return;
        label.overflow = Label.Overflow.SHRINK;
        label.fontSize = fontSize;
        label.lineHeight = fontSize + 4;
        label.getComponent(UITransform).setContentSize(width, height);
    }

    private DrawBranches(): void {
        let node = this._tree.getChildByName("基因连线");
        if (!node) { node = new Node("基因连线"); node.layer = this._tree.layer; node.setParent(this._tree); }
        node.setSiblingIndex(0);
        const graphics = node.getComponent(Graphics) ?? node.addComponent(Graphics);
        graphics.clear();
        const line = (a: number, b: number, curve: boolean) => {
            const start = this._nodes.get(a)?.position;
            const end = this._nodes.get(b)?.position;
            if (!start || !end) return;
            for (const outline of [true, false]) {
                graphics.lineWidth = outline ? 24 : 16;
                graphics.strokeColor = outline ? Color.WHITE : new Color(167, 234, 163);
                graphics.moveTo(start.x, start.y);
                if (curve) {
                    const mid = (start.x + end.x) / 2;
                    graphics.bezierCurveTo(mid, start.y, mid, end.y, end.x, end.y);
                } else graphics.lineTo(end.x, end.y);
                graphics.stroke();
            }
        };
        for (let first = 1; first <= ZRSJZ_PET_GENE_CONFIG.length; first += 5) {
            line(first, first + 1, false);
            line(first + 2, first + 3, false);
            line(first, first + 2, false);
            line(first + 1, first + 3, false);
            line(first + 1, first + 4, true);
            line(first + 3, first + 4, true);
            line(first + 4, first + 5, true);
            line(first + 4, first + 7, true);
        }
    }

    private BindButton(node: Node): void {
        if (!node) return;
        const button = node.getComponent(Button) ?? node.addComponent(Button);
        // 统一代码绑定，避免旧预制体点击事件重复触发。
        button.clickEvents = [];
        node.off(Button.EventType.CLICK, this.OnButtonClick, this);
        node.on(Button.EventType.CLICK, this.OnButtonClick, this);
    }

    private SelectNext(): void {
        const learned = ZRSJZ_PetService.GetPetGrade(this._petName);
        this._selectedLevel = ZRSJZ_PET_GENE_CONFIG.find(gene => gene.Level > learned)?.Level
            ?? ZRSJZ_PET_GENE_CONFIG[ZRSJZ_PET_GENE_CONFIG.length - 1]?.Level ?? 1;
        this.Refresh();
        const node = this._nodes.get(this._selectedLevel);
        if (node && this._scroll?.content) {
            const viewWidth = this._scroll.node.getComponent(UITransform).width;
            const width = this._scroll.content.getComponent(UITransform).width;
            const x = node.position.x + this._tree.position.x - viewWidth / 2;
            this._scroll.scrollToOffset(new Vec2(Math.max(0, Math.min(width - viewWidth, x)), 0), 0.2);
        }
    }

    private RenderTree(learned: number): void {
        const reminderLevel = !EDITOR && ZRSJZ_PetService.GetGeneLearnError(this._petName, learned + 1) === ""
            ? learned + 1 : 0;
        for (const [level, node] of this._nodes) {
            const tip = node.getChildByName("红点");
            for (const sprite of node.getComponentsInChildren(Sprite)) {
                sprite.grayscale = sprite.node === tip ? false : level > learned;
            }
            // 编辑器保留红点可见以便调整；运行时只显示材料充足的下一等级。
            if (tip && !EDITOR) tip.active = level === reminderLevel;
        }
        const selector = this._tree?.getChildByName("选中");
        const selected = this._nodes.get(this._selectedLevel);
        if (selector) {
            selector.active = !!selected;
            if (selected) {
                selector.setPosition(selected.position);
                selector.getComponent(UITransform)?.setContentSize(132, 132);
            }
        }
    }

    private SetLabel(path: string, text: string): void {
        const label = find("Panel/" + path, this.node)?.getComponent(Label);
        if (label) label.string = text;
    }

    private Refresh(): void {
        if (EDITOR || !this._petName || !isValid(this.node, true)) return;
        const iconRequest = ++this._skillIconRequest;
        const gene = ZRSJZ_PetService.GetGeneConfig(this._petName, this._selectedLevel);
        if (!gene) return;
        const learned = ZRSJZ_PetService.GetPetGrade(this._petName);
        this.RenderTree(learned);
        for (const base of ZRSJZ_PET_GENE_CONFIG) {
            if (base.Type === "技能") {
                void this.RefreshSkillIcon(this._nodes.get(base.Level)?.getComponent(Sprite), base.Level, iconRequest);
            }
        }
        const isLearned = ZRSJZ_PetService.CheckPet(this._petName) && gene.Level <= learned;
        this.SetLabel("效果", ZRSJZ_PetService.GetGeneEffectText(this._petName, gene));
        this.SetLabel("Tip", "学习消耗：" + gene.CostProp);
        const available = ZRSJZ_PetService.GetGeneCostOwned(gene);
        this.SetLabel("消耗道具数量", gene.CostProp === "金币" ? FormatMoney(Number(available)) + "/" + FormatMoney(gene.CostCount, true) : available + "/" + gene.CostCount);
        const count = find("Panel/消耗道具数量", this.node)?.getComponent(Label);
        if (count) count.color = available >= gene.CostCount ? new Color(40, 180, 55) : new Color(230, 65, 55);
        find("Panel/已学习", this.node).active = isLearned;
        const learn = find("Panel/学习", this.node);
        learn.active = !isLearned;
        learn.getComponent(Button).interactable = !this._learning;
        this.SetLabel("学习/tip", "学习");
        const icon = find("Panel/Icon", this.node)?.getComponent(Sprite);
        if (icon) { icon.sizeMode = Sprite.SizeMode.CUSTOM; icon.spriteFrame = this.GetFrame(gene.Type); icon.grayscale = false; }
        if (gene.Type === "技能") void this.RefreshSkillIcon(icon, gene.Level, iconRequest);
        void this.RefreshCostIcon(gene.CostProp);
    }

    private async RefreshSkillIcon(icon: Sprite, level: number, request: number): Promise<void> {
        if (!icon) return;
        icon.sizeMode = Sprite.SizeMode.CUSTOM;
        // 按基因解锁等级匹配技能，不能使用基因节点序号作为技能槽位。
        const skill = [0, 1, 2, 3].map(index => ZRSJZ_PetService.GetSkill(this._petName, index))
            .find(item => item?.Unlock === "基因" && item.GeneLevel === level);
        if (!skill) { icon.spriteFrame = this.SkillSF; return; }
        const path = `Sprites/宠物/技能/${this._petName}/${skill.Name}`;
        const cached = this._skillFrames.get(path);
        if (isValid(cached)) {
            icon.spriteFrame = cached;
            return;
        }
        // 首次加载留空，后续直接使用缓存，避免刷新时闪回通用技能图标。
        icon.spriteFrame = null;
        try {
            const frame = await ZRSJZ_Tools.LoadSpriteByBundle("73_ZRSJZ_DLC", path);
            if (!isValid(this, true)) return;
            this._skillFrames.set(path, frame);
            if (isValid(this, true) && isValid(icon, true) && request === this._skillIconRequest) {
                // 只替换贴图，保留RenderTree设置的未学习灰色状态。
                icon.spriteFrame = frame;
            }
        } catch (error) { console.warn(`[ZRSJZ_PetGenePanel] 技能图标加载失败：${path}`, error); }
    }

    private async RefreshCostIcon(propName: string): Promise<void> {
        const request = ++this._iconRequest;
        const icon = find("Panel/消耗道具图标", this.node)?.getComponent(Sprite);
        if (!icon) return;
        icon.spriteFrame = null;
        try {
            const frame = propName === "金币" ? this.GoldSF : await ZRSJZ_UIManager.Instance?.GetPropUI(propName);
            if (!isValid(this, true) || !isValid(icon, true) || request !== this._iconRequest || !frame) return;
            icon.sizeMode = Sprite.SizeMode.CUSTOM;
            icon.spriteFrame = frame;
            const { width, height } = frame.originalSize;
            const scale = Math.min(85 / Math.max(width, 1), 85 / Math.max(height, 1));
            icon.getComponent(UITransform).setContentSize(width * scale, height * scale);
        } catch (error) { console.warn("[ZRSJZ_PetGenePanel] 消耗图标加载失败", error); }
    }

    public OnButtonClick(event: Button | Event): void {
        const node = event instanceof Button ? event.node : event.target as Node;
        ZRSJZ_AudioManager.Instance?.PlaySound("点击");
        if (node.name === "关闭" || node.name === "Mask") { ZRSJZ_UIManager.Instance?.HidePanel(ZRSJZ_PANEL.宠物基因弹窗); return; }
        if (/^Lv\d+$/.test(node.name)) { this._selectedLevel = Number(node.name.slice(2)); this.Refresh(); return; }
        if (node.name !== "学习" || this._learning) return;
        this._learning = true;
        try {
            const error = ZRSJZ_PetService.TryLearnGene(this._petName, this._selectedLevel);
            if (error) ZRSJZ_UIManager.Instance?.ShowTip(error);
            else this.SelectNext();
        } finally { this._learning = false; this.Refresh(); }
    }
}

import { ZRSJZ_BoxroomService } from "../../../73_ZRSJZ/Scripts/Service/ZRSJZ_BoxroomService";
import { ZRSJZ_AccountService } from "../../../73_ZRSJZ/Scripts/Service/ZRSJZ_AccountService";
import {
    _decorator,
    AudioClip,
    EventTouch,
    instantiate,
    Label,
    Node,
    Prefab,
    Sprite,
    SpriteFrame,
    UITransform,
    Vec3
} from 'cc';
import { ZRSJZ_Panel } from '../../../73_ZRSJZ/Scripts/Panel/ZRSJZ_Panel';
import { ZRSJZ_UIManager } from '../../../73_ZRSJZ/Scripts/Manager/ZRSJZ_UIManager';
import {
    ZRSJZ_GRID_TYPE,
    ZRSJZ_PANEL,
    ZRSJZ_PROP_CONFIG,
    ZRSJZ_PROP_QUALITY
} from '../../../73_ZRSJZ/Scripts/ZRSJZ_Constant';
import { ZRSJZ_GameData } from '../../../73_ZRSJZ/Scripts/ZRSJZ_GameData';
import { ZRSJZ_AudioManager } from '../../../73_ZRSJZ/Scripts/Manager/ZRSJZ_AudioManager';
import { BundleManager } from 'db://assets/Scripts/Framework/Managers/BundleManager';
import {
    FormatMysteryBoxValue,
    ZRSJZ_MYSTERY_BOX_AUDIO_LEAD_TIME,
    ZRSJZ_MYSTERY_BOX_CELL_SIZE,
    ZRSJZ_MYSTERY_BOX_CONFIG,
    ZRSJZ_MYSTERY_BOX_FRAME_PADDING,
    ZRSJZ_MYSTERY_BOX_QUALITY_RANK,
    ZRSJZ_MYSTERY_BOX_REVEAL_DURATION,
    ZRSJZ_MysteryBoxConfig,
    ZRSJZ_MysteryBoxType
} from '../ZRSJZ_MysteryBoxConstant';
import { ZRSJZ_MysteryBoxSmallBox } from '../ZRSJZ_MysteryBoxSmallBox';
const { ccclass } = _decorator;

type ZRSJZ_MysteryBoxReward = {
    name: string,
    value: number,
    quality: ZRSJZ_PROP_QUALITY,
    gridType: ZRSJZ_GRID_TYPE,
    column: number,
    row: number,
    width: number,
    height: number,
    node?: Node,
};

@ccclass('ZRSJZ_MysteryBoxPanel')
export class ZRSJZ_MysteryBoxPanel extends ZRSJZ_Panel {
    private _selectedType: ZRSJZ_MysteryBoxType = "普通箱";
    private _isOpening: boolean = false;
    private _itemPrefab: Prefab = null;
    private _mysterySprites: Map<string, SpriteFrame> = new Map();
    private _qualityAudios: Map<string, AudioClip> = new Map();
    private _qualityAudioPlayId: number = 0;
    private _assetTask: Promise<void> = null;

    protected onLoad(): void {
        const panel = this.node.getChildByName("Panel");
        const boxSelect = panel?.getChildByName("购买界面")?.getChildByName("物资箱选择");
        for (const type of Object.keys(ZRSJZ_MYSTERY_BOX_CONFIG) as ZRSJZ_MysteryBoxType[]) {
            boxSelect?.getChildByName(type)?.on(Node.EventType.TOUCH_END, () => {
                this.SelectBox(type);
            }, this);
        }
        panel?.getChildByName("购买界面")
            ?.getChildByName("选择按钮")
            ?.on(Node.EventType.TOUCH_END, this.ConfirmSelection, this);
    }

    public Show(...args: any[]): void {
        super.Show(...args);
        this._isOpening = false;
        this.ShowPurchasePage();
        this.SelectBox(this._selectedType);
        this.RefreshPurchasePrices();
        this.RefreshStatistics();
        this.LoadAssets();
    }

    public OnButtonClick(event: EventTouch): void {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        switch (event.getCurrentTarget().name) {
            case "返回":
                if (this._isOpening) {
                    ZRSJZ_UIManager.Instance.ShowTip("开启中，请稍后");
                    return;
                }
                if (this.IsOpeningPageVisible()) {
                    this.ShowPurchasePage();
                    this.ClearBoard();
                    this.SelectBox(this._selectedType);
                    return;
                }
                ZRSJZ_UIManager.Instance.HidePanel(ZRSJZ_PANEL.盲盒界面);
                break;
            case "开吃":
                this.OpenSelectedBox();
                break;
        }
    }

    private SelectBox(type: ZRSJZ_MysteryBoxType): void {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        this._selectedType = type;
        const purchasePage = this.node.getChildByName("Panel")?.getChildByName("购买界面");
        const boxSelect = purchasePage?.getChildByName("物资箱选择");
        const selected = boxSelect?.getChildByName("选中");
        const target = boxSelect?.getChildByName(type);
        if (selected && target) {
            selected.setPosition(target.position.x, selected.position.y, selected.position.z);
        }
    }

    private ConfirmSelection(): void {
        ZRSJZ_AudioManager.Instance.PlaySound("点击");
        const panel = this.node.getChildByName("Panel");
        const purchasePage = panel?.getChildByName("购买界面");
        const openingPage = panel?.getChildByName("开箱界面");
        if (purchasePage) purchasePage.active = false;
        if (openingPage) openingPage.active = true;
        this.RefreshOpenBoxState();
        this.ClearBoard();
        this.ResizeBoard(ZRSJZ_MYSTERY_BOX_CONFIG[this._selectedType]);
        this.SetCurrentValue(0);
        this.SetOpenButtonText("开吃");
    }

    private ShowPurchasePage(): void {
        const panel = this.node.getChildByName("Panel");
        const purchasePage = panel?.getChildByName("购买界面");
        const openingPage = panel?.getChildByName("开箱界面");
        if (purchasePage) purchasePage.active = true;
        if (openingPage) openingPage.active = false;
    }

    private IsOpeningPageVisible(): boolean {
        return this.node.getChildByName("Panel")
            ?.getChildByName("开箱界面")
            ?.active === true;
    }

    private RefreshPurchasePrices(): void {
        const boxSelect = this.node.getChildByName("Panel")
            ?.getChildByName("购买界面")
            ?.getChildByName("物资箱选择");
        for (const type of Object.keys(ZRSJZ_MYSTERY_BOX_CONFIG) as ZRSJZ_MysteryBoxType[]) {
            const priceLabel = boxSelect?.getChildByName(type)
                ?.getChildByName("价格")
                ?.getChildByName("价格文本")
                ?.getComponent(Label);
            if (priceLabel) {
                priceLabel.string = FormatMysteryBoxValue(
                    ZRSJZ_MYSTERY_BOX_CONFIG[type].price, true
                );
            }
        }
    }

    private async OpenSelectedBox(): Promise<void> {
        if (this._isOpening) {
            ZRSJZ_UIManager.Instance.ShowTip("开启中，请稍后");
            return;
        }

        const config = ZRSJZ_MYSTERY_BOX_CONFIG[this._selectedType];
        if (ZRSJZ_GameData.Instance.Gold < config.price) {
            ZRSJZ_UIManager.Instance.ShowTip("金币不足");
            return;
        }

        this._isOpening = true;
        this.SetOpenButtonText("准备中");
        await this.LoadAssets();
        if (!this._itemPrefab || this._mysterySprites.size === 0) {
            ZRSJZ_UIManager.Instance.ShowTip("盲盒资源加载失败");
            this._isOpening = false;
            this.SetOpenButtonText("开吃");
            return;
        }

        this.SetOpenButtonText("开启中");
        ZRSJZ_AccountService.ChangeGold(-config.price);

        const rewards = this.GenerateRewards(config);
        await this.BuildBoard(config, rewards);
        this.SetCurrentValue(0);

        let revealedValue = 0;
        const revealRewards = rewards.slice().sort((left, right) =>
            left.row - right.row || left.column - right.column
        );
        for (const reward of revealRewards) {
            const revealDuration =
                ZRSJZ_MYSTERY_BOX_REVEAL_DURATION[reward.quality] ?? 0.8;
            const smallBox = reward.node?.getComponent(ZRSJZ_MysteryBoxSmallBox);
            await Promise.all([
                smallBox?.Reveal(revealDuration) ?? Promise.resolve(),
                this.Wait(Math.max(
                    0,
                    revealDuration - ZRSJZ_MYSTERY_BOX_AUDIO_LEAD_TIME
                )).then(() => this.PlayQualityAudio(reward.quality)),
            ]);
            revealedValue += reward.value;
            this.SetCurrentValue(revealedValue);
        }

        const mailAwards = await this.GrantRewards(rewards);
        const hasFragments = rewards.some(reward => reward.name === "宠物碎片" || reward.name === "英雄碎片");
        const deliveryTip = mailAwards.length > 0
            ? "仓库空间不足，其余道具已发至邮件"
            : "道具已存入仓库";
        void ZRSJZ_UIManager.Instance.ShowTip(
            hasFragments ? `${deliveryTip}，碎片已计入余额` : deliveryTip,
        );
        const redCount = rewards.reduce((count, reward) =>
            count + (reward.quality === ZRSJZ_PROP_QUALITY.红色 ? 1 : 0), 0
        );
        ZRSJZ_BoxroomService.RecordMysteryBoxOpen(
            config.price,
            revealedValue,
            redCount
        );
        this.RefreshStatistics();
        this._isOpening = false;
        this.SetOpenButtonText(
            `再来一次(${FormatMysteryBoxValue(config.price, true)})`
        );
    }

    private PlayQualityAudio(quality: ZRSJZ_PROP_QUALITY): void {
        let audioName = "白绿蓝";
        switch (quality) {
            case ZRSJZ_PROP_QUALITY.紫色:
                audioName = "紫";
                break;
            case ZRSJZ_PROP_QUALITY.金色:
            case ZRSJZ_PROP_QUALITY.红色:
                audioName = "金红";
                break;
        }
        const audioClip = this._qualityAudios.get(audioName);
        if (!audioClip || !ZRSJZ_AudioManager.Instance) return;

        const originalName = audioClip.name;
        try {
            audioClip.name = `${originalName}_${++this._qualityAudioPlayId}`;
            // ZRSJZ_AudioManager.Instance.StopMusic();
            // ZRSJZ_AudioManager.Instance.PlayMusicByClip(audioClip, false, 1);

            ZRSJZ_AudioManager.Instance.PlaySoundByClip(audioClip);
        } finally {
            audioClip.name = originalName;
        }
    }

    private Wait(duration: number): Promise<void> {
        return new Promise(resolve => {
            this.scheduleOnce(() => resolve(), duration);
        });
    }

    private GenerateRewards(config: ZRSJZ_MysteryBoxConfig): ZRSJZ_MysteryBoxReward[] {
        const occupied: boolean[][] = Array.from(
            { length: config.rows },
            () => Array(config.columns).fill(false)
        );
        const totalCells = config.columns * config.rows;
        const fillRate = config.minFillRate
            + Math.random() * (config.maxFillRate - config.minFillRate);
        const targetCells = Math.max(1, Math.round(totalCells * fillRate));
        const targetValue = this.GetTargetRewardValue(config.price);
        const targetCellValue = targetValue / Math.max(1, targetCells);
        const pool = Array.from(ZRSJZ_PROP_CONFIG.values())
            .filter(prop => prop.PropType === "物品");
        const rewards: ZRSJZ_MysteryBoxReward[] = [];
        let occupiedCells = 0;
        let baseValue = 0;
        let attempts = 0;

        while (occupiedCells < targetCells && attempts++ < 300) {
            const remainingValue = Math.max(1, targetValue - baseValue);
            const prop = this.PickProp(pool, targetCellValue, remainingValue * 1.05);
            const [height, width] = this.GetGridSize(prop.GridType);
            if (occupiedCells + width * height > targetCells + 2) continue;

            const position = this.GetFirstValidPosition(occupied, width, height);
            if (!position) continue;
            this.SetOccupied(occupied, position.column, position.row, width, height);
            rewards.push({
                name: prop.Name,
                value: prop.UnitPrice,
                quality: prop.Quality,
                gridType: prop.GridType,
                column: position.column,
                row: position.row,
                width,
                height,
            });
            occupiedCells += width * height;
            baseValue += prop.UnitPrice;
        }

        if (rewards.length === 0) {
            const fallback = pool[Math.floor(Math.random() * pool.length)];
            const [height, width] = this.GetGridSize(fallback.GridType);
            rewards.push({
                name: fallback.Name,
                value: fallback.UnitPrice,
                quality: fallback.Quality,
                gridType: fallback.GridType,
                column: 0,
                row: 0,
                width,
                height,
            });
        }

        return rewards;
    }

    private PickProp(pool: any[], targetCellValue: number, maxValue: number): any {
        const affordablePool = pool.filter(prop => prop.UnitPrice <= maxValue);
        if (affordablePool.length === 0) {
            return pool.reduce((cheapest, prop) =>
                prop.UnitPrice < cheapest.UnitPrice ? prop : cheapest
            );
        }
        const sourcePool = affordablePool;
        let totalWeight = 0;
        const weighted = sourcePool.map(prop => {
            const [height, width] = this.GetGridSize(prop.GridType);
            const valuePerCell = prop.UnitPrice / Math.max(1, width * height);
            const valueDistance = Math.abs(Math.log(
                Math.max(1, valuePerCell) / Math.max(1, targetCellValue)
            ));
            const qualityRank = ZRSJZ_MYSTERY_BOX_QUALITY_RANK[prop.Quality] ?? 1;
            const weight = (1 / (1 + valueDistance * 2)) * (0.7 + qualityRank * 0.12);
            totalWeight += weight;
            return { prop, weight };
        });

        let random = Math.random() * totalWeight;
        for (const item of weighted) {
            random -= item.weight;
            if (random <= 0) return item.prop;
        }
        return weighted[weighted.length - 1].prop;
    }

    private GetTargetRewardValue(price: number): number {
        const gameData = ZRSJZ_GameData.Instance;
        const historyDifference = (gameData.MysteryBoxTotalCost ?? 0)
            - (gameData.MysteryBoxTotalValue ?? 0);
        const correction = Math.max(-price * 0.25, Math.min(price * 0.25, historyDifference * 0.1));
        return Math.max(
            price * 0.55,
            Math.floor(price * (0.70 + Math.random() * 0.60) + correction)
        );
    }

    private async BuildBoard(
        config: ZRSJZ_MysteryBoxConfig,
        rewards: ZRSJZ_MysteryBoxReward[]
    ): Promise<void> {
        const board = this.GetBoard();
        if (!board) return;
        this.ClearBoard();

        this.ResizeBoard(config);

        const itemLayer = new Node("盲盒内容");
        itemLayer.layer = board.layer;
        board.addChild(itemLayer);

        const emptySprite = this._mysterySprites.get("道具底");
        const emptySize = ZRSJZ_MYSTERY_BOX_CELL_SIZE * 0.88;
        for (let row = 0; row < config.rows; row++) {
            for (let column = 0; column < config.columns; column++) {
                const emptyNode = new Node("空格");
                emptyNode.layer = board.layer;
                itemLayer.addChild(emptyNode);
                const emptyTransform = emptyNode.addComponent(UITransform);
                const emptyImage = emptyNode.addComponent(Sprite);
                emptyImage.sizeMode = Sprite.SizeMode.CUSTOM;
                emptyImage.spriteFrame = emptySprite;
                emptyTransform.setContentSize(emptySize, emptySize);
                emptyNode.setPosition(this.GetGridPosition(
                    column,
                    row,
                    1,
                    1,
                    config.columns,
                    config.rows
                ));
            }
        }

        const initTasks: Promise<void>[] = [];
        for (const reward of rewards) {
            const itemNode = instantiate(this._itemPrefab);
            reward.node = itemNode;
            itemLayer.addChild(itemNode);

            const width = reward.width * ZRSJZ_MYSTERY_BOX_CELL_SIZE;
            const height = reward.height * ZRSJZ_MYSTERY_BOX_CELL_SIZE;
            itemNode.setPosition(this.GetGridPosition(
                reward.column,
                reward.row,
                reward.width,
                reward.height,
                config.columns,
                config.rows
            ));
            const gridName = reward.gridType.replace("_", "x");
            const gridSprite = this._mysterySprites.get(gridName);
            const component = itemNode.getComponent(ZRSJZ_MysteryBoxSmallBox);
            if (component) {
                initTasks.push(component.Init(
                    reward.name,
                    width,
                    height,
                    reward.quality,
                    reward.gridType,
                    gridSprite
                ));
            }
        }
        await Promise.all(initTasks);
    }

    private GetGridPosition(
        column: number,
        row: number,
        width: number,
        height: number,
        columns: number,
        rows: number
    ): Vec3 {
        return new Vec3(
            (column + width * 0.5 - columns * 0.5) * ZRSJZ_MYSTERY_BOX_CELL_SIZE,
            (rows * 0.5 - row - height * 0.5) * ZRSJZ_MYSTERY_BOX_CELL_SIZE,
            0
        );
    }

    private GetFirstValidPosition(
        occupied: boolean[][],
        width: number,
        height: number
    ): { column: number, row: number } | null {
        const rows = occupied.length;
        const columns = occupied[0]?.length ?? 0;

        for (let row = 0; row <= rows - height; row++) {
            for (let column = 0; column <= columns - width; column++) {
                let valid = true;
                for (let y = row; y < row + height && valid; y++) {
                    for (let x = column; x < column + width; x++) {
                        if (occupied[y][x]) {
                            valid = false;
                            break;
                        }
                    }
                }
                if (valid) return { column, row };
            }
        }
        return null;
    }

    private SetOccupied(
        occupied: boolean[][],
        column: number,
        row: number,
        width: number,
        height: number
    ): void {
        for (let y = row; y < row + height; y++) {
            for (let x = column; x < column + width; x++) {
                occupied[y][x] = true;
            }
        }
    }

    private GetGridSize(gridType: ZRSJZ_GRID_TYPE): [number, number] {
        const [height, width] = gridType.split("_").map(Number);
        return [Math.max(1, height || 1), Math.max(1, width || 1)];
    }

    private async GrantRewards(rewards: ZRSJZ_MysteryBoxReward[]) {
        const rewardCounts = new Map<string, number>();
        for (const reward of rewards) {
            rewardCounts.set(reward.name, (rewardCounts.get(reward.name) ?? 0) + 1);
        }
        return ZRSJZ_UIManager.Instance.ReceivePropAwards(
            Array.from(rewardCounts.entries()).map(([PropName, Count]) => ({ PropName, Count })),
        ).then(result => result.MailAwards);
    }

    private RefreshOpenBoxState(): void {
        this.LoadAssets().then(() => {
            const stateSprite = this.node.getChildByName("Panel")
                ?.getChildByName("开箱界面")
                ?.getChildByName("普通箱打开状态")
                ?.getComponent(Sprite);
            if (stateSprite) {
                stateSprite.spriteFrame = this._mysterySprites.get(`${this._selectedType}打开状态`);
            }
        });
    }

    private RefreshStatistics(): void {
        const openingPage = this.node.getChildByName("Panel")?.getChildByName("开箱界面");
        const statistics = openingPage?.getChildByName("统计");
        const gameData = ZRSJZ_GameData.Instance;

        const totalValue = statistics?.getChildByName("价值文本")?.getComponent(Label);
        const openCount = statistics?.getChildByName("累计开启次数")?.getComponent(Label);
        const redCount = statistics?.getChildByName("价值文本-002")?.getComponent(Label);
        if (totalValue) {
            totalValue.string = FormatMysteryBoxValue(gameData.MysteryBoxTotalValue ?? 0);
        }
        if (openCount) openCount.string = `${gameData.MysteryBoxOpenCount ?? 0}次`;
        if (redCount) redCount.string = `${gameData.MysteryBoxRedCount ?? 0}个`;
    }

    private SetCurrentValue(value: number): void {
        const label = this.node.getChildByName("Panel")
            ?.getChildByName("开箱界面")
            ?.getChildByName("本次的吃")
            ?.getChildByName("价值文本")
            ?.getComponent(Label);
        if (label) label.string = FormatMysteryBoxValue(value);
    }

    private SetOpenButtonText(text: string): void {
        const label = this.node.getChildByName("Panel")
            ?.getChildByName("开箱界面")
            ?.getChildByName("开吃")
            ?.getChildByName("文本")
            ?.getComponent(Label);
        if (label) label.string = text;
    }

    private GetBoard(): Node {
        return this.node.getChildByName("Panel")
            ?.getChildByName("开箱界面")
            ?.getChildByName("道具底框") ?? null;
    }

    private ResizeBoard(config: ZRSJZ_MysteryBoxConfig): void {
        const boardWidth = config.columns * ZRSJZ_MYSTERY_BOX_CELL_SIZE
            + ZRSJZ_MYSTERY_BOX_FRAME_PADDING;
        const boardHeight = config.rows * ZRSJZ_MYSTERY_BOX_CELL_SIZE
            + ZRSJZ_MYSTERY_BOX_FRAME_PADDING;
        this.GetBoard()?.getComponent(UITransform)?.setContentSize(boardWidth, boardHeight);
    }

    private ClearBoard(): void {
        const board = this.GetBoard();
        if (!board) return;
        const children = board.children.slice();
        board.removeAllChildren();
        children.forEach(child => child.destroy());
    }

    private LoadAssets(): Promise<void> {
        if (
            this._itemPrefab
            && this._mysterySprites.size > 0
            && this._qualityAudios.size > 0
        ) {
            return Promise.resolve();
        }
        if (this._assetTask) return this._assetTask;

        this._assetTask = Promise.all([
            new Promise<void>(resolve => {
                BundleManager.GetBundle("73_ZRSJZ_DLC").load(
                    "Prefabs/盲盒道具框",
                    Prefab,
                    (error: any, prefab: Prefab) => {
                        if (error) {
                            console.error("盲盒道具框加载失败:", error);
                        } else {
                            this._itemPrefab = prefab;
                        }
                        resolve();
                    }
                );
            }),
            new Promise<void>(resolve => {
                BundleManager.GetBundle("73_ZRSJZ_DLC").loadDir(
                    "Sprites/盲盒",
                    SpriteFrame,
                    (error: any, sprites: SpriteFrame[]) => {
                        if (error) {
                            console.error("盲盒图片加载失败:", error);
                        } else {
                            sprites.forEach(sprite => this._mysterySprites.set(sprite.name, sprite));
                        }
                        resolve();
                    }
                );
            }),
            new Promise<void>(resolve => {
                BundleManager.GetBundle("73_ZRSJZ_DLC").loadDir(
                    "Audios",
                    AudioClip,
                    (error: any, audioClips: AudioClip[]) => {
                        if (error) {
                            console.error("盲盒品质音效加载失败:", error);
                        } else {
                            audioClips.forEach(audioClip =>
                                this._qualityAudios.set(audioClip.name, audioClip)
                            );
                        }
                        resolve();
                    }
                );
            }),
        ]).then(() => undefined);
        return this._assetTask;
    }
}
